/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20101026-8","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"建設委員会","time":"午前１０時０３分～午後０時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回かなり詳細な比較調査を行ったというんですけれども、何かこういった調査を行っていく上で参考にした自治体とかはあるんですか。ほかの区とかもこういうのをやっているんか尋ねました。","respondent":"齋藤道路公園課長","answer":"今度１１月にも東京都から技術者の会議で検証結果について発表して欲しいと求められています。引き続き土木行政についてはコストを考え、事業を進めていきたいと思っています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり少しでもＣｏ２排出というのは、ぜひそこら辺は引き続き注視をして、研究していただきたいなというのがこちらの要望です。こういった調査の経費というのはどういうところから、財源といいますかね、それはどうなるのか説明を求めました。","respondent":"齋藤道路公園課長","answer":"調査の財源は、夜照度をはかりましたので、職員の超勤代ぐらいのものです。はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"じゃあ、一般財源ということなんでしょうか。財源といいますか、そちらを聞いたんですけれども。","respondent":"齋藤道路公園課長","answer":"検証したのは、職員がしました。ですから、一般の職員給与費で超勤代からということです。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"まとめとして、省エネ街路灯が理にかなうという結果が出たんですけれども、すみません、これは齋藤課長の担当だと思うんですけれども、環境課長としてはこのまとめについて、環境面から考えたらどういう意見になっていくか教えていただけますか尋ねました。","respondent":"工藤環境課長","answer":"私どももそういった部分で環境行政を進めていく上で、投資、イニシャルコストの部分があります。庁舎内、施設内におけるＬＥＤをどのようなタイミングで推進するかという部分は十分に研究してまいりたいというふうに考えているところであります。","id":"exchange-004"},{"speaker":"藤原委員","kind":"意見","question":"Ｃｏ２削減というのは世界的、そのＣｏ２削減、お金はかかるものだというのは思っているんですよ。だから、コストはかかるけれどもＣｏ２は下がるという結果は出ていても、それでもまだ時期尚早というふうに考えるのかということなんですけれどもとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"現在の水銀灯から比べると、ともに約３分の１の排出量に抑えることができる、これでほぼ同じであれば当然コスト的に安いほうを採用せざるを得ない。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"近所の方とかから、あそこまで明るいと逆に苦情とか来なかったですかというのを聞きたかったんです。あの地域で。","respondent":"齋藤道路公園課長","answer":"車のドライバーの方がまぶしいと感じられるというのは初めて聞きました。ご指摘をいただきもう１回照度については考えなきゃいけないというふうに思います。","id":"exchange-006"},{"speaker":"若林委員","kind":"意見","question":"今現在の区で導入している省エネ型とＣｏ２、例えば、それは大変にすばらしいことなんだろうというふうに評価をしたいと思います。もう一度ご答弁、どういうふうにまた検証されていくかというところを、さっきの室内とかいうのもありましたけれどもとの意見を述べました。","respondent":"齋藤道路公園課長","answer":"例えば、天王洲の開放護岸に１１基ＬＥＤの街路灯を設置しました。公園の沿道でないところに設置して、３６０度に照らすタイプのＬＥＤ証明を設置して、これはどういう効果があるか今後検証してみたいと思います。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"各清掃工場の水銀の自己規制値というんですか、実際検出された値はどれぐらいだったのか、それぞれお伺いしたいと思います。被害金額がおさまるんですけれども、足立の事故を受けて一定の予防的な対策がとられたということなのか、そこら辺もお伺いします。","respondent":"太田品川区清掃事務所長","answer":"それから、他の工場についても足立工場と同様に０.０５mg/m3という数字ということで聞いております。ただ、特別にじゃあ強化したかというと、注意はしていたと思いますが、結果的にこういう被害で済んだということが真実なのかなというふうに思います。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後の再発防止対策が重要だと思うんですが、説明があったんですけれども、ぜひ全力を尽くしていただきたいんですが、先ほどご説明していただいた今後の対策で、どの程度こういった再発の防止できるのかというのは、そこら辺についての見通しというんですかね、それはどうか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"じゃあ、やったから出ないかというところまでは正直言って私の段階では申し上げられない、大変難しいことだなと思っています。それから、２３区課長会と対策についてさらに検討していこうということで、さらに有効な再発防止策についても検討していくということであります。","id":"exchange-009"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"この水銀が入っていた可能性があるごみというのは、事業者から排出されたごみの中にあったということは確定していいんですか。普通の家庭ごみの収集ラインの中にあったというふうなルートもあり得るんか尋ねました。","respondent":"太田品川区清掃事務所長、岩田都市環境事業部長","answer":"そういう意味でいくと、この報告書にもあるように、一般家庭のことも否定はできないということ。あるいは、家庭系も考えられるだろうということで… 清掃主管部長会というのが２３区でございまして、徹底した調査と警視庁への告発を含めた厳罰を求めて対処するようにという申し入れを行っております。","id":"exchange-010"},{"speaker":"阿部副委員長","kind":"質問","question":"先ほど家庭ごみルートでもあり得るかと伺ったのは、これはエリア的にも環八ですか、分けて置いていくというようなこともまた１つあり得ることかなと。チェックだけでは多分終わらない問題ではないかと思うんですが、その辺のご認識といいますか、考え方について少し伺えればと思います。","respondent":"岩田都市環境事業部長","answer":"先ほど説明しましたように、特定はできていないんです。我々で調査できる範囲内はここまでが限界だったです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"内訳戸数の中で品川区の戸数が１２戸だということですが、あと、どんな対応をしているのか具体的にお伺いしたいなと思います。前回もやって、今回も、もうずっとやっているのかなと思うんですけれども、前回の土日の参加人数実績がわかればお伺いします。","respondent":"柏原住宅担当課長","answer":"土曜日と日曜日、荏原文化センターときゅりあんの３階交流室ですね、こちらのほうを利用いたしまして案内をしています。今回と同様の募集を行いました５月の募集の際には、荏原文化センターで２６件、きゅりあんのほうで１０件という結果になってあります。","id":"exchange-012"},{"speaker":"安藤委員","kind":"確認","question":"１２月には高齢者住宅の発表があったりするんですが、そういったことも行っているのかどうか、確認したいと思います。","respondent":"柏原住宅担当課長","answer":"基本的にはこちらのほう、都営住宅等のご案内ですので、そういったところが基本のお話にはなるんですけれども、それ以外の住宅につきましても、ご相談があった場合は区役所のこういう窓口でやっていますであるとか、そういったところのご案内はさせていただいています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ積極的に区のほうからも、困っているときにはこういう住宅制度もありますよというご案内をしていただきたいなというふうに、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"こちらに関してはどのように予想しておられるんでしょうかという点と、幾ら入っているのかということと、その算定根拠と考え方はどうなっているのかということをお伺いします。","respondent":"三宅都市開発課長","answer":"変更点といいますか、今は工事中でなかなか通りにくいというような構造がありますので、基本的には前と同じような流れであると考えております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"すみません、標準レベルの橋だと１.３億円国から補助金が来るということですと、その残ったところがグレードアップ分ということなんでしょうか。何ていうんでしょうね、グレードアップ分の内訳ですけれども、そこに関してはどこがどれぐらい負担するのかという内訳があれば説明を求めました。","respondent":"三宅都市開発課長","answer":"グレードアップ分の負担ですが、こちらは大崎駅西口南地区の再開発の組合といいますか、そこの負担をいただいているところです。例えばそういう部分でございまして、それにつきまして、そういうグレードアップ分としましては約２億円少しといったところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"そこに関しての、何ていうか、声は聞いているのか。そして、どういう対策を考えているのかお伺いします。","respondent":"岩田都市環境事業部長","answer":"道路を管理している部隊が聞いているお話は、再開発が完成した街区はゆったりとした歩道ができて、非常に安心して歩ける空間になってよかったと、こういう声は聞いておりますけれども、歩行者が危険であるというような声は私ども道路管理者のほうには来ておりません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"車両が、歩行者に対する配慮というところがやはり不十分なので、今の状態だといつ事故が起こってもおかしくないというような状況があるんですね。特に高齢者の方が多い地域でもありますので、お願いしたいと思うんですけれども、そこら辺についての考えをお伺いします。","respondent":"岩田都市環境事業部長","answer":"これは信号がついても絶対的な安全は確保できないんです、信号というのは。大井町もそうですけれども、上空でクロスして、歩行者にとっては非常に安全なまちづくりに寄与する構造物だとご理解をいただきたいと思います。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"それに対応して歩行者の安全を図っていただきたいという私の意見だし、それに対するお考えを聞いたので、お願いしたいと思います。やはり信号機があることでドライバーは運転に注意するわけですから、それは当然のことだと思いますし、ぜひやってほしいと求めました。","respondent":"岩田都市環境事業部長","answer":"信号機の設置権限は公安委員会が持っておりますので、状況を確認し、警察と順次そこら辺については検証してまいります。そういう意味で申し上げたわけです。","id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問","question":"もう１つ、ここのデッキの構造を私はうろ覚えなので伺うのですけれども、何かそのままの高さで歩道に結ばれるんでしたっけ。それとも、スロープなのか、階段なのか、どういうふうに歩道と最後着地する形になっていくか説明を求めました。","respondent":"三宅都市開発課長","answer":"これが約７メートルの高さのところから地上に接続する部分です。こちらの敷地内についてはその再開発事業の中でこのデッキを取り付けるように、建築工事と一体で整備されていくものです。","id":"exchange-020"},{"speaker":"阿部副委員長","kind":"確認","question":"やはり契約期間といったらいいですかね、確認しますけれども、動線としてはバリアフリーには今回この動線はならないんですかね。ちょっとまだ階段の横に、隣にエスカレーターもつきますとか、そういう構造ではなくて、とりあえずここでは階段のみということでよろしいか尋ねました。","respondent":"三宅都市開発課長","answer":"協定締結の実施ですが、今回の本会議で議決をいただいて、速やかに締結する予定です。ちょっと図面に表示し切れていませんが、これは西口南の再開発事業の中でエレベーターが公園のすぐのところにつける予定になっております。 ちょっとすみません。ここに階段がございまして、ここから五、六ｍ先のところにつく予定になっております。","id":"exchange-021"},{"speaker":"阿部副委員長","kind":"質問","question":"すみません、今のエレベーターの件なんですが、要は公園のほうにまたデッキが少し伸びていって、エレベーターがつくということなんでしょうかね。いつごろになるんか尋ねました。","respondent":"三宅都市開発課長","answer":"こちらの図で言うと、平面図でいきますと、薄い点線が伸びている下側ですね、ここに場所としてはつく予定でございまして、こちらは西口南地区の再開発事業の中でやりますので、一応完成の時期としては平成２５年の夏を予定しています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"提案","question":"こちらにいらっしゃる委員の皆さんの会派からも１人ずつ出ていますので様子は伺ったかと思うんですが、それはちょっと少数で、そういった様子でした。あれですかね、その条例改正は、この建設委員会で出された条例が仮にここで否決された場合はどういったことになるのか伺いますとの意見を述べました。","respondent":"三宅都市開発課長、松代都市計画課長、片田防災まちづくり事業部長","answer":"大枠を決めておりますので、住民のご意見を踏まえて十分な検討がなされるように、区としても引き続き指導してまいりたいと考えています。… 説明等ですけれども、これはご存じのように、都市計画法のほうで定められた説明会があります。地域説明会も含め… 法の縛りがありませんから、逆に言うと、できるようになってしまいます。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"それぞれこちら資料の提示がないので伺いたいんですが、まず、反対意見ということは住民の方が懸念されているということですからね。日影により教育環境の悪化が懸念されるというところに関してはどういう見解なのか、あと、それぞれどういう見解をお持ちなのかお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"じゃあ、区はどういう見解を示しているんですかというのを、それは当然知ってしかるべきだと私は思いますけれども。ですから、ぜひご答弁を、当然答弁いただけるものだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"もっと本当は多いんですから。その抜粋に関する見解。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとこれは建設委員会なんでお伺いしたいんですが、圧迫感が大きいとありますけれども、これは景観を大事にしたいという意見だと思うんです。そちらが２点目の質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問","question":"これは報告事項ですから、この報告を受けましたということですから、ここでそういう問題を審議するんではないと思うんですよ。もう打ち切っていただいていいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"私は報告事項ということがどうあるべきなのかというのは大いに議論の余地があるんじゃないかと思うんです。それが必要な報告に対して、やはり委員として、議論をしていくというのが大事だと思うんですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"こっちは、何もここに書いていないことを質問したわけじゃないんですから、ここにばっちり書いていることで質問したんですから。そこら辺は充実してほしいという意見も述べましたけれども、質問したわけで、やめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"阿部副委員長","kind":"質問","question":"よろしいですか。これはこれとして報告として伺っておき、実りある議論になるのではないかと考えていますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"市川委員","kind":"質問・要望","question":"１つだけ確認をさせていただきたいんですけれども、２週間の縦覧でこれだけ１９８通の賛成反対含めて意見が出たということなんで、かなりの何か、この再開発には関心を持っているんだなということを改めて感じているんですけれども、答申案の中にこういう意見は盛り込まれるものなんか尋ねました。","respondent":"松代都市計画課長","answer":"答申案といいますか、今回６項目の地区計画の中の要件があります。こういう審議をしたということは、正式な書面ではなくても、ちゃんと東京都のほうには伝えてあります。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"これまでの使用状況を教えていただきたいのと、デメリットというのはそれぞれどういうことがあるのか教えてほしいと求めました。あわせまして、使用していた当該の少年野球関係者さんなどからは、改修やその後の運用に当たってはどのような要望が出ているのかお伺いします。","respondent":"齋藤道路公園課長、藤橋都市整備下水道課長","answer":"現行の使用状況についてご説明申し上げます。火、水、金は朝の６時から７時半まで少年野球の方が朝練をやっていらっしゃるということです。もう１点目の野球をされている方等の声ということについてですけれども、それから、利用者の方々を交えまして意見交換を行ってまいりました。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"改善されるのかどうかということと、それはアンツーカーにしていただけないかという要望を聞いたんですけれども、それというのは今回行えないんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"本年４月に改修した後オープンしたんですけれども、雨が降った後もすぐに利用できると、大変好評いただいているところです。各ベース、塁のところとマウンドについては土で残そうといった形で配慮して、これまでよりも利便性をアップしたものというふうに区では考えています。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはどうなのかということと、塁間をアンツーカーにという要望があるんですが、それというのは行えないものなのかお伺いしたいと思います。例えば、引き続き土日使用の優先ですとか、無料による使用継続というのはどう考えていらっしゃるのかお伺いします。","respondent":"藤橋都市整備下水道課長、岩田都市環境事業部長","answer":"今回採用する予定の人工芝は八潮北も最新のタイプのものでございまして、ここでやけどをしたという事例は、私のほうでは聞いていません。人工芝にすることによって、特定の利用者がそこで独占的に使用できるという状況になりますので… 都市公園法で言う有料施設に位置づけておりますので、１回５００円ですけれども、既にそれぞれの野球連盟からは有料でずっとお使いいただく。だから、５００円をいただくと、こういうことになっております。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に要望なんですが、よく使っていた方のご意見をしっかりと伺って、全面改修するわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"阿部副委員長","kind":"質問","question":"遊戯コーナーについて幾つかお伺いします。一番下に、体験の場を検討しているということなんですけれども、この体験をするのはデザインした子どもたちを対象にということなんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"私どものほうで今考えてありますのは、デザインを提案した３０人の子どもたちと地域の子どもたちを対象にする考えです。","id":"exchange-037"},{"speaker":"阿部副委員長","kind":"質問","question":"特に、ちょっと乳幼児が安全に過ごせる遊び場スペースみたいなのをどのあたりに考えてらっしゃるのか教えてください。両方ちょっと高さがあるといいますか、ここの構造がどうなっているのかと、防犯面からどのようにお考えなのかということを説明を求めました。","respondent":"藤橋都市整備下水道課長","answer":"このテーブルベンチ工の周りにはいわゆる乳母車も置けるようなスペースも考えて、その辺を考慮して、この部分をターゲットに考えてあります。","id":"exchange-038"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"どうなんでしょうね、要望次第ではありますけれども、その辺は何かお考えになってらっしゃいますか。聞きにくいんですけれども。","respondent":"藤橋都市整備下水道課長","answer":"今のテーブルベンチ工は少し茶色で書いて丸くなっている部分の周りに点線で囲ってあって、名称は記入してございませんけれども、施設的にはいわゆる一般の公園にあるような、今委員がご指摘のようなちっちゃい幼児向け遊具を設置することも考えております。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"伺いたいことは公園のこと１件、あと、要望と、全体的な考え方等をちょっと３件伺います。それと、要望を１つ、グランドと遊戯コーナーの工事スケジュールがずれています。","respondent":"齋藤道路公園課長、藤橋都市整備下水道課長","answer":"夜間閉鎖するかどうかは、そういう考えは、一般の公園ですのでございません。〔「有料施設は閉めるんでしょう」と呼ぶ者あり〕 有料施設につきましては閉めますけれども、子どものアイディアを活かした北側部分の公園は閉める考えはありません。今説明したとおり、遊戯コーナーにつきましては２４時間ということで今考えて、管理の仕組みについて検討しています。","id":"exchange-040"},{"speaker":"渡部委員","kind":"質問・要望","question":"もうたくさん声を聞いていただいて、いい公園をどんどんつくってほしいと求めました。それは本当に一番怖いんで、もうそうならないように最大の努力をしてほしいと求めましたので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-02","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと聞きたいことが１件あります。すみません、区民の皆さんがこれ見たいなと思った場合にはどういうふうにしたら見られるのかというのをちょっとお伺いしたいのと、あと。","respondent":"原委員長","answer":"掲載場所は特にはありません。フォルダに入れて書庫にということになります。","id":"exchange-042"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"内容を東急さんから伺っていればお聞かせいただきたいなという点と、工事の完成というのは、いつごろになるのかお教えいただきたいのが２点目。いろいろなことを要望、どういう、以上３点のお答えを聞きたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"工事内容、エレベーター等の構造の件ですけれども、エレベーター設置計画の検討を現在行っている旨の報告は受けてあります。３点目につきましては、理解を十分図るよう、地元調整に万全を期すよう強く要望しています。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういうようなエレベーターをつけてほしいとか、出された案に対して地域の住民の皆さんの意見とか要望を取り入れてですとか、ですから。そういった点で、東急から受けている報告があれば教えていただきたいと思ったんですけれども、それは全くないのかということをお伺いします。","respondent":"山崎マスタープラン担当課長","answer":"下神明駅にエレベーターが設置されることによりまして、利便性の向上が図られるもの、こういうふうに認識しています。調整の仕方にもよりますけれども、そういった調整が整い次第、本委員会で内容の報告を予定しています。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"どうなっているんですか、東急さんが全く教えてくれないんですけれども、１日も早く示してほしいという要望をしているんだということでしたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"阿部副委員長","kind":"質問","question":"今スケジュール、あるいは、内容というのはまだわからないということで、それはそういう段階なんだろうなと思うんですけれども、それはいつごろになるとめどが立つというようなめどというのはあるんでしょうかね。","respondent":"松代都市計画課長","answer":"当然その間には当委員会のほうにも、今後時期を見て説明をする、そういう段階を踏んでいきたいと、このように思っております。今のところはちょっとまだそこまで行っておりませんので、今後年内の早いうちにそういったものを詰めてきたいと、このように思っているわけです。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":43986,"voices":157}},{"id":"h22-20101026-9","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"文教委員会","time":"午前１０時０２分～午後１時４４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件整理しています。","topics":[{"id":"topic-01","title":"の平成２２年特別区人事委員会勧告","agenda":"の平成２２年特別区人事委員会勧告","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"総務委員会のところとかかわるかと思いますが、若干教えていただいてもいいですか。ここで書かれているのは当然なんですけれども、品川区は、今回は４３名のところしかかかわらないんですかね。","respondent":"田村庶務課長","answer":"重要性というのは認識しているということで、副校長は管理職ですから、自分の下にいる教職員の状況についても目配りをしてくれと。早いうちに専門医療の方につなげるということで、まさに勧告の内容を早くから取り入れて、実施しているです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なところをお聞きしたかったのですが、体調を崩されている方もかなりお見受けするので、ぜひ力を入れていただきたいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"の保幼小ジョイント期カリキュラム","agenda":"の保幼小ジョイント期カリキュラム","exchanges":[{"speaker":"井上委員","kind":"質問","question":"こういう財政難の折にこういったところの視点も必要であるという観点からお聞きしますけれども、どういったところでつくられていて、これをこれからどういうところに配って使っていくようにしていくかもあわせて説明を求めました。","respondent":"冠木指導課長","answer":"私立の保育園、私立の幼稚園にも相当数を配布させていただきまして、品川区の子どもたちの支援のためにあてていただくというように考えております。全体で、すべての印刷代で２０万円前後だったと思います。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"冊子の発行数がトータルで幾らなのかということと、ちなみに教育委員会でこういった冊子をつくるときに、印刷料というのは契約がどういうふうになっているのか、これに限らず、わかれば説明を求めました。","respondent":"冠木指導課長","answer":"こういった冊子を一般につくるときの考え方としては、一般競争入札でやっております。発行部数は確認します。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"桑野先生についても、選考されるときに幼児教育も含めて、これはどうして平成２１年度は２人の先生になられて変更になっているのか。作業部会の方でも、部長として選ばれたこの方が酒井先生に変わっているわけですが、どういった状況でこのようになっているのか尋ねました。","respondent":"冠木指導課長","answer":"今年度４月の人事異動で他の区に異動しておりまして、今、第一日野小学校の幼保一体施設で仕事に取り組んでおられる酒井校長先生に入っていただいたという経過です。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"検討会の方では平成２１年度中に変更していますけれども、なぜこういった状況になったのか尋ねました。","respondent":"冠木指導課長","answer":"これは平成２１年度の委員、平成２２年度の委員という意味ですので、途中で変わったというわけではなくて、年度の切り替えのところでの変更という意味あいです。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"小学校長の代表という方は、当時１人ではなかったかなと思うんです。平成２１年度に桑野先生が初めになられていて、平成２１年度中に変わっているという表記だと思うんですがいかがか尋ねました。","respondent":"冠木指導課長","answer":"平成２１年度に変更したという事実はございません。桑野委員については平成２１年度いっぱい委員をやっていただいております。","id":"exchange-007"},{"speaker":"井上委員","kind":"確認","question":"では、小学校の校長先生は、平成２１年度は２人いらして、平成２２年度は１人に変わったという理解でよろしいのか確認をさせてください。","respondent":"冠木指導課長","answer":"平成２１年度は桑野委員と岸委員、平成２２年度は酒井委員です。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"ジョイント期にここまで細かく提供する必要があるのかというところで、子どもたちがそういうふうな状況になっているのか。どういうふうな議論の中でまとめられているのかちょっとお伺いしたいと思います。","respondent":"冠木指導課長","answer":"個に応じた対応をするとかといった努力をしておりますので、そういう意味あいにおいては、現状ございません。考え方を十分に共通理解して指導していくことで、そういった部分にも対応していけるというような考え方から、今回のカリキュラムをつくったです。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"ここに沿ってということについての議論が共有できると思うので、そういうことを考えたら、親の方にはこれをどういうふうに活用していこうとお考えか尋ねました。","respondent":"冠木指導課長","answer":"こういった部分で、保育士や教員が家庭への啓発をしていくという考え方でおります。それからもちろん、保育課で来年保護者向けのリーフレット的なものを考えているというような情報もいただいているところです。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、入学式は４月６日とかそのぐらいじゃないですか。小学校１年生になったら最低限の自立というのはあるので、そこら辺をどこまで盛り込んでいくのかなというのをお聞きしたいと思います。","respondent":"吉岡保育課長","answer":"もちろん検討委員にも入っていただいているんですけれども、活用できるものはご活用いただきたい」というような連絡をしています。ですから、区としては区立幼稚園・保育園、その内容について私立幼稚園側でもご活用いただける部分は十分にご活用いただきたいとお願いしたです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"当たり前のことですから。自立ということがどこまで入っているのかもお伺いします。","respondent":"吉岡保育課長、冠木指導課長","answer":"ただ、私立幼稚園についてはその設置主体、運営主体である幼稚園がそれぞれ行っているものですので。先ほど指導課長からもご説明したように、この辺の区の考え方をご説明しまして… 先ほど説明をしましたように、既に１４名の教員が来て、私どももそういうところで公私問わずに情報提供します。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"そこに対しての保育園側の指導というんですか、それをどのように考えているか。その人たちに対してどういうふうに考えていきますかということをお聞きして終わりにします。","respondent":"吉岡保育課長","answer":"対応がなかなか難しい親御さんたちにどう対応するのかということですが、当然個別の事情も十分斟酌しながら、きめ細かな対応を図って趣旨へのご理解をお願いしていきたいと考えております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後でまたゆっくりお伺いしたいと思っていますが、どういう方法がいいのかというのはさまざまな検討やご意見をいただきたいと思うんですね。もう１回これの生かし方というか、位置づけをお伺いしたいと思います。","respondent":"冠木指導課長","answer":"ですので、この部分を双方の保育士や教諭の現場の状況など、十分に作業部会で吟味しながらこの１冊にまとめたというような考え方です。なお、今３,０００部ということでやっておりますけれども、頒布等々につきましては意見としてお伺いしました。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"指導課というところでどちらかというと小学校の部分の教育でいろいろな問題も抱えていらっしゃるのでそっちの方が強いのかなと思ってお話を伺ってい…ちょっと大きなテーマかもしれませんけど、その辺をもう１回お聞かせいただけたらなと思います。","respondent":"冠木指導課長","answer":"遊びのことについてございましたけれども、当然、就学前の教育において遊びというものの重要性というのは私どもも認識しておりますし。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１点は、使ってみて初めて生かされるし、動きながらどんどん改善するべきところは改善していただきたいということをお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"金野委員","kind":"質問","question":"幼稚園、一つ一つすべての行動が教育の観点から子どもたちを教育するというふうに持っていく視点をまず持たなければいけないだろうと思うんですね。いわゆる５歳児はどういった生活をしてきているのか、あるいは子どもたちがどういう思いで、これからどのように先生たちにしていかれますか尋ねました。","respondent":"冠木指導課長、吉岡保育課長、若月教育長","answer":"例えば教育研修であるとかという取り組みはするんですけれども、根本のところで、一方で難しい部分もあります。若手の先生の研修で語っていただくとか… さらにのりしろの部分、具体的には５歳児のことについて、小学校の先生方とさらに進めるということで考えています。… 先ほど飯沼委員がお話しになっていましたけれども、例えば小１プロブレムの背景は何かというと、これは一言でいうことはなかなか難しいと思うんです。","id":"exchange-017"},{"speaker":"金野委員","kind":"提案","question":"その点を１点お聞きしたいのと、例えば年度末の切り替えのときに、年度年度で子どもたちの状況というのは違うと思うんです。交流を持つ時期ではないかなと思うので、そういった先生たちの情報交換の場所があったらいいのではないかなと提案をいたしますが、どうか尋ねました。","respondent":"冠木指導課長","answer":"十分に啓発に努めてまいりたいと思いますし、学校側から見た視点、両方入れた形で啓発を進めていけばいいのかなと思っているところです。そういった意味でも１園１校のつながりももちろん大事なんですけれども、もっと広い意味で、そんな取り組みをしてまいりたいと考えています。","id":"exchange-018"},{"speaker":"金野委員","kind":"提案","question":"今の質問で、これからもいろいろなところで提案をしていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認したいのは、効果の測定をするのかどうかですね。６５ページに１つの姿を示しているわけだから、「しっかり学ぶしながわっこ」の将来的な見直し等があればということを説明を求めました。","respondent":"冠木指導課長","answer":"それから２点目の検証につきましては、実は説明をする中で、今年の１月からモデル実施をやりました。これはまだまだモデル実施ですので、これについてもいろいろと精査しながらよりよいものにしていきたいなと思っているところです。","id":"exchange-020"}]},{"id":"topic-03","title":"の品川地区幼保一体施設の概要","agenda":"の品川地区幼保一体施設の概要","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今回、平成２３年４月から御殿山幼稚園がここを使うということで、御殿山幼稚園の子どもたちにとって、ここに来て何か変わることはあるんか尋ねました。","respondent":"吉岡保育課長","answer":"幼保一体施設ということになりますので、従来に比べまして０歳から３歳の保育園児も同じ幼保一体施設の中に入って保育等行うという形になります。５歳児だけで完結しておりましたところ、０歳から３歳の、そのように考えております。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"幼保一体型のところに幼稚園ということは、預かり保育も行うということで、給食体系は、御殿山幼稚園の子どもたちはどのようにこれから進めようとしているんか尋ねました。","respondent":"吉岡保育課長","answer":"給食につきましては、従来の幼保一体施設と同様に、週２回程度の給食の体験、それから預かり保育につきましても給食の提供を予定しています。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"今回は給食が週２回提供されることになって、お弁当を持ってきて預かり保育をするというような、その辺をしっかりとどういう体系で進めようとしているのかお伺いします。","respondent":"吉岡保育課長","answer":"浜川幼稚園の方は、単独の幼稚園ですから給食の施設がございません。その中での預かり保育の場合については、必要であればお弁当をご持参いただくというように考えています。","id":"exchange-023"},{"speaker":"井上委員","kind":"確認","question":"そこのところの確認と、そういう子どもたちと幼保一体施設で預かりになった子どもたちの関係というのは、どういうふうに整理をしていこうと考えていますか。","respondent":"吉岡保育課長","answer":"幼稚園に上がるときには、保育園の３歳児クラスを１５人で考えてありますので、その１５人は希望すれば幼稚園に入れるという形です。延長が必要であれば１９時半まで延長するわけですけれども、それは運営の形態の中で、それは運営の中で適切に考えてまいります。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"適切に、これからの検討ということでしたけれども、今まで保育園として通っていた人たちは給食が提供される。そこの給食の提供というのがどういうふうな基準でされるのかというのは、その整理が保護者の方にはよくわからないと思うんですがいかがか尋ねました。","respondent":"吉岡保育課長","answer":"基本的に幼稚園の預かり保育をするお子さんは、就労支援のためにお預かりをするですので、当然給食の提供を考えております。ただし、就労していない親御さんのお子さんについては、週２回程度の給食以外はお弁当を持参していただくという考え方です。","id":"exchange-025"},{"speaker":"井上委員","kind":"意見","question":"二葉の方は、子どもの人数の関係かもしれないんですけれども、「明日、預かり保育をお願いしたい。１週間前とかでないと食材の都合でできませんということで、園のやり方ですというのか、区としてこういう方針を持っていますというのがあるのかとの意見を述べました。","respondent":"吉岡保育課長","answer":"二葉と台場でやり方が違うというお話ですけれども、実際の運営の中で若干違う部分はあるかと思いますが、それぞれの園で運営していますので、二葉の方が台場のことで混乱するということはないのかなと考えています。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"どういう考えで選択をするのかというのを一つお伺いしたいのと、４、保育園のところは０歳から３歳までですよね。この辺はどういうふうになるのか説明を求めました。","respondent":"吉岡保育課長","answer":"５歳の幼稚園があって、幼保連携型で０歳から５歳の保育園と４歳と５歳の幼稚園という並列型にすることで、待機児の解消に努めたという経過です。御殿山幼稚園が再開発完了後に戻った後の保育園ですけれども、教育的要素を備えた保育園という形で考えております。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３歳で後の行き場が突然なくなってしまったときにどうするのかなと思っていたので、そのまま保育園ということですね。図面を大分前に見たんですけれども、ここのところの給食はどこでつくるのか、ちょっと教えてほしいと求めました。","respondent":"吉岡保育課長","answer":"給食につきましては、ほかの幼保一体施設や保育園と同様ですけれども、施設内の厨房でつくるということになります。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"施設内の厨房でということですけれども、幼稚園部分の預かり保育を希望される方のところも、学校の方じゃなくてそこでつくるということか尋ねました。","respondent":"吉岡保育課長","answer":"ご指摘のとおりでございまして、幼稚園の就労支援の預かり保育の給食につきましても、同じ幼保一体施設の厨房でつくります。","id":"exchange-029"},{"speaker":"金野委員","kind":"質問","question":"関連なんですが、まずそこからお聞きします。そのときに保育園は０歳から５歳までの保育園になりますよということは、この「幼」という部分はどうなるんか尋ねました。","respondent":"吉岡保育課長","answer":"残った施設は保育園になろうかなと考えていますので、基本的には幼保一体施設ではなくなってしまうです。検討の余地はあろうかと思うんですけれども、基本的には０歳から５歳の保育園というように考えているところなので、残った保育園の方は。","id":"exchange-030"},{"speaker":"金野委員","kind":"質問","question":"ということは、今の事業開始は６月１日なので、そのときまでは幼保一体施設の幼稚園と保育園で、そののちは保育園だけになるということでいいか尋ねました。","respondent":"古川子ども未来事業部長","answer":"そのときに私は、本会議でもご説明申し上げたんですが、必ずしも幼保一体施設というようには申し上げられなかったんですね。まだ今後の検討の問題ですが、そこに何らかの形での施設ができる、それはまた将来の課題です。","id":"exchange-031"},{"speaker":"金野委員","kind":"質問","question":"そうすると、今、この２つの保育園と幼稚園ですから、園長先生は２人いらっしゃるということの理解でいいでしょうか。それが１点と、それと同じような考え方で、いわゆる預かり保育料というものを設定するのか尋ねました。","respondent":"吉岡保育課長","answer":"それから保育園園長、それと幼保一体施設全体を統括する施設長に幼稚園長か保育園長のどちらかがなるということになろうかと考えています。預かり保育につきましては、幼稚園の教育時間にプラスするサービス提供になりますので、別途、預かり保育料を徴収する予定です。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"これは何年ぐらいまでここにいるんですか。これから何をどういうふうにするのか、将来的にはこういうことを想定した形で今いろいろやっているんだとか、そこら辺どう考えているんか尋ねました。","respondent":"吉岡保育課長","answer":"４歳児、施設としての保育・教育の内容は、教育内容・保育内容が保育園化してしまうというのは必ずしも当たらないのではないかなと考えております。","id":"exchange-033"},{"speaker":"西本委員","kind":"意見","question":"４歳、５歳で見ると、中身は一緒ですよということなんだろうと思うんです。だからそこの部分はきちんと、保護者がそういう話をしているかどうかわからないんですが、その辺はどうされますかとの意見を述べました。","respondent":"吉岡保育課長","answer":"それから通常幼稚園に入られる就労なさっていない、あるいはパートに出るぐらいの方と、ご家庭の状況でもちろん違うのは事実です。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"先ほど質問したときに、御殿山幼稚園が北品川の再開発エリアに戻った後も、すこやか園で進んでいくという前提で質問をしていたんです。平成２６年に北品川第二保育園ということになるだろうという前提を決定したのは、ここはちょっと明確にしていただかないと、お知らせください。","respondent":"吉岡保育課長","answer":"こちらの品川地区に幼保一体施設をつくるという話は、そういう形ではご説明していなかったと思います。平成２６年度の見込みですけれども、まだ今後検討する内容ですので、今現在では。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"もう一つ、平成２６年の中で検討する内容であるということは、どういうことを検討して、どういうふうに結果を導こうとしているのか。どういうものかというものかはまだわかりませんとおっしゃる、先でなきゃわからないではなくて、ちょっと明確にしていただきたい。","respondent":"古川子ども未来事業部長","answer":"しかし一定、御殿山幼稚園を母体にし、そこに新設の保育園をつけた幼保一体施設を平成２３年６月からやっていこうというものの考え方です。当然その上の４、５歳というものは考えていくだろうということは、保育園的なものは当然に考えざるを得ないだろうです。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"今後の動向の具体的なものというのは、どういうものなのか説明を求めました。","respondent":"古川子ども未来事業部長","answer":"私が考えておりますのは、あるいは保育園、そういったことが考えられると思います。何らかの別な要素がありますが、少なくとも御殿山幼稚園が移転した後に、新設の幼稚園は入れませんと考えています。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"今の部長のご答弁で、幼稚園がなくなった部分の後については難しいというところ、もうちょっとそこのところを説明を求めました。","respondent":"古川子ども未来事業部長","answer":"新たに区立幼稚園を増やす考えはございませんので、必然的に保育園型の４歳、５歳児を含めた施設になるだろう。現時点での考え方で申し上げますと、保育園として教育内容を充実したものをやっていくこともあるだろう、このように考えています。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"認定こども園制度とか、まだよく中身が伝わってこないんですけれども、すごく微妙であるということですかね。そういうのを含めつつ、今、考えていただけているんか尋ねました。","respondent":"吉岡保育課長","answer":"今、私どもが聞いている話では、平成２３年度の通常国会の中において法律の改正をする。平成２５年度から実施されるですけれども、まだそれ以上に具体的な内容につきましては今後のことになると思います。","id":"exchange-039"}]},{"id":"topic-04","title":"の２、その他を議題に供します。 まず、(1)の所管質問","agenda":"の２、その他を議題に供します。 まず、(1)の所管質問","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"それで、その部分について具体的にどういう研修を、いつ、何回行ったのかという詳細について伺いたいと思います。この電話が入ったときに、２４時間見守りホットラインはどういう流れでつながっていくのかというところから、まずはお知らせほしいと求めました。","respondent":"安井子育て支援課長","answer":"うちの方で対応しますということなんですけれども、緊急の場合などは、こちらの方でも１１０番してくださいという場合が多いんです。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"１０月１日から開始したので、現状何件ぐらい、どういう電話が入っているのかということを、平日と夜間に分けて説明を求めました。","respondent":"安井子育て支援課長","answer":"幸いということなのかわからないんですけれども、今のところ通報は１件も入っておりません。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"児童虐待の方は子育て支援課の方に電話が行くと思うので、高齢者はちょっと置いておきまして、そちらの部分だけでお伺いします。これはだれが受けることになっているんか尋ねました。","respondent":"安井子育て支援課長","answer":"マンションのどこら辺とかという話だと、うちでも後のフォローがなかなかできませんので、そこら辺を重点的に聞かせていただくということ。ＤＶについても、ご家族から相談がある場合もありますので、そこら辺の事情についてお聞かせいただくという形になります。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"２４時間をうたうのであれば、これは効果的ではないように思うんですが、その辺についてどういう検討をされたのか。そしてどういうふうに進めていかれるのかお伺いします。","respondent":"古川子ども未来事業部長","answer":"９月１４日の文教委員会において、今お尋ねのしながわ見守りホットラインについてはご説明、ご報告申し上げたと思います。もちろん後日になる可能性は非常に大きいんですが、対応してまいりますよということでございまして、それを１０月から始めている。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"私たちは、当事者の相談のところと思っていたんですけれども、まずは気づきというところで、地域の人がどこに電話していいかわからないというところの情報収集の一つとして、この事業を始めたという考えであるということでよろしいんか尋ねました。","respondent":"安井子育て支援課長","answer":"ただいま部長からもありましたように、まさにそういうところでございまして、そういった町場の方からの連絡先がわからないというような話もあります。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"今、自分が困っているとか、そういう電話の状況というのはどういう状況にあるのか。推移とか変化があったら説明を求めました。","respondent":"安井子育て支援課長","answer":"うちもそうですし、子育て支援センターにもあるんですけれども、そういうお電話をいただくようになりました。６月の大阪の事件以来、児童相談所も同じような状況が続いているということで、職員も一生懸命頑張って対応に努めているというような話がありました。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問・要望","question":"周りからのそういう相談とともに、もしかして自分がとか、電話相談というところに助けを求めるツールとしてそれが機能しているのか。そういう本人からの声というのは、普通、電話というもので届くんか尋ねました。","respondent":"安井子育て支援課長","answer":"そこら辺で、声かけをして、もしくは家事や何かで厳しいという話であれば家事援助をお願いするツールもありますよとかといったご案内をしています。子育て支援センターでも声かけをして、そういった対応を図っているという感じです。","id":"exchange-046"},{"speaker":"金野委員","kind":"質問","question":"先ほどのご説明の中で、緊急時には１１０番をということで、通報された方が１１０番をしてくださいねという対応になってしまうんでしょうか。というのは、その先の支援の手というのはその人に「緊急時ですから１１０番してくださいね」ということではなく、場所が特定できるのであれば。","respondent":"安井子育て支援課長","answer":"その際には必ず宿直から私のところに電話が入るということで、後のフォローで情報が確認できるように対応しています。あるいはうちから重ねて警察へお話をするというような形で対応することになっております。","id":"exchange-047"},{"speaker":"金野委員","kind":"質問・要望","question":"周りの人に気づいていただくのに、堺議員が質問した内容でもお話しさせていただきましたが、早急に周知をしていただきたいなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"私たちは前回も説明を受けましたけれども、見えないのは、どういう流れでどういう処理をするんですかということなんですよ。１枚紙の資料みたいな形で示していただくと、説明しやすいし、区の方でもわかりやすいんじゃないかと思うんですがいかがか尋ねました。","respondent":"安井子育て支援課長","answer":"そこに通報の窓口をもう１本つくって、より受けやすいようにしたい。４万件とか、児童虐待についてはこれだけ言われておりますので、そこら辺について一歩踏み出して強化していこうという形で進めているです。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"じゃあ、２４時間のみんながいないときにどういう流れで情報が行って、どういうふうに処理できるんですかということを知りたいんですよね。だからそこをはっきり説明してもらえるだけで安心するんじゃないんか尋ねました。","respondent":"安井子育て支援課長","answer":"夜中の部分については、単なる情報提供であればそのまま翌朝私どものところへまわってきますので、それで対応していくという形になります。そういう形で基本的に進めます。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"基本的には、１１０番とかが必要なものについては緊急にやる、それは今までもそうだと思うんです。なので、基本的には次の日に報告を受けるという形になるという理解でいいか尋ねました。","respondent":"古川子ども未来事業部長","answer":"虐待にかかわる子育て支援課でありますとか、迅速に対応できるようなものを、目指している。今までもそれぞれの必要性に応じてすぐに対応すべきもの、あるいは翌日でいいもの、そういう仕分けはしておりました。","id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"前に危機管理対策として、職員の方が夜間の当直みたいなのをやっていましたが、今もいらっしゃるのか。今までどういう人が夜間のスタッフになっているんか尋ねました。","respondent":"安井子育て支援課長","answer":"ですから、ほかのいろいろな電話とはちょっと違う扱いをしていただくように対応できているということになります。宿直は総務課で委託しています。","id":"exchange-052"},{"speaker":"伊藤副委員長","kind":"意見","question":"聞きとった情報にまずどう関与して、そのほか別なところにおつなぎするものとか、いろいろなことがあると思うんですよ。そういう情報をどうきちっと管理して、分析・評価をして対処していく仕組みがちゃんとできていますかということ、答えてほしいと求めました。","respondent":"安井子育て支援課長","answer":"もしかすると前にもそういうことがあったということであれば間違いないのではないか、過去のことも踏まえながら対応しているというところがあります。それは全く変わりません。","id":"exchange-053"},{"speaker":"伊藤副委員長","kind":"質問","question":"いろいろな話が入ってくるでしょうから、緊急性の高いものを精選するべきであって、逆にこれからいろいろなところから情報が来るわけじゃないですか。これは補正予算ですから、来年度は予算に反映されてくると思いますから、しっかり検討してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"そうすると、区立幼稚園に行かずに、私立にも行かずに待っているという方が多いということですか。公立がだめなので私立に行っているという方が多いのか。","respondent":"伊崎待機児童対策担当課長","answer":"多くは公立の第２希望の幼稚園に入られていらっしゃるとか、第１希望の幼稚園があくのを待っていらっしゃるという方が多いと聞いています。年によってはいらっしゃったとは聞いております。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4714#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":48359,"voices":141}},{"id":"h22-20101026-5","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"総務委員会","time":"午後１時０２分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"意見","question":"補正予算の性格上、これをどう考えるか。来年度、この辺についてはどのように分析され、考えてやっていらっしゃるのかだけ聞かせてくださいとの意見を述べました。","respondent":"金子企画財政課長","answer":"高齢者世帯の２４時間対応訪問介護サービスモデル事業ですが、実施するわけでありますが、今後の対応を検討していくということがありますので。継続すべきもの、そういったものがあろうかと思いますが、それぞれ適切に判断していくことが必要かというふうに考えてあります。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"その意味で、本当のテスト試行ですから、それはそういうことだということをしっかりお伝えしておかなければいけないという部分が残るのです。お知らせしておいたほうが、みんな安心感があるという問題がありますので、その辺はよろしくお願いをしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"３９ページのここに豊町二丁目の用地取得の規模など、概要だけ教えていただきたい。","respondent":"金子企画財政課長","answer":"これは住所で見ますと豊町二丁目５番１８号で、ちょうど戸越公園の南側のあたりに位置いたします。広さは約１３０m2になります。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"この第７１号議案全体を通しまして追加で行うものであったり、当然その４分の３は国から入ってくるんですけれども、その全体を通してとらえ方をちょっと教えていただきたいんです。","respondent":"金子企画財政課長","answer":"当初予算で予定していた実績を超えた実績があって、今回それに該当するのは児童扶養手当の部分と、それからご指摘の生活保護費の部分です。この２件になります。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"増加の原因といいますか、どういうところが傾向として増えてきているのかというのがわかったら、教えてほしいと求めました。国が始めた場合、区としてどういうふうな対応の考え方があるのかというのを、今のところ考えていることがあれば伺いたいというふうに思います。","respondent":"金子企画財政課長","answer":"４点のお尋ねですけれども、まず防犯カメラの設置の考え方であります。ただ、ある程度はっきりした時点で来年度の基本的な設定のところもまた検討する必要があるかなというふうには聞いてあります。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は国が始めたときに区がどうするかということが、区の立場というんですか、考え方というのが問われてくるんじゃないかというふうに思います。そこら辺で何か考え方があったら伺いたいと思いますが、いかがか尋ねました。","respondent":"金子企画財政課長","answer":"そこのところはちょっと聞いておりませんので、申しわけありませんが、そういうことでご承知いただきたいと思います。先ほど申しましたとおり、中学１年生が基本的な考え方だよというふうに聞いておりまして、ご指摘の全額助成等については承知してございません。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"国が始めたら予算がそういう意味では増えるわけですから、そういう質問なので、ちょっとそれについてもう１度考え方を伺いたいと思います。その方向に私は行かざるを得ないのではないかというふうに考えますけれども、ちょっと重ねてですけれども、その考え方があったら伺いたいと思います。","respondent":"金子企画財政課長","answer":"これは今、これの中で費用の検討をあわせて行っているかどうかというのは承知していないんですけれども、少なくとも今後。幼保一体施設というのは建設していくという考え方がありますので、そういう意味では、そういった考え方は変わらないというふうに承知しています。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"本来はやはり国のほうに私は戻すべき話じゃないかなと、財政負担が増えていくと思うんですが、そういうことというのは動きがあるのでしょうか。品川区もやはり増えつつあるというよりは、急激に増えてきていると思うんですが、その辺の方向性について説明を求めました。","respondent":"金子企画財政課長","answer":"生活保護のほうの問題ですけれども、ご指摘のとおり、増えれば増えるほど４分の１負担は各市区町村の負担になっております。そこで全国市長会でも、こういった状況では市区町村の負担増が免れませんので、抜本的な制度改正を国のほうに要望しています。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認で、また教えていただきたいんですが、もう１回ちょっとおさらいをしておきたいと思います。","respondent":"金子企画財政課長","answer":"やはりどうしても事情の変化、この中でも実績増になるもの、あるいは事故が起きてそれに対応しなければならないもの等々が出てきてまいります。ここのところは、年２回という形が多かったのですけれども、その間の６月と１２月にもお願いしていることがあるというのが実情です。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"それから１０分の１０という補助で１,２５０万円出ているのと、こういうお金はどういうところに手当てされていることになるのですか。あるいは特にそういうのがなくて、総額の中で、区のほうで具体的に振り分けるとか、ちょっとその辺の仕組みも教えてほしいと求めました。","respondent":"金子企画財政課長","answer":"ちょっと説明がうまくできるか難しいんですけれども、東京都のほうで基金を設置していまして、そこから２分の１が出ると。今年の４月１日現在のゼロ歳から２歳の待機児童数以上の定員拡充に当たる場合には、待機児童解消の補助がいただけることになったです。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"最低６カ月の間に３回ですか、どうしても必然的に女性の命を守るという点からいくと、事業の継続性が必要になってくる。それも含めて区の事業としても積極的にこの件についても取り組んでいただきたいなと、要望も含めまして何点か教えてほしいと求めました。","respondent":"金子企画財政課長","answer":"それから２０歳の女性が１,５００人、接種の見込み率が他の任意接種と同程度と想定いたしまして３０％で、１,５００人というふうに想定しています。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"ワクチンの接種についてはそういう方向でぜひまた取り組んでいっていただきたいと思うわけですが、１つ、それから検診というのが同時に必要なんだと。そこのところの実現に向けて、この辺についてひとつ予算化をしていただけたらと、こう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"林委員","kind":"質問・要望","question":"各委員会で、もうされたと思うんですけれども、ちょっと聞かせていただきたいのは、この３３ページの手当の支給というところで、全部支給が延べマイナスの５９２人、これは補正予算なので、予定として何月から来年の３月３１日までという、そういう日にちの問題をまずは聞かせてもらえますか。","respondent":"金子企画財政課長","answer":"児童扶養手当ですけれども、これは支給月が４月、８月、１２月の年間３回になっています。ですので今度の１２月期、これの対応としまして、１２月からの対応としまして、今補正予算をお願いしているところであります。","id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"これも４カ月でというと、月に１００人という単純計算でいっていいわけですか。それともう１つ、ちょっとここで聞いていいのかどうかわかりませんけれども、父子家庭は品川区にどのくらいのパーセンテージでいらっしゃるのか尋ねました。","respondent":"金子企画財政課長","answer":"父子家庭全体、こちらはまた所得制限等があるので１００人しか該当しないのですけれども、１３８人以上いるというのが現状だろうと思います。ちょっと正確にはわからないので、申しわけないですけれども。","id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"買い取るときに、この防災対策というか、これは品川区のお金を３,２００万円強出しても買っていいよという判断をもらったから買えたんですか。９,１４０万円の土地の価格だから、結果的に補助金が後からついてきた、そういう考えになるわけか尋ねました。","respondent":"金子企画財政課長","answer":"国の補助等では３分の１ずつで、残る３分の１も財調のほうで措置されますので、積極的に取り組んでいるところであります。","id":"exchange-015"},{"speaker":"林委員","kind":"意見","question":"どういう言葉を使うかわからないけれども、３分の１は品川区が持つという、そういう考え方でいいわけですねとの意見を述べました。","respondent":"本間副区長","answer":"私からお答えしますけれども、こちらに、要するに土地の購入価格の査定をしていただくです。そういう不動産鑑定士、要するに専門の第三者機関に価格をかけて、そして決めていただいているです。","id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"そうすると、補助金というのは後から、土地の価格が決まった後に、これは国から幾らくらい出るよ、これは都から幾らくらい出るよという、そういうカウントをして申請をするということになって。","respondent":"本間副区長","answer":"先ほど企画財政課長がお答えしたような、そういう助成制度が活用できるということを念頭に置いていろいろ物件が出た場合にはいろいろ考えているという、積極的に購入する方向で安全な品川区をつくっていこうということで土地を購入しています。","id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"もう１点、純粋に平成２１年度の補正が４億９,７００万円強という計上があって、ここに載ってきたわけですよね。どうでしょう。","respondent":"金子企画財政課長","answer":"その後、これからご審議いただくわけですけれども、決算のほうの段階で、繰越金が２８億円余ございました。そのうちの今回はうちの金額で４億９,７９７万６,０００円を計上するというふうな経過になっております。","id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"第７２号議案になりますから、後でまたお聞きします。一般会計予算では、補正予算として計上されているというだけで、認識を持っていればいいわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"そうすると１回目を受けた人、２回目を受けた人が３回目を受けなかったらむだになってしまうよという、そういう意味に受け取っていいんか尋ねました。","respondent":"金子企画財政課長","answer":"私どもが聞いているところによれば、先ほど申しましたとおり、期間はあります。初回から１カ月、初回から６カ月の計３回で、この３回打たなければならないというふうに聞いているところです。","id":"exchange-020"},{"speaker":"林委員","kind":"意見","question":"総務委員会で取り上げる議題になるのかどうかわかりませんけれども、３回やらなかったら３回分お金をもらってしまったほうがいいんじゃないのか。効き目がないということならばとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"林委員","kind":"意見","question":"先に言ってくれればよかったのに」という話が出てきたら、せっかく、予防だから後々の効き目を期待してやるわけですよね。「最初に聞いておけば、３回ちゃんとやったのに」ということにもならないかなという、これは厚生委員会でやる話になるのかもわからないですがとの意見を述べました。","respondent":"金子企画財政課長","answer":"医療機関で１回目、２回目のところでもそういうような啓発といいますか、指導というのをしていく必要があろうかと思います。その辺のところは所管のほうでも何らかの対応を考えていると思いますけれども、また確認させていただければと思います。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと１点だけ意見を言いたいんですけれども、なかなか今の事態を改善できないので、そこの点だけは改めて述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"４８ページ、４９ページの繰越金が、偶然なんですか。偶然なのか、やむを得なくここに同じ額が出たというふうにとればいいのか、それを聞かせてください。","respondent":"金子企画財政課長","answer":"繰越金は実はこれ以上ありますけれども、この歳出予定の分だけを今回繰越金として歳入のほうの補正にも計上させていただいたという形です。あくまでも繰越金の内数だということでご承知いただければと思います。","id":"exchange-024"},{"speaker":"林委員","kind":"質問","question":"流用もできる金額がないから繰り越してしまうという仕組みで、繰越金を計上して充てるという、そういうふうにとってしまっていいですか。そんなことをやっていいんか尋ねました。","respondent":"金子企画財政課長","answer":"今回どうしても年度途中でこういう歳出の必要性が出てきました。その分今回の歳出に応じた分だけを歳入のほうの繰越金で計上させて、歳入と歳出を同額にしているというふうな形で補正の計上をしているものです。","id":"exchange-025"},{"speaker":"林委員","kind":"意見","question":"流用という言葉を使うから、どうしてもこの５,５６０万円の改修費をどこかで立てなければならないとすれば、私はこれはおかしいと思う。予算、それから予算から成り立っている施策の実施ということについて、どうしても使いたくなるよね、「流用」という言葉をとの意見を述べました。","respondent":"日下部企画部長","answer":"これは今もご説明させていただきましたけれども、これを過大に見込むということになりますと、少し堅めに見込んでおくわけです。やはり繰越として当初予定よりも少し余裕が出た財源が出てくるわけですから、これは実はこの間ずっと毎年度、それをこの必要な歳出に充てていく。","id":"exchange-026"},{"speaker":"林委員","kind":"質問","question":"そこでもう１回繰越金というのを立ててくるわけですか。立ててくると言うか、計上してくるわけか尋ねました。","respondent":"日下部企画部長","answer":"財源として、いわば歳入のプラスアルファ分というのが出てまいりましたので、それでこれを充てるということが可能になったということです。幾つかの選択がありますが、これを考えるしかないというようなことですので、そのようなことでご理解をいただきたいと思います。","id":"exchange-027"},{"speaker":"林委員","kind":"質問","question":"この５１ページにある電算システムの改修ということは、この時期にやらなければならない改修なんですか。なぜ本会計からの繰入金を充て、それを充てていくという、この改修費というのを繰越金でまかなうというのがどうも腑に落ちないんだ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"２つの数字をなぜ持ってくるんだということなんです。繰越金が６,５００万円計上してあって、ここで５,５００万円なら、ぴったり繰越金を流用しているというふうにとるじゃないか尋ねました。","respondent":"日下部企画部長","answer":"さっき企画財政課長もご説明させていただきましたけれども、実は繰越金が国保会計の場合、これが大体１０億円を超えるくらい繰越金が出てまいります。ですから、残りはそのまま手つかずのままという形で、最終的な決算で処理をするという形になるわけです。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"１つは非自発的な失業者の保険料減額ということと、ちょっとそこと、それはどういうふうになっているのかを聞きたいのが１つ。これが今やる必要があるというのは何なのかというのをちょっと伺いたいと思います。","respondent":"金子企画財政課長","answer":"今回のところはちょっと部分的な話で申しわけないんですけれども、国保給付の中のキー項目を国のほうで、国保連のほうで変更していると。現在のシステムを修正することで、システムがきちんと動くような形に修正していくというふうに聞いているところです。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"確認","question":"そこを確認したいのと、そこら辺の線引きが変わってきているかどうなのかというのがわかったら、伺いたいんですけれども。","respondent":"原情報システム課長","answer":"そもそもこの制度は平成１７年の医療制度改革、それについては平成２３年度から全部が電子化するようにと、こういうような国の方針がございました。根幹となるキーが今までのキーではなくて大きく変更となる関係でシステムを大幅に改修する必要があるというような背景の中で。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、やはりもっと実際のお医者さんのところがどうなのかというのを調べていったほうがいいんじゃないかなというふうに私は思うんです。区のところでもやはり調べていただきたいと、これはちょっと要望ですけれども、言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"だから２目保険給付費負担金等償還金というのは予算に載っていない目なのだけれども、突然降ってわいた目なのですか。当初予算を立てたときには考えつかなかったものが、ここへ来て出てきたという、これはそういうふうな理解を私たちはするものなのか尋ねました。","respondent":"金子企画財政課長","answer":"これは右側の説明欄にもありますとおり、精算にかかる返還金で、今回は返還金であります。実際のところ１億４,０００万円ほど出ておりますので、この歳出に見合う金額のみを今回補正で計上させていただいているという形です。","id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"繰越金のほうは、さっきの話でわかりました。科目存置でも１,０００円くらいでよく当初予算には入る場合があるんだけれども、返還金の反対を言うと収入金が生まれる場合もあるわけか尋ねました。","respondent":"金子企画財政課長","answer":"こういう毎年度毎年度確定してからいただくというのでは遅過ぎますので、年度を越えてからこういう形で出入りについて調整するということは多々ありますので、今回については多くいただいているので還付するという形になりましたです。","id":"exchange-034"},{"speaker":"林委員","kind":"確認","question":"１つだけ確認だけさせてください。このゼロという、科目存置されないまま、この時期に来て補正予算でポンと挙げてくるというのは、法的には認められている作業なんですね。","respondent":"金子企画財政課長","answer":"きちんと、そういう意味では補正予算として計上しておりますので、これは間違ったやり方ではありません。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"都への返還というのは時期的にはどんな感じになるのかというのを１つ聞きたいのと、これはもちろんあれですよね。そこの主な使わなかった内容というか、きょうはそこら辺のところをちょっと所管のところではないので、もしわかったら伺いたいと思います。","respondent":"金子企画財政課長","answer":"中身につきましては、聞いているところによりますと、介護保険の中の介護給付費分、それから地域支援事業分、それぞれあります。１つの事業ではないものですから、細かいことは大変申しわけありませんが、ご容赦願いたいと思います。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"やはりその中心は給付を抑えるというところが中心になるわけですから、それが今回、こういうところにも出ているんじゃないかというふうに思います。そういう意味では、２３億円を超える金をためているわけですから、私は特別養護老人ホームの増設等。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-02","title":"本日は、所管事務調査といたしまして、都区制度のあり方","agenda":"本日は、所管事務調査といたしまして、都区制度のあり方","exchanges":[{"speaker":"土井委員","kind":"質問","question":"都をみんなで包囲網で追い込もうというような発案なり、行動なり、似たようなものはどうなのか尋ねました。","respondent":"濱野区長","answer":"先ほど、５３項目についての事前検討をしていこうよというふうにご提案をしたときに、そういう趣旨の発言がありました。そういったことを申し上げるのは、つまりどんどん先取りしてやっていこうよという区は、そうあまりないのではないかなというのが率直な感想です。","id":"exchange-038"},{"speaker":"林委員","kind":"質問","question":"熱心な人を選んでいくという考え方も議会側は持つべきじゃないのかなという気がするんです。新しく４年間始まるわけですから、前を向きそうな区に働きかけるというのはできるものなのですか、無理か尋ねました。","respondent":"濱野区長","answer":"先ほど申しました５３項目について事前に検討するということについては慎重な区と、２３区がこの都区の事務配分の再配分のことについて。にもやはり５３項目をしっかり勉強しておくことが大事ではないかなというふうに思っています。","id":"exchange-039"},{"speaker":"林委員","kind":"質問・要望","question":"これは２３区でやはり十分に仲間意識を持って都側とぶつかっていくべきだと私はいつも思うんだけれども、都側との当たり方は内々ですよね。どうする、いろいろな作業をしていただきたいというふうに思いますので、お願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"土井委員","kind":"質問","question":"そうしないと議論が進まないと。そこら辺に対する働きかけと感触みたいなものがあればお伺いしたい。","respondent":"濱野区長","answer":"「また、具体化を行うための実務レベルの検討体制を検討する」という文言があります。一定、任意共管の事務の仕分けが終わった時点で、すぐにこの実務レベルの検討体制の検討に入ろうという心積もりでおります。","id":"exchange-041"},{"speaker":"宮崎委員","kind":"質問","question":"そこら辺をどういうふうに考えているかということと、区側のほうで論立てをしていくのかというのは１つはかぎになるのかなというふうに思います。では５３項目、そこのところは私もよくわからないんですけれども、どんな思いでいるのかなということをお聞きしたい。","respondent":"濱野区長","answer":"１つの象徴として児童相談所の問題がありますけれども、やはり二元的な対応をやっていますから、そういうケースというのが今までも随分あるわけです。","id":"exchange-042"},{"speaker":"宮崎委員","kind":"意見","question":"そういった意味では一番、私は児童相談所というのが一番わかりやすいし、住民にも訴えやすいと思います。どういう角度で訴えてくるのかということなんかが、やっぱり世論というのはどういうふうにも絡んでいくので、何かあったらお願いしますとの意見を述べました。","respondent":"濱野区長","answer":"少なくとも今の２３区の中で区域の再編が必要だ、近々の課題として、その辺はやはり結束して相対していくということが必要だと思います。時の為政者はどういうふうに考えたかわかりませんけれども、そういう切羽詰った状況の中で府と市を１つにして都にしたわけです。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問","question":"それがこういう形まで来ているわけですから、私は世論をつくっていくという点では、そういうことなんかがあってもいいのではないかなと思っています。それはちょっと感想です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"そうしたほうがいいですよというような、そういうランクづけ、点数づけというのがあるんでしょうか。そうじゃなくて、一応こういうものだったら区でできますよと、区とすれば、その東京都の予算をそのままそっくりもらうという考え方なんか尋ねました。","respondent":"濱野区長","answer":"今、ちょっと一緒になってしまうと議論を進めていくのが難しいんですけれども、何となく話し合っていると何となく伝わってくるのがあります。その辺は、じゃあ、受け取った後でこっちがどうなのかというのも、やはりよく考えていかないといけないのかなということを感じました。","id":"exchange-045"},{"speaker":"須貝委員","kind":"意見","question":"区の財政等、東京都の財政等を見ながら、私は少しスピードをゆっくりしたほうがかえっていい方向に進むんじゃないかなと。最終的にあまり区も、どうぞ当面の間は慎重に進めていただいたほうがちょっといいような気がしますので、どうぞ慎重に進めていただけたらと思いますとの意見を述べました。","respondent":"濱野区長","answer":"質問ではありませんが、考え方をお話しさせていただきたいと思います。２０年持ち出せない話だと思いますので、本当はもっともっとどんどん話を進めたいですけれども、何とかやっていきたいと思っています。","id":"exchange-046"},{"speaker":"堺委員","kind":"確認","question":"もう場合によっては１０年、３年半、区長としてはどうなんでしょうか。最も身近な品川区としてやるべきこと、それでやるんだというふうにしてほしいという、ちょっと確認をしたいと思います。","respondent":"濱野区長","answer":"特別区の自治権拡充ということの長さと言いましょうか、例えば区長公選、準公選、こういった時代から考えますと、もう４０年間になっています。","id":"exchange-047"}]},{"id":"topic-03","title":"」を聴取いたします。 初めに、(1)の「新地方公会計制度に基づく財務４表","agenda":"」を聴取いたします。 初めに、(1)の「新地方公会計制度に基づく財務４表","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"２３区のほうも基本的にこれと同じ様式でやっているのか。それと、あと２３区の横並びで見られる、そういう資料というのはあるのかないのか、その点だけ説明を求めました。","respondent":"金子企画財政課長","answer":"２３区のほとんどが、たしか全部だったような気がするんですけれども、ほぼ全部がこの方式を採用しております。それぞれ各区ごとに、先ほどちょっと申しましたパンフレットといいますか、レポート方式のものを出しているほうがメインになります。","id":"exchange-048"}]},{"id":"topic-04","title":"の「品川区配偶者暴力対策基本計画（案）に対するパブリックコメントの実施について」","agenda":"の「品川区配偶者暴力対策基本計画（案）に対するパブリックコメントの実施について」","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"１点だけ聞きたいんですけれども、アンケートのところでは、公的な機関等で相談するという人が非常に少ないような感じがするんです。兄弟とか、なかなか解決できないんじゃないかなと思いますけれども、そこら辺のことをどういうふうにしていくのかなということですけれどもとの意見を述べました。","respondent":"中山人権啓発課長","answer":"もし、ＤＶについての相談を受けたことがある人、平成１１年はやはりパートナーとのことは２人で解決すべきだというのが２割の数字になっております。１つにはやはり啓発をすることと、区のほうにつないでいただくような、そんな仕組みをつくっていければと思っているところです。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひそういう啓発をどんどんしていただきたい。何かあればお願いします。","respondent":"中山人権啓発課長","answer":"配偶者暴力相談支援センターの機能をどう設けていくかという話と、それからＤＶの出前講座みたいなものも考えておりますので、またその相談の窓口があるということも積極的にＰＲしていきたいと考えています。","id":"exchange-050"}]},{"id":"topic-05","title":"の「平成２２年特別区人事委員会勧告の概要について」","agenda":"の「平成２２年特別区人事委員会勧告の概要について」","exchanges":[{"speaker":"土井委員","kind":"質問","question":"毎度のことなんですけれども、勧告が出ると、それに対して職員組合等々やるんですけれども、そこがどのようになっているか。品川区の場合ですと、違ったグループに属される方もいろいろあるわけで、そこら辺との兼ね合いはどのようになって結論になっているのか尋ねました。","respondent":"榎本人事課長","answer":"大きくその２つの団体を対象に、もう既に要請活動が始まっておりますけれども、１１月半ばに向けての例年の要請交渉活動に入っていくという形。その交渉が妥結した段階で条例等のところの手続きに入っていくというような形で流れていくものというふうに考えています。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問・要望","question":"地域手当というのは、現行１７％から１８％に引上げとなっているところで、その地域手当とは何なのか、その正確な意味を、ちょっとそこのところを教えていただきたいんです。","respondent":"榎本人事課長","answer":"それが平成１３年から地域手当というふうに名前が変わりまして、特に国家公務員の部分で、それぞれその勤務地によってパーセントを変えると。それに合わせて１８％になるよう順次改正を行ってきて、１８％が特別区の地域の本則という形になっています。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問","question":"やはりそうなると今度は手当の意味といいますか、何なんだろうなと思うんですけれども、そこのところはどういうふうな説明になるのか尋ねました。","respondent":"榎本人事課長","answer":"その部分の考え方を引き継いでいるというふうに考えております。ただし、逆に行くと、その部分のバランスはとらなければいけないのかなというふうに思っています。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"意見","question":"それともう１つは、やはり今国民の購買力を下げると、日本の全体の需要をどんどん下げてきていると。これは感想ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"須貝委員","kind":"質問","question":"その約４％の差があるというのは、それでいいのでしょうかという話も変だけれども、その辺についてはどのようなご見解をお持ちなのか尋ねました。","respondent":"榎本人事課長","answer":"職員の給与比較につきましては正規職員、そこの部分では単純にそういう形のパーセント、４％の差という形はとらえられないかなと考えています。","id":"exchange-055"},{"speaker":"須貝委員","kind":"質問","question":"実際、国の特に税金を扱っているんですから一番間違いないところで５.５％下がっていると言って、そのはっきり数字を押さえているわけですね。あくまでそういう方向で品川区のほうは人事院勧告のほうで動いていくという形で、今回そういう形で動くということですよね。","respondent":"榎本人事課長","answer":"例えば電気・ガス・熱供給・水道業ですと６３０万円、それから最下位が宿泊業・飲食サービス業で２４１万円ということでかなり開きがあります。それから東京都の人事委員会、より精緻な比較ができているというふうに考えておりますので、これに従っていく形になると考えています。","id":"exchange-056"}]},{"id":"topic-06","title":"の「南大井六丁目区営住宅耐震改修その他工事請負契約について」","agenda":"の「南大井六丁目区営住宅耐震改修その他工事請負契約について」","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"この住宅は築何年たっているのかと、あと、外フレームと建物を圧着というのは具体的にどういうふうな方法でつくるんか尋ねました。","respondent":"宍戸施設整備課長","answer":"コンクリートの柱ですとか、はりを工場生産のものを持ってまいりまして、現地で組み立てていくというふうな工法です。何種類か工法については検討したんですけれども、ああいった斜め材を外側に足していくというふうな工法も検討したんですけれども。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"外フレームと建物の接合といいますか、それは具体的にこの場合はどういうふうにしていくか説明を求めました。","respondent":"宍戸施設整備課長","answer":"アンカー打ちなどをするのに加えまして、鉄筋や何かもぐっと引っ張りながら圧着した状態で、かなりモルタルよりも圧着性のいいコンクリートを流し込むというふうな形で、非常に強いモルタルで圧着させるというふうな工法で密着させるというものです。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"例えば日にちがずれると、こういうことはやらないのかどうなのか。この場合、一緒の日だったからだめだったのか、そこら辺の考え方はどうなのか尋ねました。","respondent":"阿部経理課長","answer":"要するに１月３１日までに完成しなければ、あるいは道路整備が予定どおり終わらないということで、工区を２つに分けたということです。今回と同じような、１つをとれば、もう１つは無効という考えには変わりございません。","id":"exchange-059"},{"speaker":"林委員","kind":"質問","question":"今、２カ所、北品川と戸越とをやっているんだけれども、相当ずれが起きているんですよね、工事、特に戸越のほうが１年くらいずれている。その商店街の人たちは、街路灯のことだとか、そういうことについての話は上がってきていないのか尋ねました。","respondent":"阿部経理課長","answer":"ただ、かなり歩道がはっきり確保されているような状況ではございませんし、商店街も当然営業しています。今回のところにつきましては道路を新設するという場所ですので、今おっしゃった２カ所とは大分様子が違うというふうに所管からは聞いております。","id":"exchange-060"},{"speaker":"林委員","kind":"質問","question":"そうすると、商店街の皆さんの意見も吸い上げておいてあげてほしいなと思いますので、お願いをしておきます。これから始まる工事でしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-07","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"林委員","kind":"質問","question":"リボンの上、防災センターに今まであったものが１１月１日から移るということだそうで、我々に教えてくれるということはないんですか。それから何であっちへ移さなければならない理由があったのか、その辺を聞かせてくれますか。","respondent":"阿部経理課長","answer":"もう１点、庁舎全体の有効活用、どういうふうにしたら一番使い勝手がいいのかという検討をいたしました。外から来る方のためにも、その辺があそこに集約できるという判断をいたしまして、あそこに持っていくという決定をしたものです。","id":"exchange-062"},{"speaker":"林委員","kind":"質問","question":"そうですかということだけど、年に１遍、その環境フェアのときにセンターがきちんと機能するようにお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1868#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":75254,"voices":185}},{"id":"h22-20101027-14","meetingId":"h22-cm10","date":"2010年10月27日","dateIso":"2010-10-27","committee":"行財政改革特別委員会","time":"午前１０時０２分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"耐震改修は既にされていたかどうかの確認と、築年が、どれぐらい以後新しい施設になってからオープンして使用できると計算しているのかを伺います。荏原第四中学校のほうは、貸付料は幾らになるのかを説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"１点目、今後の協議の中で詳細に詰めていく予定ですので、現時点ではまだ確定はしていないです。引き続き協議していく中で決めていきたいと考えていますけれども、区民の財産を貸し付けるですので、きちんと貸付料はいただきたいと考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"プールの件は、ぜひそちらも耳を傾けていただいた上で要望を取り入れる方向で検討してほしいと求めました。検討の経緯を伺いたいのですが、節目となるところがあったと思うので、日時を追って説明してほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"こちらにつきましては７月の本委員会でもご説明させていただいたと思いますが、私ども、庁内に区有施設跡地活用検討委員会を立ち上げまして。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"検討経緯のところですけれども、それを受けてどういう検討の組織が立ち上がったのか、もう少し詳しく知りたいと思います。地元の要望との関係なんですけれども、今まで地域の人たちの要望を聞くような、それもちょっとお伺いします。","respondent":"久保田行財政改革担当課長","answer":"やはり改めて本年、平成２２年９月に、そうした中で跡地活用検討委員会にも諮りまして最終的にこういう方向で行こうというところで決めたものです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"部長クラスがということなんですけれども、いつこれは立ち上がって、これはもう日常的に存在しているものなのか。何か具体的にどういうものがあるのかお伺いしたいのが１点と、これはあくまで案ですから、そこら辺については何かほかに考えているのかお伺いします。","respondent":"久保田行財政改革担当課長","answer":"住民への説明ですけれども、私ども品川区としましては、やはり主体的に区としての案をまず定めなければならないだろうと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"特別養護老人ホームが小規模になったその経緯というんですか、検討経緯と、住民要望との関係からちょっと何か説明があればしていただきたいのですが。","respondent":"久保田行財政改革担当課長","answer":"今回の活用については、そうした中で特別養護老人ホームの整備ということであれば、小規模の特別養護老人ホームを計画していくです。その一方で、それに合った形での小規模の特別養護老人ホームの整備ということを決定して、利用計画案として取りまとめたところです。","id":"exchange-005"},{"speaker":"井上委員","kind":"確認","question":"初めてお伺いした形になるかと思うんですけれども、どういうスケジュールで今後これが確定というところまで行くのか、ちょっとその辺の先を見通したスケジュールをまず確認させてください。","respondent":"久保田行財政改革担当課長","answer":"学校避難所等の問題もありますので、地域の方からの意見もお伺いしなければならないかなと考えています。そうしたものを踏まえまして、できれば今年度中にパブリックコメントをかけて、広く区民の方からご意見をお伺いしていきたいと考えております。","id":"exchange-006"},{"speaker":"井上委員","kind":"提案","question":"パブリックコメントを今年度中にということは、例えばですけれども、その辺をどういうふうに区としては持っているのでしょうか。もうちょっと違うというような具体的な提案があった場合には、その辺は、区としてはどうお考えか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"青稜高校への貸し付けについてですけれども、こちらにつきましては、区としては協力していきたいという考えを持ってあります。１年６月という短期間の一時的な貸し付けでありますので、また区も主体的にいろいろと活用計画について検討していきたいと考えていますが。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"ほかの私学に対しても同じように平等にあるべき、公平にあるべきだと思いますので、そういう資料提供をまずはしていただきたいと思うんです。そんなに便宜を図っているものではないよという資料を、ぜひわかりたいと思いますので、説明も含めてお願いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"青稜高校に関してですけれども、しながわ中央公園の利用について、簡単に概要についてご説明いたします。青稜高校につきましては、その辺も今後詰めていくですので、青稜高校だけに特段の便宜を図っているといったところはございません。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"その特例にかかわらず、今、そういう準備をちゃんとされているということで理解します。減額のところで、情報公開ではなくて生涯学習課になるんでしょうか、そういったところでちゃんと示していただけるものなんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"今、資料提供ということでございましたけれども、行財政改革特別委員会で資料要求ということで取りまとめをされるのであれば、私どももそれには協力はしていきたいと考えております。","id":"exchange-009"},{"speaker":"井上委員","kind":"意見","question":"では、ぜひそういうデータがあって区民の方へも説明ができるし、おかしいと言われて、ただ、大丈夫です、とは言えないので、ぜひ委員会としてそういった資料要求をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"杜松小学校と荏原第四中学校をどうするのかというのは、そういうのは一つの材料として提供されていたのかどうかをちょっとお聞きしたいのです。荏原第四中学校を使うかどうかは別問題としても、学校跡地などの検討をしていたわけですから、その当時の状況をちょっと聞かせていただきたいです。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、その時点で私どもとして例えば荏原第四中学校と杜松小学校をお貸ししようというような具体的な検討をしてきた経過はございません。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、そういう話は区にあったわけですから、その辺をちょっともう少しお聞きしたいんです。あれだけしながわ中央公園のグラウンドを活用しているわけですから、そこをちゃんとした形でちょっと説明をしていただきたいんです。","respondent":"日下部企画部長","answer":"そういう一つの検討が進んでいるときに、検討をしていきたいということで、一貫して申し上げてまいりました。これは先ほどもきのうの区政協力委員会で区としての考え方をご説明させていただいたということで申し上げましたけれども、今もグラウンドについては。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"かなり具体的ではないとはいえ区に対して要望が青稜高校からあったわけですから、そこはしっかりと私は報告をしていく部分ではないのかと思います。これらについての提言についての検討は、先ほどあった跡地活用検討委員会ですか、この中でどのように行われたのかをちょっと聞かせていただけますか。","respondent":"日下部企画部長","answer":"これをもとに議会としてのそういうご審議をしていただく、これがやはり重要ではないか、このような考え方です。この間、検討を積み重ねてきた、そういうものです。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"平成２２年９月、青稜高校から要請があった時点で、その時点でおそらく区のほうは今のお話で聞くと課題になっていたのではないかと思うんです。こういう高齢者施設を建設していく、増設していく、こういう流れをしっかりつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"１点、その辺を見てからやっていかないと、過去にスタートしたときもそういう状況があったのだということを皆さんに説明してほしいと求めました。今度のこの杜松小学校の跡については、では、この先はどんなふうにしてこの目的に合うような仕組みをつくっていくのかお聞かせ願いたいと思います。","respondent":"日下部企画部長","answer":"今回、きょうもご説明させていただきましたけれども、今ご指摘の点も含めまして今後しっかり詰めていく必要があるのではないかと考えています。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"それぞれメリット、何となく疑義を持たれるようになってくるので、そのあたりはしっかりと説明できる仕組みをつくっておいてほしいと求めました。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"金野委員","kind":"確認","question":"こちらもいわゆる介護予防拠点ということですから、その確認とともに、プールのある位置ですね。","respondent":"久保田行財政改革担当課長","answer":"プールにつきましては、一貫校にもプールができますので、ここのプールをこのままプールとして活用するのはなかなか難しいのかなと考えています。今後の活用等につきましては、やはり詳細な設計の中で高齢福祉の事業部とも検討していきたいと考えているところです。","id":"exchange-017"},{"speaker":"金野委員","kind":"質問・要望","question":"校庭ですね、例えば校庭の避難所としての機能は、そういったところの機能もぜひ高めていただくようなところも要望しておきたいと思います。その介護予防拠点が、ある程度器具を備えた、そういったところも要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと１つだけ聞くのを忘れたんですけれども、先ほど荏原第四中学校の貸し出しの賃料は決まっていないという話がありました。何かの基準があるのだと思うんですけれども、それと財産価格審議会ですか、あの辺との関連を教えていただけますか。","respondent":"市岡総務部長","answer":"これは２つルールがありまして、そこに諮問をして回答をいただいて基準価格を決める、こういう仕組みになっています。これは不動産鑑定士の正式な専門鑑定をいただいて、それに基づいて決定する、こういう仕組みになってあります。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"その庁内の「公有財産管理運用委員会」ですか、ここは先ほどの話と同じで、部長や課長のところでつくり上げている委員会ということなんか尋ねました。","respondent":"市岡総務部長","answer":"これは、ご案内かと思うんですが、「公有財産管理規則」という区の規則がございまして、これに基づいて、私が委員長なんですけれども、必要な部課長で構成する委員会です。","id":"exchange-020"}]},{"id":"topic-02","title":"旧第一日野小学校跡地の活用","agenda":"旧第一日野小学校跡地の活用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"鑑定士の方はどういう考えでこの金額を算出したのかをお伺いします。どういう、例えば７８台だったら１台分に月額３万円で掛ける７８台みたいな、そういう何か考え方があると思うんですが、そこら辺もお伺いします。","respondent":"久保田行財政改革担当課長、市岡総務部長","answer":"この暫定活用中の期間の契約上は２年間ということで契約を結んだですが、私どもとしてはこの２年が延びることはないと考えているところです。そこはまたＴＯＣと協議をいたしまして… 駐車場の車１台ずつの貸付料を足し上げていって賃料を出すというふうな、そういう性格のものではありませんし、国家資格として公のものです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"直接、全住民の皆さんを対象にしたこの活用についての説明会の開催を求めたいと思うんですが、そちらの考えはいかがかということ。具体的にその活用をすべきだと思うんですが、先ほど具体的に杜松小学校でご説明いただいたように、それぞれの築年数は全部同じなんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"こういったことをきちんと地元には説明していかなければならないと思ってありますし、きちんと対応してくれるものだと考えているところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"それとあと、ちょっとＴＯＣが頑張って説明してくれるのではないでしょうかというようなことがありましたけれども、やっぱり区の施設なわけですから。どういう場に行って、これからそういった直接の説明会は開催するつもりはあるのか、そちらをあわせてお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"地元への説明ですけれども、私どもとしましては４月と８月に地元の大崎第一地区の町会長会議で説明を行ってまいりました。それで７月１５日ですけれども、時間としましては午後７時から午後８時１５分まで約１時間１５分ほど説明と質疑応答を行いました。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと１点尋ねたいのが、あと、特別養護老人ホームでも結構切実な声が届きました。そう思わないですか、それだけお伺いします。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましては地域別に例えば幾つ必要という考えではございませんで、その意味では、私どもとしては区全体として考えているところです。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"ですから、再度またもとに戻った審議がされたことがちょっとどうかなというのが、あまりその点に触れていくのがちょっと気になったんですけれども。この費用としてはどこの款・項・目で出てくるのか、予算上、最初からこういうものは計上しているものなんか尋ねました。","respondent":"市岡総務部長","answer":"この鑑定評価は、これは通常の公式の報酬額だと思うんですが、１件約３０万円程度です。フェンスですとか、これは借り主側が負担するというようなことも含めて鑑定条件の中に織り込んで鑑定を依頼し、回答をいただいたものです。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問","question":"わかりました。今後、先ほど来１０年間という期間が出たときには、同じように公有財産管理運用委員会の中で検討していくということでよろしいのか尋ねました。","respondent":"市岡総務部長","answer":"そのとおりです。本格貸し付けになる場合には、これは鑑定条件が違いますので、これは改めて鑑定もし、決定もしていくということになります。","id":"exchange-026"},{"speaker":"渡部委員","kind":"確認","question":"利用者が多くて１０９万円を超えた場合、これは公有地において商売をやっていることにはならないのか、大丈夫なんですか。ＴＯＣが公有地で利益を出してしまって大丈夫なものなのかどうかだけ１つ確認したかったんです。","respondent":"市岡総務部長","answer":"予定利回りみたいなものを想定して貸し付けておりまして、これが鑑定上も適正な額として考えられて金額が出されているものですので、それらを織り込んだ上での適正な価格ということでご理解いただきたいと思います。","id":"exchange-027"},{"speaker":"渡部委員","kind":"質問","question":"例えばですけれども、公園とかですと駐車場は区の土地ですから、委託して委託料を払ってたしか駐車料金は区に入るような仕組みですよね。仕組みと言ったら変なんですけれども、そのもうけ分をもらえるようなというか、できないのかなとちょっと思ったので質問させていただきました。","respondent":"市岡総務部長","answer":"あるいは損失が出たとか、それは上下両方ともありますので、そこには関与しないです。そのためにも適正な価格で貸出しをするということを私どもとしてはきちんと担保するような手続を行っている、こういうことです。","id":"exchange-028"},{"speaker":"井上委員","kind":"確認","question":"確認で、あと、移転だからということでしょうか。そこが残ったときにもそれは解体しなければいけないというその文部科学省のルールになるのか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"それに加えまして短期的ということで期間的に短いというところもありますので、活用は今回図らないという考えを持っているものです。例えば管理上の問題もありますので、そういった意味で、校舎、幼稚園の園舎等の活用は今回はしないという考え方でいるものです。","id":"exchange-029"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"どういう面積なのか、つかんでいるならご報告していただきたいと思うんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"活用できるような公有地があるならば、積極的に活用していくべきだと思いますし、国もそういう方針を打ち出しているわけですよね。区内にどういう公有地、ぜひ委員会としても明らかにしていただきたいので、資料を要求したいと思います。","respondent":"堺委員長","answer":"では、その件については、また正副で検討します。以上で、本日の予定はすべて終了いたしました。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/438675?Template=document&Id=5894#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":30226,"voices":72}},{"id":"h22-20101028-15","meetingId":"h22-cm10","date":"2010年10月28日","dateIso":"2010-10-28","committee":"環境対策特別委員会","time":"午前１０時０３分～午前１１時３８分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"水辺とみどりの整備に関することとして、みどりの現状と施策","agenda":"水辺とみどりの整備に関することとして、みどりの現状と施策","exchanges":[{"speaker":"川西委員","kind":"質問","question":"ちょっと聞き漏らしたかもしれないので伺います。それから平成６年にみどりの条例というので動きまして、何というんですか、建築に対する指導というのはそのままになってしまっている。","respondent":"藤田水とみどりの課長","answer":"１人当たりの公園面積かなと思うんですが、１人当たりの公園面積といいますと、最近品川区内増えてきております。それと公園面積を比較すると、ちょっと伸びが、人口の伸びが大きいために余り増えていないということかなと思います。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問・要望","question":"６,９４１本確認されて、平成１４年との比較で１,４４０本増えたと。急に大径木が１,４４０本増えるわけないんですから。","respondent":"藤田水とみどりの課長","answer":"そのことは１つあると思いますが、委員お話のとおり、そういったことでこの本数についてはどうしても変動が出てきてしまいます。ということで、あくまでもそのときの本数がこういう本数であったということのご報告だけしかできないということで、私ども考えてあります。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"単純なことで水面と運河の違い、これは運河は水面になっていませんよね、これで見ると。それは何でなんですかという、それだけのことなんです。","respondent":"藤田水とみどりの課長","answer":"品川区の行政区域の２,２７２という数値では、運河等は含んでいないです。緑被地、緑被率を出すときには運河は含まないということで、こちらの分布図の方にはこういった形で記載をさせていただいてあります。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"単純に同じ水面だったらつながっているわけじゃないですか。それをなぜか、国なり東京都の基準があってこうされているんですかということの質問です。","respondent":"藤田水とみどりの課長","answer":"２,２７２と一般的に言っている数値の中にはもともと川は含んでいます。ただし運河は含んでいないということで、こういう記載になってあります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"それとの関係というのはどういう位置づけになっているのか伺いたいと思います。このみどり率を加えたねらい、目的は何なのか伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"ご説明の中でもいたしましたが、４分の１緑化というような言い方をして、その数値に向けて今努力をしています。もう既に１４年ほどたってありますので、実施計画の中でもそういった計画をつくり、さらに進めていきたいということで考えてあります。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"それまでの緊迫感を持った具体的な行動とかスピード感が必要だと思っているんですけれども、この辺どうお考えなのか伺いたいと思います。ちょっとそこの関係がよくわからないので、あわせてご説明いただけますか尋ねました。","respondent":"藤田水とみどりの課長","answer":"都の横引きなのかどうなのかというお話ですが、品川区の緑化の率、これにつきましては都の基準よりか厳しくなっております。現在の率として行っているものについては、おおむねいい形で私ども指導ができているというふうに考えてあります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、川とか運河を足しちゃっているわけですから、実際のみどりからすると、２１.２％と言いましたけれども、１５.８％なわけですよね。みどりを増やさなきゃいけないという議論に進んでいるわけですから、これはちょっと違うと思うんですが、いかがか尋ねました。","respondent":"岩田都市環境事業部長、藤田水とみどりの課長","answer":"都市におけるＣＯ２対策ということは、やっぱり化石燃料をいかに使用を抑えていくか、こういったものが一番大きな施策になってまいります。ただ、過去品川区は緑被率でずっと区民には説明してきていますので、今は並行して… 現在緑確保の総合的な方針ということで、やはり重点的にやっていくべきだろうということで、今都全体で取り組んでいるところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"何というんですか、循環システムの循環を壊してＣＯ２が増えていった、こういう問題があると思うんですね。やはり具体的にみどりを増やしていくためにどう汗をかき、計画を具体化していくのかと、その方向はしっかりと示してほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"当面建て替え予定がない、強度的に問題がない、屋上等の緑化についても積極的に私どものほうとしてはやっていきたいなということを考えてあります。川の壁面の緑化ということで、これまで目黒川、立会川のほうでずっと進めてきたところです。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"何といったらいいんですか、ＣＯ２とかそういうことを考え始めると、景観という意味ではそれがつながっていくことにとても意味があると思うんですね。だからそういった視点でもみどりを増やすという考え方があっていいのではないかと思うんですが、いかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"今検討しているところと聞いてありますので、そういったような実態を調査などをして、その先の策を考えていきたいということで考えてあります。","id":"exchange-009"},{"speaker":"阿部委員","kind":"意見","question":"やはり、どういうところでそういったものを確保していくのかということは、ぜひある程度計画的に進めていかれるべきであろうなと考えています。この点についてはご答弁お願いいたしますとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"非常に部課長で議論していますし、これはいずれ本格的に区としても、この問題については検討せざるを得ないと考えています。いろいろこれからは考えて、みどりや花を楽しんでいただけるような区民づくりというんですか、そういうのをいろいろ検討していきたいと思います。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"先ほど緑被率の進捗状況について報告いただきましたけれども、その中で公共施設のほうについては結構力を入れてやられているというふうに伺いました。民間よりも規制というんでしょうかね、これはもう民間ですから、もし数字があればちょっと教えていただけないかと思います。","respondent":"藤田水とみどりの課長","answer":"で、比率のほうが１２.３％ということになってあります。ということで、公共施設のほうが緑被は既に進んでおりますので、その中でこれ以上の伸びがなかなか難しいというのが実態だです。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうところも区が積極的になんらかの形でアクションとってできるものなのかどうかということがちょっと気になります。公共のほうはどのようなストレスというんでしょうか、影響はどうなっているか、ちょっと教えてほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"緑化計画書のほうにもありますとおり、公共のほう、施設を建築する際には公共施設の場合も私どものほうに届け出をしていただきます。都の施設であったとしてもそういうような形になりますので、その中で私どもとしては適切に指導をしていきたいということで考えてあります。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"例えば屋上ですとか、壁面ですとか、そういうのが多分出てくると思うんですね。そういうところに対してのアクションについて、すみません、そちらのほうを説明を求めました。","respondent":"藤田水とみどりの課長","answer":"区の施設の場合は、私ども可能な場所についてはやっておきたいということで、その施設を管理するところといろいろお話をしています。可能な場所が私どもが見て見つかればお願いをしていきたいと考えていますが、実際にはそれぞれの施設でご検討いただいているというのが実際です。","id":"exchange-013"},{"speaker":"川西委員","kind":"質問・要望","question":"今の質問にあったように、既存の建物の中で努力されているところがあるのか、ちょっとわかれば教えてほしいと求めました。ですから、そういうのをもっと促進するためには載せていただければいいかなと。","respondent":"藤田水とみどりの課長","answer":"保存樹の関係ですが、平成２１年度で考えますと、新たに指定をしたのが１２本あるんですが、その際に解除があったものが３件あります。解除というのは… ページ数がないんですが、後ろから４枚目のところにありますので、よろしくお願いします。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問","question":"大崎地区の質問の中だと思うんですが、これは開発に、例えば大崎の明電舎の。ああいう開発行為の中で増えた壁面なのか、既存の建物なのか。","respondent":"藤田水とみどりの課長","answer":"そういうのも今は１m2からカウントできますので拾えてしまうんですが、新しい施設の屋上緑化、壁面緑化がほとんどです。","id":"exchange-015"},{"speaker":"川西委員","kind":"質問","question":"こういう指導を丁寧にされる窓口というのはきちっとしているのかどうかというのをついでに伺っておきます。これは質問ではありません。","respondent":"藤田水とみどりの課長","answer":"壁面、建築のメンバーがその強度の確認から入らなければいけないということで、なかなか難しいのが実態です。そういうお話があったときには、私どものみどりの係のほうでいろいろ支援をしながら、ご相談に応じながら対応しています。","id":"exchange-016"},{"speaker":"山元委員","kind":"質問","question":"１個だけすみません。これからも屋上緑地というんですかね、何か予定しているというか、そういうのはありますか。","respondent":"藤田水とみどりの課長","answer":"これからそういうものがあればかかってきますので、そういった部分に当たるようであれば屋上のほうの緑化も進んでいくことになります。ただ、それぞれの施設の中で施設を使う人たちのご要望があれば、その施設の中で工夫をして屋上の緑化をすることもあるかとは思います。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"ということは、緑被率とかみどり率には入ってこないという理解でよろしいか尋ねました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"壁面緑化は、実は飛行機からカメラで写真を撮るので壁が数値にあらわれてこないんですね。なので、緑被率、みどり率については、その壁面緑化の部分についてはカウントの中に入ってこなくなってしまいます。 あれも２回ほどいたずらで、一番下の茎のところポッと切られると、全部枯れたんですね。他の用途のほうとしてやっているきらいがありますので、そこら辺はちょっと使い分けながら、実際に担当部署のほうはやっております。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"第１グラウンド、第２グラウンドがある学校なんてあそこしかありませんから。みどりの基本構想の４分の１構想から見れば、ちょっと訂正をしていただきたいなと思いますけれども、いかがでしょう。","respondent":"藤田水とみどりの課長","answer":"現状として、伸びの率が民間の大幅に伸びる、公共施設の中でその大幅な伸びと同じような伸び方はなかなか難しいというようなことで考えてあります。４分の１の緑化に向けてこれからも進めていきたいと考えています。","id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"もう１個だけすみません。そもそも言葉の使い方というか、目的が多分違うと思うんですが、そこを最後に一言だけ整理整頓していただけますかとの意見を述べました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"そういうような観点からみどり率という考え方が出てきております。潤いだとか、そういったことを感じるような策につながるということで、みどり率という考え方が出てきているものです。みどり率が最適に比較するのであれば、４分の１の達成状態を確認するには、このみどり率で追っていかざるを得ないわけですね。","id":"exchange-020"},{"speaker":"西本副委員長","kind":"意見","question":"１つだけ。別な用途がありつつ、それの推進も含めて施策の中入れられないだろうかというふうに考えるんですけれども、いかがでしょうとの意見を述べました。","respondent":"藤田水とみどりの課長","answer":"それも楽しみがあるから毎日見にいく、あるいは水をやりにいくというようなことで、品種管理ができるものです。これについても屋上緑化の１つの考え方であるということで考えておりまして、現在はその助成の対象に、私ども進めているところです。","id":"exchange-021"},{"speaker":"西本副委員長","kind":"質問・要望","question":"この水とみどりの課というところが連携を組んでちょっとやっていただきたいなと、進めていただきたいなと思いますが、。","respondent":"藤田水とみどりの課長","answer":"夏休みの間にお子さんが学校に来ない、用務さんもなかなか上がらないということで、夏の間に枯れてしまったようなケースも目にしています。","id":"exchange-022"}]},{"id":"topic-02","title":"を行います。 環境情報活動センターの移転","agenda":"を行います。 環境情報活動センターの移転","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"つまらないというか、ＥＣＯだよりのところで「星稜中学校」の「セイ」の字が違っているよ。これやっぱり配布することになるので、もう出しちゃっているんですか、これ。","respondent":"工藤環境課長","answer":"こちらのほうはホームページの中で訂正します。申しわけございません。","id":"exchange-023"},{"speaker":"中塚委員","kind":"意見","question":"だからこっちに行った理由というか、利点というか、ねらいといいますか、何かそういうお考えがあるのかなと。どういうお考えなのかご説明いただけますかとの意見を述べました。","respondent":"工藤環境課長、岩田都市環境事業部長","answer":"移転に関しましては庁舎内全体のレイアウトを管轄します経理課からお話がありました。理由といたしましては、やはり庁舎全体の有効活用という考え方から、今回決まったものです。もともと第２庁舎、防災センターの２階部分、３階部分というのは、防災対策用の空間というふうに位置づけられておりました。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270609?Template=document&Id=6198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":28853,"voices":83}},{"id":"h22-20101029-4","meetingId":"h22-c-settlement","date":"2010年10月29日","dateIso":"2010-10-29","committee":"決算特別委員会","time":"午前１０時０２分～午後５時５３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を148件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"金野副委員長","kind":"質問・要望","question":"経過時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。第６項、５階の理事者控室に当委員会の模様を放送いたしますので、そちらでお聞きいただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２１年度品川区一般会計歳入歳出決算","agenda":"以上で決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２１年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"そしてもう１点は、これは監査委員報告書の中の１６ページに、債権の管理についてお伺いしていきたいと考えています。待機児童対策への喫緊な取り組みを要望しているところですけれども、また保育園の受け入れ拡大数についてお教えほしいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"ここ数年の保育園の定員の推移と待機児童者の推移についてご説明いたします。待機児の推移ですが、平成２０年の４月につきましては１１５人、平成２１年の４月が１２３人、今年の４月１日におきましては６６人となっております。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問・要望","question":"今の待機児童数を伺ったんですけれども、つい先日まで激しかった区長選があったものですから、そのときには。今お話を伺いますと、平成２２年、待機児童数６６人という話を伺いました。","respondent":"伊崎待機児童対策担当課長","answer":"５００人近い数字とおっしゃられましたのは、その中で、保育園の入園の内定が出なかった方の数ということでのご理解の中の数字かと考えております。区外からのお申し込みの方などもすべて含まれておりますので、品川区といたしましては、６６人が待機児という認識をしております。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"待機の方が６６人いたということなんですけれども、この方たちは１年間子どもたちを抱えて、仕事を休んで待っているという状況だったのでしょうか。その辺、待機された人たちの、どういう状況に置かれているのかということをお聞きしたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"４月１日時点の６６人の待機児の方の現状ですが、そのうち、２３名の方は１０月までに保育園に入園ができていらっしゃいます。自営でお子さんを見ながらお仕事をされている方などもいらっしゃいますが、皆さん、適切な保育を受けていると認識をしております。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問・要望","question":"保育に欠ける状態の方たちから優先順位があるわけですから、４時間働きたいんだ、子どもを預ければという方たちかなと思っているんですね。何園ぐらいあって、どれぐらいの子どもたちが措置されているのか、その辺の数字をお知らせほしいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"認可外保育所につきましては、区内に１９園あります。利用状況ですけれども、１４０人ぐらいの方がご利用なさっていらっしゃいます。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"認証保育所についてお伺いをしたいんですけれども、今８月１日現在で１５園、５２６人措置されている。これから、若干上がったという話は聞いているんですけれども、今後品川区としてどのようなお考えを持っているかについてお伺いしたいと思います。","respondent":"吉岡保育課長","answer":"今年度からは、現に負担をしていらっしゃる保育料を６万６,０００円を上限といたしまして、その差額を助成するような形にいたしました。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"今年度が１,７７１という数字を伺いましたけれども、当然のことながら、どうもオーバーしたんだというような声も聞くんですね。ある程度もう限界に来ているのかなという気がするんですけれども、来年度の見込みについてお教えほしいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"来年度の見込みにつきましては、現在いろいろな状況、条件下で精査をしていますが、今年よりもまた上回る可能性があると考えております。これまでのさまざまな保育施策で対応していくと同時に、今度補正予算でお願いしていますが、さまざまな施策で対応していくと考えております。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"３番目の質問で通告しました債権の管理ということについて。増加しているのか、減少しているのか、その辺をお聞きしたいと思います。","respondent":"福田会計管理者","answer":"平成２１年度と平成１７年度を比べてみますと、８,６５０万円、率ですと２０.３％の増であります。これは１つの傾向として毎年少しずつ増えてきた、こういうことが言えようかと思います。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"未済額の中には、住宅関係なんかですと、その締めの月にどうしても入らなくて、二、三日遅れて入れましたと。この辺の方策についてお伺いしたいと思います。","respondent":"福田会計管理者","answer":"あるいは実務の面でも異なっておりますので、それらをどのように整理をするか、これを検討してまいりました。これをこれからいろいろ調査をしたり、あるいは内部で検討を進めたりしながら考えていきたいと考えております。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、今後何らかの仕組みづくりを行っていく、方向性でもいいんですけれども、という方向でやっていくということでよろしいんでしょうか。もう一度お聞きいたします。","respondent":"福田会計管理者","answer":"実はこれは大変難しいことなんですけれども、きちんとするということと、それから、円滑な事務処理ができるようにすること。この要請にこたえられるような、そういう仕組みづくりをこれから考えていくというものです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"私からは成果報告書の８８ページ、９５ページから９６ページにかけまして、この３点についてお伺いします。１,０００円から５００円に値下げをしておりますけれども、ここまでの期間で何らかの傾向の変化が見られるのかどうか、お伺いいたします。","respondent":"梶戸籍住民課長","answer":"そして平成２２年度、９月３０日現在までで１,８９７件となっていますので、住民に対するパーセンテージからしていくと増えているという状況です。９月の３カ月だけで見てまいりますと、昨年の３カ月間と比べますと、２７％ぐらい増えているというような状況になってあります。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"その中で、利便性を上げる取り組みというものがどうしても増やすためには必要かと思います。今後何らかの手だてを打とうとしているのか、お伺いします。","respondent":"原情報システム課長","answer":"国のほうでも、委員ご指摘のとおり、コンビニによる住民票の交付、こういったところが今年の２月、２３区ですと、渋谷区のほうで実施をしています。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"４種類でしたかね、今どうも論議がとまっているようでありまして、なかなか進まない１つの大きな要因になっているかと思います。ほかに踏切の安全対策で補助金の対象となるような事業があれば説明を求めました。","respondent":"藤橋都市整備下水道課長","answer":"本年度に東急池上線と東急大井町線の合わせて４カ所でカラー化を予定しておりまして、対象ではありませんので、一般財源という形で考えてあります。国庫補助事業の適用の対象外のもの、カラー化につきましては、区の単独費という扱いになります。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"どうも通る車も多いようで、ここで人と自転車との錯綜というんでしょうか、非常に激しいかなという気がします。どうしても幅を広げるとなりますと、今後安全対策で改良されるような踏切の計画がありましたら、お願いします。","respondent":"松代都市計画課長","answer":"都市計画道路の整備、もしくはまちづくりの中でそういった踏切対策、また考えていけるのかなと考えています。踏切を円滑に渡れるような、そういったことも、鉄道事業者などといろいろと協議をしています。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"これは要望です。３点目ですが、こちらのほうの用途、歳入に対します用途についてお伺いします。","respondent":"和氣学務課長","answer":"地デジ対応の液晶４６インチのテレビを小学校に１台が１０校、各中学校には１台を配置し、これを各学校２台配備をいたしました。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"ブルーレイのレコーダーと私は認識していたんですけれども、違うのであれば、またお願いします。これも過去に質問させていただきましたけれども、どのような活用のされ方をしているのか、実例等がありましたら説明を求めました。","respondent":"和氣学務課長","answer":"すみません。各学年にプロジェクターを設置していますので、そのプロジェクターでパソコンを通じて見ていくとか、そんな使い方をしています。","id":"exchange-016"},{"speaker":"浅野委員","kind":"提案","question":"子どもが理科離れ、科学離れしている中では、１つの大きな方策ではないかなと提案しています。確かに授業のところですとか、そういうような理解を深める意味では非常に重要なものだと思いますけれども、この点についてのご見解をお願いしますとの意見を述べました。","respondent":"冠木指導課長","answer":"今委員お話しのように、理科につきましては、非常に可視化が難しい。こういった視聴覚教材を積極的に活用いたしまして、授業の活性化に、あるいは豊かな授業につなげていきたいと思ってあります。","id":"exchange-017"},{"speaker":"菊地委員","kind":"意見","question":"この年、普通徴収部分の中心である中小業者のところ、緊急経済対策で支援するというようなことがあったのが平成２１年度だったんだと思います。区民の暮らしの分析とあわせてお聞かせ願えればと思いますとの意見を述べました。","respondent":"武内税務課長","answer":"昨年徴収した分がこの１０月に決算という形になるんですけれども、平成２０年については、個人所得の部分はですね。株の取引等については大きく落ち込んでいるというのが現実です。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問・要望","question":"給与所得者が増えたとかいうような話がいろいろありましたけれども、どういう所得階層になってきているのかというところも教えていただきたいです。それから、平成２１年度の相談件数、減免者何件ぐらいになるのか、この辺もお聞かせ願いたいと思います。","respondent":"武内税務課長","answer":"先ほど説明したとおり、また住宅の売買等が非常に衰退というんですか、停滞したということが平成２１年度の大筋で分析できるのではないかと考えます。それは預金の中から払っていただくということも考えられるんですけれども、再就職等、そういう相談を受け付けているところです。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"減免者が何件ぐらいになるのかというのもお聞きしたので、お聞かせを願いたいと思います。それから、徴収猶予、その後に支払いが可能になる方、こういう方の件数についてもお聞かせを願えますか。","respondent":"武内税務課長","answer":"お金の支払いに応じたという、すみません、今手元に資料がありません。徴収猶予しても、半数ぐらいの方については、分納だとかという形に、お支払いに移行するという形になっております。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"本来の数字がよくわからないのであれなんですけれども、徴収猶予の方の半分ぐらいが後に分割で納入できるという意味なんですか。その辺の件数というのは、平成２１年度ですから、ある程度数字として持っておられるかと思うので、その辺、数字としてお聞かせを願えますか。","respondent":"武内税務課長","answer":"徴収猶予は、具体的には、１,８００人ぐらいの方、徴収猶予という手続を年度で行うんですけれども、その半数ぐらいの方については、分納開始だとかという形で、手続で、全額ではないんですけれども、月々幾らとかという形で払っていただいています。","id":"exchange-021"},{"speaker":"菊地委員","kind":"確認","question":"ということは、４件に１件ぐらいの割合、２５％ぐらいの方しか、猶予になったり、あるいは減免になっていないという状況なんですか。ちょっと確認させてください。","respondent":"武内税務課長","answer":"３カ月猶予してみて、執行停止という、そういう手続に入ります。その方が、平成２１年度では、６,１４２人の方を手続を行っているです。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"今の暮らしがどうなっているかというのが見えるんだと思うんですけれども、その辺での分析というのはそもそもやらないわけですか。その辺もお聞かせを願いたいと思います。","respondent":"武内税務課長","answer":"もちろんそういう相談がありますと、どういう相談の傾向があるかというのは、職員間の中で、私も含めて、傾向的な話し合いをしてもちろんやっております。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"これだけの皆さんが執行停止ということではないですか、そもそも減免の制度を使いたいということで相談に伺う状況にあるんだと思いますね。本当に生きた税金の使い方をどういうふうにしていくのかというところも、改めてその辺もお聞かせ願いたいと思います。","respondent":"武内税務課長","answer":"もちろん区政執行に当たりましては、区税収入というのは、３０％という割合を含めていますので、その辺の現状については、認識しながら、区政の声として広めていくということは大切だと認識しております。","id":"exchange-024"},{"speaker":"稲川委員","kind":"質問","question":"密集市街地整備促進事業ほか４事業という補助金があるんですが、その辺についてお伺いいたします。基本的に一番古いのからどんどん返済をしていくような感覚はあるんですけれども、どういう形の返済になっているかということを説明を求めました。","respondent":"武内税務課長","answer":"平成２０年度から以前において１７億円の滞納繰越が発生しているという中で、平成２１年度については６億１,７００万円の徴収ができたです。１,６０３件ありまして、平成２０年度分については、３万８,３１８件というものです。","id":"exchange-025"},{"speaker":"稲川委員","kind":"質問","question":"多分利子とか利息というか、１７.４％ですか、そういうのというのはついてこの額になっているのか。これは元金というか、元本というか、そういうことでよろしいんか尋ねました。","respondent":"武内税務課長","answer":"こちらに出ている滞納金額については、延滞金を除いた金額で、本税という部分です。","id":"exchange-026"},{"speaker":"稲川委員","kind":"意見","question":"結構前の本税の滞納に関して、結構昔からあるとおっしゃっていましたけれども、それはどういう形で今後徴収をしていくのか。１０年もたってしまうと、その辺今後どうやって徴収していくか、お願いしますとの意見を述べました。","respondent":"武内税務課長","answer":"そういう方ですと、不動産を、ほかのビルとか、そういうのを持っていて、それを売却して、自宅とかを持っている方がいます。そういう古いものが残っているということですので、それは状況を見きわめながら、落とすときは落とすということも必要なのかなと考えています。","id":"exchange-027"},{"speaker":"稲川委員","kind":"質問・要望","question":"区民税は払うべき税金ですので、しっかり追っていっていただいて、徴収に努めてほしいと求めました。外国人登録全般についてお伺いしますが、平成２４年ですか、外国人登録か尋ねました。","respondent":"梶戸籍住民課長","answer":"通常の観光とかは除きますけれども、３カ月以上適正な形で入られる方につきましては、その場で在留カードを空港等で交付するというものです。","id":"exchange-028"},{"speaker":"稲川委員","kind":"質問","question":"これにかかわる事務費というのは、歳入歳出に関しても、この件に関してはなくなってくるということでよろしいんですかね。それがいわば住民基本台帳のほうに今度は移行してくるという考え方でよろしいか尋ねました。","respondent":"梶戸籍住民課長","answer":"原則としては、ただいまのご質問のとおり、入ってくるです。相変わらず市区町村のほうで受託事務になりますので、そういった在留カードという形ではなくて、特別永住者の証明書という形になってまいります。","id":"exchange-029"},{"speaker":"稲川委員","kind":"質問・要望","question":"９０ページの開発行為手数料に関してです。これは１５０件と書いてあるんですけれども、実際開発行為というのはどういう行為なのか、説明を求めました。","respondent":"山崎マスタープラン担当課長","answer":"区画の変更とは、道路等の新設、廃止等により、一団の土地利用形態を変更することを申します。それから、形質の変更ですが、土地を、切土、盛土等々申し上げますが、１メートルを超える造成行為、こういったものを指します。","id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"じゃあ、最後に１件だけ。この１５０件の中で、１つの土地を分筆して分譲にするような開発行為というのは何件あるかだけ説明を求めました。","respondent":"山崎マスタープラン担当課長","answer":"開発行為の手数料に該当したものは５件ございまして、そのうち、委員おっしゃられたものに該当するのは２件です。","id":"exchange-031"},{"speaker":"渡部委員","kind":"確認","question":"今回決算書ですとか、決算審査意見書、監査委員のほうから出ている意見書の１６ページを例にとってお話を伺っていこうかなと考えています。時効の部分等もいろいろあわせて伺いたいのが１件。","respondent":"福田会計管理者","answer":"大きく分けて２つのご質問にお答えさせていただきたいと思います。そういう区別、これも非常に難しい区別なんですけれども、によるものです。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"やはり平成２１年度から、会計処理上、これは受けたサービスに対する対価ですから、当然区民の方にもお支払いいただかなければならない。毎年出ていたものがゼロになっているということ自身、何かの制度変更でもあったのかなと思ったんですが、その辺はいかがか尋ねました。","respondent":"吉岡保育課長","answer":"それで、年度を越した６月に早速、平成２１年の分でやるべきであった分について不納欠損処理を実際のところはもう既にしております。金額は１２８万円余ですので、大体金額的にも例年の額と同じぐらいの不納欠損が発生をしていたというのが実態上の状況です。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"区営住宅使用料というところで、平成２０年度の収入未済額が８５０万円あったものが、平成２１年度の収入未済になりますと８１８万円になります。この決算書の間１年間で、要するに支払い行動があったから、今年収入未済が減っているということでよろしいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"今のご質問です。その方に対して、区のほうでも積極的にアクションを起こしたところ、お支払いいただいた結果です。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"いろいろ伺ってまいりました。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは成果報告書の９２ページの国庫補助金、９８ページの都補助金、高齢者に対する補助金等をお伺いしたいと思います。１つ確認をさせていただきたいんですけれども、いわゆる在宅の介護といったものを１つの基準として、杜松小の跡地活用といったことで。","respondent":"冨岡高齢者福祉課長","answer":"中心でございまして、介護がし切れないというときになると、例えば特別養護老人ホームというような施設にお入りをいただく。小規模多機能と、そういうものも建設しながら、できるだけ地域でお住まいをいただくということを目指したいと考えているところです。","id":"exchange-036"},{"speaker":"山内委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいんですが、私、第１回定例会でシルバー人材センターの今後の行く末について質問をさせていただきました。宮地部長の答弁を確認させていただいたんですけれども、これ、厳しい運営が強いられるものと危惧をいたしておりますといった答弁がありました。","respondent":"福島ものづくり・経営支援課長","answer":"これからの区の支援も含めましてですけれども、シルバー人材センター自身は内部努力を行っておりまして、自分たちの経費削減等を行っているです。","id":"exchange-037"},{"speaker":"山内委員","kind":"質問・要望","question":"この２,５１０万円というのは、直接なんですね。今年度の平成２２年度の予算書を見ましても、やはり同じ金額なんですけれども、そのあたりも教えていただきたいなと思うんですが。","respondent":"福島ものづくり・経営支援課長","answer":"その区の補助に対しまして、都の補助が区に入ってきている、そういう構図です。都の要綱によりまして金額が決まりますので、都の要綱は改正がありますと金額が変わるというもので、ずっとフラットというものではございません。","id":"exchange-038"},{"speaker":"山内委員","kind":"確認","question":"平成２１年度の決算と平成２２年度の予算というのは同じ額ですが、会員数に対しまして、金額的にも上昇していくといったことでよろしいのか。その辺を確認させてください。","respondent":"福島ものづくり・経営支援課長","answer":"支部につきましてはＢランクになっているというものです。このランクが上がるほど、人数が増えますと、確かに金額は増えるかと思ってあります。","id":"exchange-039"},{"speaker":"山内委員","kind":"質問・要望","question":"再度、そのランクというのは、人数のことなんでしょうか。今ランクということをおっしゃられたので、その辺について確認をさせていただきたいんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"例えばＡランクですと、運営金額が幾らと決まっていまして、Ｃランクですとそれより下がるです。使うことができる内容ですとか、例えば人件費は幾らまで使えるとか、そういう細かい内容の要綱に基づきまして支給されているものです。","id":"exchange-040"},{"speaker":"山内委員","kind":"質問・要望","question":"これは民間のことなので、あえてこれはどういうことなのかといったことをお伺いをしたいんですが、品川区のいわゆる多目的広場が載っております。品川区の施設といった何か記載を載せるべきじゃないかなというような思いがしたんですけれども、そのあたりについてお伺いさせていただきたい。","respondent":"堀越文化スポーツ振興課長、金子企画財政課長","answer":"９割と、特に土日などは９割近い利用率がありますので、活用していきたいと考えております。確認させていただいて、必要に応じて申し入れ等をするような、そういう形で対応していきたいと考えております。 使用料全体についてのご質問がありましたので、私のほうからお答えします。使用料は、使用した際の受益者、受益されていますので、適切な負担をしていただくというのが基本的な考えです。","id":"exchange-041"},{"speaker":"山元委員","kind":"質問・要望","question":"最初、８３ページの使用料の中の集会所使用料について、またもう１点、８８ページの教育使用料の中の温水プールについてお聞きしたいと思います。ご質問なんですけれども、利用率というんでしょうか、その辺を教えてほしいと求めました。","respondent":"中山地域活動課長","answer":"継続的利用の方の割合というご質問ですが、１回登録をして、再度同じ申請書を書かないような形で登録はしております。継続といいますか、毎月のように利用されている団体といいますか、集会利用が多いものとは思われます。","id":"exchange-042"},{"speaker":"山元委員","kind":"質問・要望","question":"区民の方からも苦情が来ているかどうか。俗に常連と言うんですかね、何かお考えをなさっていれば、教えていただきたいんですが。","respondent":"中山地域活動課長","answer":"ご案内のとおり、基本的には２カ月前からの申し込みという形になっております。","id":"exchange-043"},{"speaker":"山元委員","kind":"質問・要望","question":"１,０６５回も利用されている、何かご存じであれば教えていただきたいのと同時に、第４日曜日がお休みになっております。日曜日がお休みというのはどうなのかなと思っているんですが、その辺も教えてほしいと求めましたが、いかがか尋ねました。","respondent":"中山地域活動課長","answer":"平成２１年度、平成１６年度以降ですか、実際には臨海斎場等ができて以降の利用実績は出ていないという状況です。運営の体制の確保も含めて、そういうお声があれば、受けとめながら検討していきたいと考えております。","id":"exchange-044"},{"speaker":"山元委員","kind":"質問","question":"そうしましたら、そのときには、ご相談に乗っていただけるということでよろしいか尋ねました。","respondent":"中山地域活動課長","answer":"曜日等の設定のことですので、そういう中で、ただいまのような声も含めて検討させていただきたいと思います。","id":"exchange-045"},{"speaker":"山元委員","kind":"質問・要望","question":"次に、８８ページの温水プールのことでお伺いをさせてほしいと求めました。ここで１つご質問させていただきたいのは、１,０００万円の差額といいますか、何か理由があるのであれば教えていただきたいんですけれども。","respondent":"堀越文化スポーツ振興課長","answer":"平成２１年度の予算と決算との利用者の差ですが、平成２１年度ですと、９,１００万円という形です。歳出ですと、八潮学園の温水プールが平成２１年度からオープンしておりますので、歳出としては増えているという状況にあります。","id":"exchange-046"},{"speaker":"山元委員","kind":"質問・要望","question":"整備についてここでお伺いをさせていただきたいんですけれども、温水プールの温度というんでしょうか、昼とか夜とか使う場合も温度が違うのか。温度を決定するというんですかね、それはどなたが何度の設定をするとかとお決めになるのか、その辺を教えていただきたいんですけれども。","respondent":"堀越文化スポーツ振興課長","answer":"プールの温度ですが、室内の温度は３１度、水温が２９度という形で、一般的な温水プールの温度、室温管理はそのような形で行っております。","id":"exchange-047"},{"speaker":"山元委員","kind":"質問","question":"もう一方、プールから一時上がって、また着替えたりする更衣室があるんですけれども、そちらの温度というのも決まっているのでしょうか。実は、やはりちょっと寒いとか、いろいろ苦情があったりもしたものですから、この辺の温度も決まっていますか。","respondent":"堀越文化スポーツ振興課長","answer":"こちら、３１度はプール内の室温ですが、着替えた後という部分ですが、学校の形状によって違います。そういったものを設置したりですとか、それぞれ要望に応じて工夫を図って、ご利用しやすいような形で運営に努めているところです。","id":"exchange-048"},{"speaker":"山元委員","kind":"質問・要望","question":"そういう意味では、温度というのは、とても体感温度というのは大事なことなので、ぜひこの辺はきちっとしてほしいと求めました。係の方と言っていいんでしょうか、ＡＥＤでしょうか、そういうことができる方がその場にいらっしゃるのかどうか教えてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"プールの一般開放の時間帯にはプールの監視業務の人員を配置しております。例えば泳力もそうですけれども、そういったプールの監視業務の中で、もし何かあった場合には対応するという形になります。","id":"exchange-049"},{"speaker":"藤原委員","kind":"質問","question":"歳入全般でお伺いしたいんですけれども、まず１０４ページの有価証券についてお伺いしますが、内容はわかっております。財源と経常収支についてお伺いしますが、２３区でもこういう形になるんだなというのは、ある意味いろいろな勉強に自分自身なりました。","respondent":"榎本人事課長、金子企画財政課長","answer":"区の職員の福利厚生のために持っていた会員の施設の会員権を互助会のほうに売り払って、区のほうにこの歳入が入ったという形です。不納欠損が出てしまうということで、それを回避するということで… 経常収支比率を中心にしたお尋ねですけれども、冒頭ご説明申し上げましたとおり、品川区でも経常収支比率は３.４％ほど数字が落ちております。","id":"exchange-050"},{"speaker":"藤原委員","kind":"確認","question":"ですから、企画財政という課なんですから、その辺はいかがでしょうか。それと、区債と基金についてお伺いしたいんですが、たしか２年ほど起債していなかったですよね。","respondent":"榎本人事課長、金子企画財政課長","answer":"それを廃止するかわりにこの部分で、その当時は区が保有をして、職員の福利厚生に使っていた。その部分で有価証券を手に入れることで、保養所機能はそのまま互助会のほうが使えるということで、そういう判断をしたものです。一番最初、ちょっと難しい質問かと思いますが、私ども、平成２１年度から新しい長期基本計画をスタートさせております。","id":"exchange-051"},{"speaker":"石田委員","kind":"質問","question":"私のほうからは成果報告書の都委託金、１０３ページの教育費委託金のスポーツ教育推進校委託金と英語教育調査研究事業委託金についてお伺いします。初めにスポーツ教育推進校委託金と英語教育調査研究事業委託金、この内容について、この２点お伺いをします。","respondent":"冠木指導課長","answer":"品川区といたしましては、この事業に３校、源氏前小学校、御殿山小学校、八潮学園が手を挙げまして、３校指定されているです。平成２１年度に小中学校を連携した英語教育、後地小学校、荏原第一中学校が指定を受けたものです。","id":"exchange-052"},{"speaker":"石田委員","kind":"質問","question":"これ、平成２１年度は違うと思うんですが、今後これを継続して調査をされるのか。調査研究と書かれて、調査研究というのも、主にどういった事業があるのか、その内容をもうちょっと詳しく説明を求めました。","respondent":"冠木指導課長","answer":"スポーツ教育推進校の３校の使い道ですけれども、これは日本全国、瞬発力というようなところに若干の課題があるというのは私どもも認識しております。平成２２年度については、平成２２年度予算に向けて、この研究については区としてさらに充実をさせていこうという考え方です。","id":"exchange-053"},{"speaker":"石田委員","kind":"質問・要望","question":"それは要望で終わりますが、その辺、ほかの学校との違いを教えてほしいと求めました。どうしてもこれは品川区でやっていきたいんだというものに関しては、ぜひとも積極的に品川区で独自に予算をつけて実行してほしいと求めました。","respondent":"冠木指導課長","answer":"そういったものを子どもたち一人一人が装着する中で、体育の授業を工夫していくとか、そういった取り組みがなされているところです。なお、英語教育については、力強い応援をいただきまして、ありがとうございました。","id":"exchange-054"},{"speaker":"石田委員","kind":"意見","question":"中学校では、そういった意味では、ぜひともスポーツを通じて子どもたちの健全な育成に臨んでほしいと求めました。英語教育、しっかりと取り組むように、僕たちもまた提言等もしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"辞退者などを引いた数字だったんでしょうか、区が発表する４月１日現在の待機児は６６人ということなんですけれども、教えてください。保育園に入れずに仕事をあきらめて申し込まなかった人や、申し込んだとしても認証に入った人や転園希望の方は除いていることでよろしいんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"待機児童として国の基準に基づき算出した方の人数は６６名です。この６６名という数字は、あと、区外からお申し込みをしていらっしゃる方などの数字は除いてあります。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"その中で、４月１日現在の待機児はなぜか６６人と、これは一たん改めて申し込みをされた方でないとこの６６人にならないと思うんですね。４月入園でかなわずに、仕事をあきらめて申し込まなかった方もたくさんいらっしゃると思うんですけれども、そこはどうなんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"この６６人は、国から出されています待機児童の報告の基準に基づいて算定をしております。４月１日現在で保育園を希望しているということがありますので、４月１日におきまして保育園の入園を希望している方という形でお出ししています。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"つまり４月１日で、不承諾通知を受けた方には改めて新年度には申し込みの必要がありますよというご案内が入っているわけですよ。ですから、改めてその通知を見て申し込みをされた方ということでよろしいんですよね、今の答弁は。","respondent":"伊崎待機児童対策担当課長","answer":"不承諾通知をお出しする中に、引き続き保育園を希望される方は４月１日から申し込みをしてくださいというご案内が入っております。これに基づきまして、ご申請を出されない方というのは、４月１日以降のご入園を希望されないという判断をいたしております。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて希望する方が全員入園できる待機児解消、認可保育園の計画的な大幅な増設でもって目指すことを求めたいと思います。来年がどうなるかと、今年１０月時点での申し込み人数、昨年の同じ時点での申し込み人数を伺います。","respondent":"伊崎待機児童対策担当課長","answer":"それの１つには、認証保育所の運営助成金などの効果があらわれているものと考えております。計画的な認可保育園の開設支援、あるいは幼保一体施設の計画的な整備等含めまして、これまでと同様に取り組んでまいる所存でおります。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"区商連との委託契約の内容についてお伺いしますが、今年も含めていただきたいんですが、ここ３年ぐらいの配食実績数を教えてください。安否確認という点もあるでしょうし、一体どれを目的にしているのか、お伺いします。","respondent":"秋山協働・国際担当課長","answer":"平成１９年度が１万６,０００食、平成２０年度が１万４,７００食、平成２１年度が１万４,１００食という形になっております。講習会などを行い、お店をご利用されていた方で、見守りということも含めて今やられていると考えています。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"委託の件ですけれども、総額５３０万円ということですが、１食につき幾らという契約ではないのか、それとも、委託契約期間というのがあるのか、そこら辺をお伺いします。","respondent":"秋山協働・国際担当課長","answer":"１食当たりの単価は、区商連に対して９００円です。契約期間は１年、４月から３月３１日までということになっております。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"メニューとかも、以前はよくいただいていた方が手をつけなくなってしまったというような声も数件伺っているので、どうチェックしているのか。じゃないと、サービスが低下してしまうと思うんですが、いかがか尋ねました。","respondent":"秋山協働・国際担当課長","answer":"それから、チェックにつきましても、アンケート等をしておりますので、それについてフィードバックしていくです。配食を継続的に続けていくということで、地域の商店とそれから地域の商店の活性化も含めて効果があるということで進めているところです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"以前行っていたような配膳の工夫ですとか、あと、メニューの工夫ですね。ぜひそういった観点から、横の連携もとりながら、高齢者のサービス受け手の方にとってよりよいサービスになるよう努力をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"武内委員","kind":"質問・要望","question":"私は９７ページの水道管直結化事業負担金、それから１０９ページの水族館運営費収入の２点でお伺いしたいと思います。この主な理由について教えていただきたいのと、区でも１０分の８の負担金ということで取り入れたと思うんですが、これもあわせて説明を求めました。","respondent":"田村庶務課長","answer":"９７ページで既に水道管直結化事業につきましては、公立の小中学校の、特に小学校のみ開設して実施してきたものです。大井第一小学校から開始しまして、当初予定した２校以外に、２校追加して合計４校ということで実施したものです。","id":"exchange-064"},{"speaker":"武内委員","kind":"質問・要望","question":"そうしますと、歳入のほうで負担金が増えたのは、２校分が追加になったということで理解をさせてほしいと求めました。早急に拡大をというような要望もさせていただいたんですが、今後都の動向も踏まえた上でどう実施していくかということについて、説明を求めました。","respondent":"田村庶務課長","answer":"水圧自体でやろうということで、当初は小学校のみ、基本は３階のみの小学校ということで考えていました。当初モデル事業だったんですが、今の段階では、平成２２年度から中学校も実施して、あわせてこの事業そのものを平成２８年度まで延長して普及を図る。","id":"exchange-065"},{"speaker":"武内委員","kind":"質問・要望","question":"今のお話だと平成２８年度まで延長されるということなので、その間に可能な学校についてはすべてやっていくということでよろしいんでしょうか。一応答弁ほしいと求めました。","respondent":"田村庶務課長","answer":"もう既に１０校近くやっていまして、学校の構造上可能な学校は具体的にさらに推進していきたいと考えております。","id":"exchange-066"},{"speaker":"武内委員","kind":"質問","question":"それから、次の質問で、水族館の運営費収入についてお伺いしたいと思います。当初予算は１億３,５６５万４,０００円ですか、決算のほうでは８,５００万円余りということで、この主な要因について説明を求めました。","respondent":"藤田水とみどりの課長","answer":"水族館運営費の歳入の部分ですが、予算時点では入館者の予測を６１万人ほどということで当初考え、計上しておりましたが、決算の段階では５３万９,０００人ということで、入館者が減ってしまったということが主な原因です。","id":"exchange-067"},{"speaker":"武内委員","kind":"質問","question":"おそらくこの中には集客をどうしていくかということもあると思うんですが、こういう予算特別委員会のときにほかの委員からの質問であったんですが、こういう見込みについて説明を求めました。","respondent":"藤田水とみどりの課長","answer":"それぞれの事業を進める中で、いろいろ検討を進めているわけですが、現在両者間の検討だけだとなかなか先の検討が見えにくくなってきてあります。","id":"exchange-068"},{"speaker":"武内委員","kind":"質問","question":"その辺はどうなんでしょうか。その辺も含めて説明を求めました。","respondent":"藤田水とみどりの課長","answer":"そういった面では、これからも水族館とどう進めるか、これは一生懸命考えていきたいと思ってあります。その中で、弱点だと思うところもはっきり導き出して、それをどうすればいいのか、それについてしっかり考えていきたいと思ってあります。","id":"exchange-069"},{"speaker":"武内委員","kind":"提案","question":"わかりました。アドバイス、ご提案させていただければしっかりさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"伊藤委員","kind":"質問","question":"私は歳入歳出決算書の収入全般に関連してと、それから、財政調整制度に関連をして、まずこの２つをお伺いします。当時の企画財政課長から検討するという話をいただいていたんですが、その後はどうなったんでしょうか、お答えいただければと考えています。","respondent":"日下部企画部長","answer":"今議会に提出をさせていただいている予算書、決算書の一定のルールといいますか、その枠組みの中ではなかなか難しいところがやはりあります。例えばひとつ参考的な資料として検討するとか、そういうことも含めまして、改めて少し詰めさせていただきたいと思います。","id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問","question":"いろんな仕組みがあるでしょうから、だけれども、これは行政が品川区議会に対してどういう敬意を払うかですね。配当割交付金、株式等譲渡所得割交付金ですか、軒並みマイナスになっています。","respondent":"金子企画財政課長","answer":"漫然に取り組むのではなく、今年度実施しましたように、これらを私どもとしましては鋭意努力して進めていくという考え方が基本であります。それを一言で申し上げれば、小さな区役所から大きなサービスをということ、これを基本としてやっていきたいと考えています。","id":"exchange-072"},{"speaker":"伊藤委員","kind":"質問・要望","question":"特に大都市圏、例えば東京とか名古屋ですかね、そういうところの財源は根絶やしされていく危険性は相当ある。ですから、おそらく行政のいろんな話が出ているでしょうから、そのことについての答弁もいただければと考えています。","respondent":"濱野区長","answer":"さまざまな面で地方財政へのしわ寄せということについては、さまざまな面で対応を考えていかないといけないんだろうと考えています。財政当局も十分に考えておりますので、今後の対応についてもしっかりとした対応を図っていくように努力したいと考えています。","id":"exchange-073"},{"speaker":"伊藤委員","kind":"質問","question":"例えばアメリカでは、全米でやっていたものが、実際２年後には１つの州しかなくなったということもあります。こういうことも勉強してわかってまいりましたので、質問させていただいて、ご答弁いただければありがたいです。","respondent":"吉田品川区保健所保健予防課長","answer":"しかし、ワクチンだけでは、ご指摘のように、子宮頸がん、予防することは十分できませんので、やはり検診とあわせて効果の判定をしていく。しかも、死亡率ということで、今後モニタリングをしていくといった形になろうかと思います。","id":"exchange-074"},{"speaker":"伊藤委員","kind":"質問・要望","question":"正確に言うと款が違うのであまり細かくは突っ込みませんけれども、事業の点検、私たちもぜひやるように要望しました。ですから、お願いしたいことは、そういう観点で対処していっていただきますようにお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"歳入全般についてお尋ねをしたいと思います。お考えを伺いたいということと、税外負担の適正化という観点で、それも今後の検討の１つになっていくのでしょうかということをお尋ねします。","respondent":"武内税務課長、金子企画財政課長","answer":"税収の増ということをどのように考えていくかということですけれども、区民の方の所得が上がれば税収が増えるということが区民税関係。区民の考え方で、たばこの売り上げ本数が下がっていくという… なかなか法制度の枠の中、あるいは都区制度の枠の中で、この部分が実現できないということが大きなハードルとしています。","id":"exchange-076"},{"speaker":"高橋委員","kind":"質問・要望","question":"そしてかつて事務事業評価を行われたと伺っていますが、その後本当に、その次年度に廃止になったのか。あるいは、廃止しなければいけないというふうに判定、評価が出たらば、そのときの視点は何だったのかということをお尋ねしたいんですが。","respondent":"久保田行財政改革担当課長","answer":"平成２２年度に行います前に、平成１３年度から１７年度にかけまして５年間事務事業評価をやってまいりました。評価を行いまして、その翌年度以降も見直しをしていくといった形で、事務事業の見直しを行ってきたといったところです。","id":"exchange-077"},{"speaker":"高橋委員","kind":"質問・要望","question":"平成２２年度に事務事業評価をされていますので、平成２３年度予算に反映させていくということで理解しているのですが、よろしいでしょうか。どのように反映させていくのかという、平成２３年度予算を含めた今後の施策に関して、その点もお聞きしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"平成２２年度の事務事業評価につきましては、予算特別委員会の前に行財政改革特別委員会のほうでもご説明いたしましたけれども。区民の方や、平成２２年度の事務事業評価とあわせまして、そういった仕組みについても現在検討しています。","id":"exchange-078"},{"speaker":"井上委員","kind":"確認","question":"それから、それから８８ページの総務手数料の情報公開手数料、それから９８ページの民生費補助金の病児・病後児保育についてお伺いをいたします。ここの負担金や使用料などは歳入のどこかにあるのかどうかということをまず確認させてください。","respondent":"間部高齢者いきがい課長","answer":"いきいきラボ関ヶ原の運営についてお答えいたします。こちらにおけます収入につきましては、区歳入に上がるものはございません。","id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"この中で、この施設がシルバーセンターと入り口が別ですけれども、外部からは一体的に見られているというような状況かと思います。現状で区はその問題意識を持っておられるのかどうか伺います。","respondent":"間部高齢者いきがい課長","answer":"１階のシルバーセンターにつきましては、これは高齢者の憩いの場としての整備ということで、現在区内で１６カ所で運営をしているものです。１階と２階に分けてありますけれども、我々といたしましては、それぞれがそれぞれの機能を果たしているものと認識しています。","id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"ちょっと質問がわかりにくかったかと思います。ちょっと区への依存度が高いのではないかと思いますが、そのところは改善が必要なのではないかと思いますけれども、見解を伺います。","respondent":"間部高齢者いきがい課長","answer":"区の委託事業ですいきいき脳の健康教室やパソコン教室を実施するほかに、自主事業については当然会の中での会計ということでやられているです。当面ある一定の年限については支援を強めるということで、今この間３年ほど支援をしてきたわけですけれども、今後につきましては。","id":"exchange-081"},{"speaker":"井上委員","kind":"質問・要望","question":"お話も伺いましたけれども、担い手不足ということで、現在は午後しかそこのところを活用していない。その辺をシニアネットと協議をして、もうちょっと広い活用の仕方もあるかなと思うんですが、いかがか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"いろんなお話も伺っていますので、その点も踏まえて、地域の方にも認識をしていただけるような努力をしてまいりたいと考えています。","id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"せっかくいい施設があるわけですから、ぜひ活用してほしいと求めました。シニアネット活動支援というところと別に、４００万円がコンサルタントに委託されているんですが、この事業の目的と決算額を説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"主には、あとシニアネットの会の運営の補助、あと一般的な高齢者クラブ等の活動の活性化やそのＰＲということを含んだ委託になってあります。","id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"今、来年に向けて公平にここのところは判断をしていただきたいなということで、これは要望でぜひお願いしたいと思います。どういうふうな充当事業の考え方があるのか、お伺いいたします。","respondent":"金子企画財政課長","answer":"委員、今ご指摘のとおり、全体では、平成２１年度、１５事業に充当してこれを実施しております。基本的な考え方として、短期的に皆様方にさまざま啓発を含めて訴える中で、今後の効果を上げていこうということで選択しているものです。","id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"例えば若者の就労支援の調査とか、待機児に至る原因を知るための保育ニーズの分析調査とか、そういったこともできるのではないかと。これからもこういった事業があった場合に、そういう考え方も必要だと思うのですが、見解を伺います。","respondent":"金子企画財政課長","answer":"あるいはひとり暮らし高齢者の訪問調査、これは後の具体的な事業につなげるようなものとして考えているところです。その中で私どもとしてできる限り先に向けて効果が得られるようなところに活用してまいりたいという考え方で今後も行きたいと考えています。","id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひほかの自治体のことも調査をしていただいて、広く取り入れていただきたいなということで要望します。次は、総務手数料の情報公開手数料ですけれども、情報公開手数料を有料にしている理由を改めてお伺いしたいと思います。","respondent":"中川原広報広聴課長","answer":"品川区では地方自治法の第２２７条に規定する特定のもののためにする事務というのに情報公開事務が当たると解釈しまして、そのためには相当の労力を要しますので、そういった根拠で負担を求める観点から手数料をいただいているものです。","id":"exchange-086"},{"speaker":"井上委員","kind":"質問","question":"むしろ行政は歓迎すべきではないかと思うんですけれども、２３区中有料のところが何区あるのか、お知らせください。それから、平成２１年度、６６６件の請求のうち、区外の事業者や個人の方たちの割合はどのぐらいを占めているのか尋ねました。","respondent":"中川原広報広聴課長","answer":"前回お尋ねのときは３区とお答えしましたが、有料とする区は２区増えました。区内が２割弱で区外が８割強です。","id":"exchange-087"},{"speaker":"井上委員","kind":"意見","question":"今の３区というのは、いつの時点の調査なのか。中央区と品川区だけなんですが、データがどちらなのかなと思いますが、３区に増えたとおっしゃったんですがとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"３区が５区に増えたと申し上げました。５区というのは、直近の、この決算特別委員会のために担当に調べてもらったところです。","id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"こういった開示請求のところで、区民の人たちが区がどういう事業をしているかとか、むしろどんどん情報公開が進められるべきだと思います。協働を図っていくということがこれからは求められるし、その辺の認識が区はどういうふうに感じていらっしゃるのか尋ねました。","respondent":"中川原広報広聴課長","answer":"この制度を活用したいろんな問題が起こってきているということも踏まえて、この制度の運用を適正にやっていかなければいけないというところなんです。","id":"exchange-089"},{"speaker":"阿部委員","kind":"質問","question":"それから、人件費なんですけれども、ずっと人件費減り続けておりまして、どの程度を適正と見ているのかという区の大きなお考えを伺いたいと思います。１回申請ではやはりちょっと危ないのではという気もしているんですけれども、その辺の不正とのかかわりでお考えがあれば説明を求めました。","respondent":"武内税務課長、金子企画財政課長、梶戸籍住民課長","answer":"普通徴収の方も当然給与所得者でいるわけですけれども、その方たちが４,０８５人、平成２０年度分の決算よりも増えている。… ２３区平均で２０.４％のところを１８.８％ですから、数字としては良好なほうだと考えていますが、分母によっても左右されます。人件費そのものが２.４… ７月から交付手数料１,０００円から５００円という形で改めまして、なお一層、住基カードをとりやすくしたところになってあります。","id":"exchange-090"},{"speaker":"阿部委員","kind":"質問","question":"分析と言いましたのは、こうした政策が奏効してこういう結果であったというようなことが伺えればなと思いましたので、ご答弁お願いします。お一人当たりがどんどん減っていっているということなのか、それとも若い人の比率が増えたとか、何か構造的な変化があるのであれば説明を求めました。","respondent":"武内税務課長、榎本人事課長","answer":"平成１９年に税源移譲という、その分、税額が平成１９年から大きく毎年のようにプラスになっております。そういう政策もある中で、区民税が平成２１年度分については、平成２０年度と同等の数字と考えております。職員数の関係ですけれども、平成２２年４月は新規採用職員数欄、ご覧いただくと、１７８名ということで、大幅な増になっています。","id":"exchange-091"},{"speaker":"阿部委員","kind":"質問","question":"今後、品川区の職員構成というのは少し若返っていって、人件費として減ってくるということなんでしょうか。職員としてある程度のボリュームをキープすることはとても大切なことだと思っているんですが、その辺のお考えはいかがでしょうか、説明を求めました。","respondent":"濱野区長、榎本人事課長","answer":"要するに国際都市東京の表玄関というポテンシャルが上がっていることによって、税収も増えているんだということをお話を申し上げてまいりました。そういう緻密な調査によって裏打ちされたものではありませんけれども… それに対応して、できるだけ最少人数で努力はしておりますけれども、一定数は補充していかなきゃいけないという考え方があります。","id":"exchange-092"},{"speaker":"阿部委員","kind":"質問・要望","question":"ぜひそこは丁寧に自覚的にできるだけの資料もそろえていただきたいし、それにあわせた政策を打ってほしいと求めました。人件費のほうは、数字で出すというのは難しいかもしれませんが、考え方だけでもご答弁ほしいと求めました。","respondent":"榎本人事課長","answer":"例えば２０代から５０代まで考えれば、なるべくそれに近づけるような形で人員構成をつくっていきたいという考えです。今度逆に若い人の多い世代が上へ行けば同じようなことになってしまいますので、その部分を十分考慮して、採用計画を立てていきたいと考えております。","id":"exchange-093"},{"speaker":"山路委員","kind":"質問・要望","question":"１点目は８７ページ、２点目は１０９ページ、放置自転車対策についてお伺いいたします。ここで区民の方が定期利用をしたいのであいていますかと指定管理者の現場の方にお伺いしたところ、全くあいてない、非常に冷たい態度で言った。","respondent":"藤木交通安全担当課長","answer":"実態としまして、五反田の定期利用は利用率といたしまして７割から８割程度ということで、事実としては駐輪場はあいていた。そのような状況です。","id":"exchange-094"},{"speaker":"山路委員","kind":"質問・要望","question":"７割から８割ということで、表示といいますか、こういうきめ細かな心遣いも必要かと思います。放置自転車をやっぱりなくしていくような、こういう努力をしてほしいと求めましたが、その辺についてはどのようにお考えか尋ねました。","respondent":"藤木交通安全担当課長","answer":"日報の提出などもこの春ぐらいから必ず行うようということで、私のほうで点検をして、サービスを求めております。２点目の五反田駅周辺の駐輪場ですけれども、駐輪場の整備等をやっていけないかと、その辺の検討をしています。","id":"exchange-095"},{"speaker":"山路委員","kind":"質問・要望","question":"あそこは私道の道路とお伺いしておりましたが、こういう方たち、非常に喜ばれていることをこの場をおかりいたしましてご報告をします。あれだけの多くの自転車をとめるのか、この辺の状況について掌握されていたら、情報を聞かせてほしいと求めました。","respondent":"藤木交通安全担当課長","answer":"駐輪場の管理員のほうで、駐輪場のあいているスペースをご案内したりするなどして、利用に見えた方にはそのような対応をしています。そのようなことはないんですけれども、ご自分で勝手にと申しますか、そちらのほうへとめていただいた方なのかなと考えております。","id":"exchange-096"},{"speaker":"山路委員","kind":"質問","question":"もう少し整備して、駐輪場は私もよく利用するんですけれども、まだあいている日が多いですよね。整備をさらにお願いしたいと思いますが、今後どのように考えていらっしゃるか、お伺いします。","respondent":"藤木交通安全担当課長","answer":"大変失礼いたしました。近辺、指導ならびに撤去などをこの夏ぐらいから進めている地域ですので、通行しやすい道路になるようにこれからも進めてまいりたいと考えております。","id":"exchange-097"},{"speaker":"山路委員","kind":"質問・要望","question":"そうじゃなく、せっかく駐輪場がありますので、駐輪場に駐輪できるように促していただきたいということですね。この辺をさらによろしくお願いいたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"原委員","kind":"質問","question":"午前中からいろいろお話を伺っていて、良という感じなものですから、私はどういうふうにして聞いていっていいのかなという気がします。以前お聞きしたときに、雑の部分が１億９,０００万円、この中身をお教えほしいと求めました。","respondent":"金子企画財政課長、中川原広報広聴課長、太田品川区清掃事務所長、三宅都市開発課長、冨岡高齢者福祉課長","answer":"雑入のところの幾つか、私のほうからお答え申し上げます。これが４,６００万円ほどありまして、かなりのウエートを占めているという内容です。広告料の伸びについては私のほうからご説明いたします。２０万部という大きな印刷数ですので、それからホームページのバナー広告の収入が増している… 平成２０年の９月の米国に端を発しますリーマンショックによりまして、平成２０年の１１月以降、市況価格が下落をいたしました。それが平成２１年度… 私用光熱水費について私のほうからお答え申し上げます。","id":"exchange-099"},{"speaker":"原委員","kind":"確認","question":"ほかのところは大体そうですかという、昨年から都市基盤整備費収入、これは１００倍ですよね。この１６億円、まずそれと後見制度のことの確認、２点お願いします。","respondent":"冨岡高齢者福祉課長、金子企画財政課長","answer":"何といいますか、省略をしていくということがありますので、その部分が反映されていると思います。件数は増え、場合によっては、それほど金額は増えていかないという状況が続く可能性があります。ただ、決算書の組み立ての中で寄附金のところにこういったものが入っておりますと、地方財政法の割当的な寄附と疑われるおそれが出てまいります。","id":"exchange-100"},{"speaker":"原委員","kind":"質問","question":"確かに諸収入が約６０億、そのうち雑というのが２９億ですか、半分、５０％だからバランスがとれているということで。ですから、ここでお願いをしたいのは、例えば入りのここのところで１６億というのはある程度すごい数字かなと思います。","respondent":"金子企画財政課長","answer":"１６億という金額は、今後とも予算の科目については、きちんとした整理する形で見られるような形を努力していきたいと考えています。","id":"exchange-101"},{"speaker":"宮崎委員","kind":"質問","question":"私は成果報告書８０ページの財政調整交付金に関連して、再開発の補助金について伺いたいと思います。この補助金の増額についてどういう経過で、いつ方針化したのか、まず伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"特に北品川五丁目第１地区ならびに大崎駅西口南地区という状況のお話ですけれども、事業費の見直し等々含めて、事業者のほうが再精査したものです。その結果として、一部補助金を変更して、対応してきたというところがあります。","id":"exchange-102"},{"speaker":"宮崎委員","kind":"質問","question":"１つ伺いたいのは、質問したんですけれども、こうした財源の確保の見通しがどういうふうになっているのか。あわせて国の補助金も、そういう見通しがあるのか、ないのか、伺いたいと思います。","respondent":"三宅都市開発課長、金子企画財政課長","answer":"国の補助金ですけれども、今見通しを報告しまして、確保されるように調整しております。なお、都からは補助金はもらっておりません。 再開発に関する財調についてのお尋ねですけれども、これは翌年度になります。翌年度以降４カ年で計算されて、対応補正と言うんですけれども、計算されて、財調のほうによってくるというふうな形でいただいております。","id":"exchange-103"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど北品川五丁目第１地区と南地区以外にもそういうことをやっているのがあるのかどうなのか聞きたいということと。こっちのほうから回したりする、そういうやりくりをするのかどうなのか、聞きたいと思いますとの意見を述べました。","respondent":"金子企画財政課長、片田防災まちづくり事業部長","answer":"先ほど申しましたとおり、翌年度から４カ年、その前提となるのが都市計画交付金なんですけれども、そういう形で４カ年で入ってまいります。これは、ルール化されておりますので、全体のパイどうのこうのということとは直接関係なくて… 今権利変換計画を進めて行っている中で、事業の見直しを行って、それの再精査を行って、手続を進めていくといったような段階です。","id":"exchange-104"},{"speaker":"宮崎委員","kind":"確認","question":"そこのところを確認しておきたいと思います。おおよそ、前後でどういうふうになったのか、伺いたいと思います。","respondent":"三宅都市開発課長","answer":"大崎駅西口南地区ですけれども、工事費につきましては、内容を仕様などを見直しまして、約５％低減しております。そういったことで、差し引きで、増減がないような状態になっているです。","id":"exchange-105"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところはどうなのかということを１つ聞きたいのと、やっぱり疑問のところですよね、南地区のところは。その見直しを踏まえて、そこに何か判断が入っているのかどうなのか、ここのところはどうなんか尋ねました。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"１点目の補償費ですけれども、計上漏れといいますか、建物の中まで精査できていなかった。権利変換のもとの資産ではなくて、資産としての評価ではなくて、補償の部類に入るものが増えたために補償費が増えたです。精査する中で、２７０億円で基本的には変わってきてないというところがありますけれども、イコールの数字になってきたというような状況です。","id":"exchange-106"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところを聞きたいのと、そうしますと、今、結局補助のほうは対象事業の３分の２まで補助ができる。３分の２まで全部行くぞという考えがあるのか、そこの気持ちのところ、考えのところを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"それがだんだん……。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"これらの違いはどういうところにあるのか。４番と６番でしょうか、それからなぜこのような状況になっていて、区はどういうふうな対策を考えているのかをまずお聞きしたいと思います。","respondent":"武内税務課長","answer":"３つ目の執行停止即時消滅分というのは、午前中話があったように、今現在どうしてもこれは払えないと。財産も全然ない、預金もないというような状況の場合については、不納欠損という、即時消滅させるという、そういうものです。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"それに対する区の対応をどうされるのかということを、国民健康保険についても、その辺についてお聞きしたいと思います。両方お聞きしたいと思います。","respondent":"武内税務課長","answer":"２億８,５００万円、平成１９年度については４億円という大きな金額なんですけれども、こういう数字が出てくるという状況です。その後、これは不納欠損で落とすしかないですので、その辺はしっかりした私どもの調査に基づいて執行していくという考えです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"それも踏まえると、それは帳尻が合えばいいんですけれども、帳尻が合わなくなったらどうするのという。非常にやりにくい状況になっているのではないかなと思いますが、その点に関しての今後の考え方をお聞きしたいと思います。","respondent":"金子企画財政課長","answer":"なかなか絵姿が見えてこないという状況がありますので、これを注視しながら、対応が遅れることのないようにしていきたいと考えております。それは私ども、私なりに見通しをまた別に立てまして、できる限り正確に補足するように対応するつもりですし、してきたところです。","id":"exchange-110"},{"speaker":"西本委員","kind":"意見","question":"国も、一括交付金の話も出ていますけれども、どういう形で削減というのをひっくるめてやっていくのか。行政側のほうも収集していただいて、議会といろいろ議論しながら決めていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうから成果報告書の８７ページの区民住宅使用料に関連してお伺いをします。決算書の４３ページですが、収入未済額が３,６７６万６,５９３円、現況についてまず冒頭お伺いをさせてほしいと求めました。","respondent":"柏原住宅担当課長","answer":"残りの２,５００万円ほどなんですけれども、こちらのほうがどうしても滞納ということで、収納がなかなか難しいと。退去されている方とかもいらっしゃいますので、こういったところで滞っている部分があるです。","id":"exchange-112"},{"speaker":"堺委員","kind":"質問","question":"先般お聞きしたところによりますと、平成１７年以降、こういうことから指摘をさせていただきました。この件について、簡単で結構ですが、ご説明いただければ大変ありがたいと思います。","respondent":"柏原住宅担当課長","answer":"その他、入居の基準については、変更を行わない。現在オーナーへの借上料、こちらのほうも変更は行わないです。","id":"exchange-113"},{"speaker":"堺委員","kind":"確認","question":"確認をしておきたいんですが、新たに３月１日から入居される方については、確認をしておきたい。いずれまた早い時期にそれなりの手を打つということなのか、この辺のところもあわせてお考えをお示しほしいと求めました。","respondent":"柏原住宅担当課長","answer":"バランス等も考えまして、現在お住まいの方につきましても、同様の家賃ということでやらせていただく予定です。８０％ありますので、行く行く入居率が例えば５０％を切るであるとか、適用するかどうかというのは考えていきたいと考えています。","id":"exchange-114"},{"speaker":"堺委員","kind":"質問・要望","question":"予算特別委員会のときにも申し上げました建設型、これについても区のほうでは対応していただきたいと申し上げました。したがって、建設型のこの件については、今後どういうふうにしていくつもりなのか、その辺のところをお考えをお示しいただければと。","respondent":"柏原住宅担当課長","answer":"こちらのほうは入居率が現在４０％を切るといったところです。その辺も検討しながら、できるかどうかということも含めまして、建設型については今後検討していきたいということで考えております。","id":"exchange-115"},{"speaker":"堺委員","kind":"質問","question":"ですから、同じ至近距離の中で、入居する希望者は、同じ家賃を払うならば、ファミーユ下神明のほうが全然いいと。その辺との絡みの考えはいかがか尋ねました。","respondent":"柏原住宅担当課長","answer":"ファミーユ西品川につきましては、既に建設型ということで、家賃補助がもう切れております。こういったところも含めて、ファミーユ西品川については家賃の問題であるとかいうのは検討していきたいと考えています。","id":"exchange-116"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今、ファミーユ西品川について家賃補助が切れたというご答弁だったんですよね。ということは、もう国の縛りがないから、強いて言えば区独自に打とうと思えば手は打てると理解をしていいのか尋ねました。","respondent":"柏原住宅担当課長","answer":"家賃補助は切れておるんですけれども、区民住宅ということで建てておりますので、建設時の補助もいただいております。いろいろな手続が出てまいりまして、それがいいのかどうかというところもありますので、そういったところも含めてトータルで検討していくです。","id":"exchange-117"},{"speaker":"堺委員","kind":"質問・要望","question":"それは確かにそういういろんな絡みはあるかもしれませんが、このファミーユ西品川はあくまで区民住宅ですから、用途変更はあり得ない。したがって、今回借上型住宅について手が打たれたように、建設型についても早急に手を打ってほしいと求めましたが、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"今担当課長がご答弁申し上げましたように、特に建設型については、建設時に国の補助金、建設費用の補助金をいただいております。その対応がありますので、若干難しいところがありますけれども、今、借上型も含めて、引き続きそれは検討してまいりたいと考えています。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"縛りがあって、国債というのは期限があると思うんですが、これは使えないようになっちゃうんですか。地球環境基金もそうですが、３０億円入っていますが、とりあえず載っけたんだよということなのか尋ねました。","respondent":"金子企画財政課長、福田会計管理者","answer":"私のほうから特別区債の考え方についてお答え申し上げます。９０％は起債を起こせまして、一般財源を振り向ける額が非常に少なくて済みますので、そういったものについては活用していこうという考え方です。 国債を購入いたしますと、途中で手放さない限りは、これは当然現金化されませんので、使うことができません。そういう事態が発生しないように、日々の現金をきちんと確保しながら資金を出納している、これが現状です。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"３０億円のうち２９億円ですか、ほとんどそこでとまっちゃうのかなという感覚を覚えたもので、一応お聞きいたしました。これは翌年度はおよそどのぐらいの金額ベースで減るのか尋ねました。","respondent":"金子企画財政課長","answer":"お金が余ったから事業に振り向けるとか、切るとか、そういった対応で考えている組み立てではないというところをまずご理解いただきたいと思います。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"いろんな意味で、テレビでも報道、放映されていますが、本当に自立して生きていけないというようないろんな状況があると思います。私は積極的に予算化してもいいんじゃないかと思うんですが、そういうところの配慮、対応というのはちゃんとなっているのか尋ねました。","respondent":"日下部企画部長","answer":"先ほどもお答えいたしました。これは切れ目なく今日まで緊急対策として進めておりますし、これも３つの緊急課題ということで、これも含めて進めているです。","id":"exchange-121"},{"speaker":"大沢委員","kind":"質問","question":"８３ページ、使用料及び手数料、そして８５ページ、しながわ中央公園、それと９１ページ、感染症ということ、３点お伺いをします。しっかりとしたここについてのご答弁を伺いたいと思うんですけれども、使用料及び手数料、そして今後の見込みについてお伺いをしたいと思いますので。","respondent":"金子企画財政課長","answer":"今後の見込みですけれども、そういった意味では、区民関係の施設、八潮のほうでありますとか、若干増えてまいります。今後若干増えてまいりますが、手数料の価格が適切かどうかというのは、節目節目できちっと検討していく必要があると考えています。","id":"exchange-122"},{"speaker":"大沢委員","kind":"質問","question":"そこの上で、きちんとした使用料についての額について検討していく必要があるということ。使う気持ちを惹起してもらうような施設であり続けるべきだと思いますけれども、行政側では、どのようにそれについてお考えになりますか尋ねました。","respondent":"金子企画財政課長","answer":"さまざま利用されている方々、それから、そういったところを新しい施設に反映できるようにと。それは単に使用料の価格だけではなくて、さまざまなサービスの部分についても生かしていけるような形で考えていくというのが基本的な姿勢です。","id":"exchange-123"},{"speaker":"大沢委員","kind":"質問・要望","question":"次、しながわ中央公園、８５ページについてお伺いさせてほしいと求めましたが、先ほど課長の答弁の中で、中央公園の前の学校施設があります。民間及び学校法人への貸し付けを具体例を挙げて伺いましたけれども、どのようになっているのか、お尋ねしたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"私立の学校については、平成２１年度については１校、その前にもう１校実績があります。区内の学校が幾つか使用しているという、そういう状況にあります。","id":"exchange-124"},{"speaker":"大沢委員","kind":"質問","question":"去年対応していただいたわけですけれども、そこをつかさどる一番のかなめの方たちである保健師についてお伺いをしたいと思います。それを踏まえまして、本来、行政につかさどる保健師の業務についてお尋ねをしたいと思います。","respondent":"吉田品川区保健所保健予防課長","answer":"あるいは今回起こった新型インフルエンザのように、感染症が発生した場合に、患者のもとに駆けつけて対応する。そういったきめ細かい対応。","id":"exchange-125"},{"speaker":"大沢委員","kind":"質問","question":"しかしながら、ここで１つお伺いをしたいんですけれども、組織変更がされました。この４名の体制についてのお考え、保健師４名に対する、専ら感染症という業務を行うに当たっての４名についてのお考えをお聞かせ願いたいと思います。","respondent":"吉田品川区保健所保健予防課長","answer":"十分これまでの３センターといいましょうか、大井で行っていた人数で十分対応できる、通常の発生状況であれば対応できる人数だろうと考えております。","id":"exchange-126"},{"speaker":"大沢委員","kind":"意見","question":"重きを置いた場合には、そちらのほうが従になって、主は感染症ということになるということでよろしいんですねとの意見を述べました。","respondent":"吉田品川区保健所保健予防課長","answer":"保健予防課の所管している業務といたしましては、重点的にやっているのは感染症ならびに予防接種ですので、母子保健については、ご案内等は保健師のほうでいたしますが、主には該当地区の保健センターにおつなぎしているといった状況です。","id":"exchange-127"},{"speaker":"大沢委員","kind":"意見","question":"では、保健予防課の保健師においては、各保健センター、保健所に対しての司令塔の役割ということであって、実際母子相談、ほかの相談に関しては、相談業務は、そちらのほうにお願いをしてやっていただいている、こういうことでいいんですねとの意見を述べました。","respondent":"吉田品川区保健所保健予防課長","answer":"ご指摘のとおりでございまして、感染症ならびに予防接種業務については、私どものところでメインにやっておるところですけれども、母子保健業務、あるいは精神の実際の個人的な対応といった内容になりますと、各地区の保健センターに依頼をお願いしているといったところです。","id":"exchange-128"},{"speaker":"大沢委員","kind":"質問","question":"ですから、これから１年たったときの検証、おそらく４人体制では足りなくなるのではないかという危惧を持っております。よろしくどうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"土井委員","kind":"質問","question":"住民基本台帳カードですが、何のためにやっているんですか。なぜやるの、どうしていっぱいやらなきゃいけないのというところと、今現在の到達点を聞かせてください。","respondent":"梶戸籍住民課長","answer":"１つ、住民票の写しがとれる、そういったさまざまな可能性を持っているカードです。我々のほうの、先ほども件数お話しいたしましたけれども、３５万区民の方たちの大体４％強が今持っていらっしゃるような状態になってあります。","id":"exchange-130"},{"speaker":"土井委員","kind":"意見","question":"その辺を我々のところはどう発想して、どう考えてやるのかということを問われる時点で、はっきりしてもらわなきゃいけないのではないかな。いろんな発想がどうも皆さんあるようなんだけれども、わかってないというのが今現状なので、その辺をちょっと聞かせてくださいとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"政府もいろいろな健康カードの導入についても検討はしましたが、今後も研究しながら、ある程度これを普及させていく。せっかくつくったものですし、お金をかけずに有効に使える手段を検討していくということは自治体の役割でもあろうかと考えております。","id":"exchange-131"},{"speaker":"土井委員","kind":"質問","question":"ぜひその意味では、区市町村でもやっていますから、いろいろやっていますから、皆さんは、ちゃんとそれを乗り越えたわけでしょうから、きっと。たがら、その辺も含めて、どうお考えか、説明を求めました。","respondent":"吉岡保育課長、金子企画財政課長","answer":"もともとの保育料の考え方、国の徴収基準額という考え方がありますので、そこについても一定の階層の増というようなことも行われております。委員ご指摘のとおり、常に考えていかなければならないし… それからソフトの運営費についてコスト表示をしようということで今検討している最中でありますので、そういう意味では、幾分それにお答えできるかと考えています。","id":"exchange-132"},{"speaker":"土井委員","kind":"質問","question":"なかなかわかっていただけないと思うものですから、申し上げているので、よろしくお願いしたいと思います。そういう中での財調に与える影響みたいなものについてどうお考えか、今後の課題になりますが、説明を求めました。","respondent":"金子企画財政課長","answer":"全体としての中の５５％の配分であるとか、特段ありませんけれども、特別交付金ですね。特別交付金が５％、これについての協議というのも、これは引き続き来年度に向けての財調協議の中で協議が行われるという見通しになっております。","id":"exchange-133"},{"speaker":"土井委員","kind":"質問","question":"来年度、それ以降の見通しについてはいかがか尋ねました。","respondent":"濱野区長","answer":"ご指摘のように、今財調が減っているのは、調整３税が減っているからです。大きな話になれば、それは当然今やっているあり方検討会の一定の結論を見て、結果として配分率の見直しということが行われるだろうと考えています。","id":"exchange-134"},{"speaker":"飯沼委員","kind":"質問","question":"お伺いしたいのと、本会議場の傍聴席の音響効果についてお伺いしますので、よろしくお願いいたします。始めた理由を改めて伺うのと、年齢区分型と幼保連携並列型と２つに区分をされているので、この２つに分けている理由もお知らせください。","respondent":"吉岡保育課長","answer":"それから４歳、５歳の幼稚園、先ほど申し上げたよりよい保育教育を実施するということで考えていたところです。今年度４月の待機児をいかに解消するかという中で、いずれにおいても、十分な質の高い保育教育を実施すべく今取り組んでいるです。","id":"exchange-135"},{"speaker":"飯沼委員","kind":"質問","question":"認定こども園、幼保一体の施設、どこまで増やしていくつもりなのかどうか。既存の保育園への拡大とか、私立の幼稚園とか保育園の組み合わせとかが新たに考えがあるのか、その辺の方向性を説明を求めました。","respondent":"吉岡保育課長","answer":"従来計画的に設置をしてきているところですけれども、６月には、品川地区の幼保一体施設を開設する予定となっています。それぞれの方針をお持ちの上で、私立幼稚園、私立保育園に進めていくという考えは今のところはございません。","id":"exchange-136"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つには、お尋ねをしたいと思いますけれども、子どもの側から幼保一体施設を検証されている部分があるのかどうか。トータルな見方としては、そういった面では、子どもの立場に立ったときにどうなのかというところを説明を求めました。","respondent":"吉岡保育課長","answer":"就労の支援という意味での制度としては、幼稚園に比べれば、サービスの内容としては高い部分もあるのかなと考えているところもあります。","id":"exchange-137"},{"speaker":"飯沼委員","kind":"質問","question":"子どもにとってどうかというところで、お伺いしたんですが、検証をきちんとしているかどうかというところ。みんながそうだねと言えるような検証がちゃんとされているかどうかというところをお伺いしたので、もう１回そこと、全国の中では。","respondent":"吉岡保育課長","answer":"現在幼稚園も保育園もそれぞれ、特に保育園については、それもしっかりした保育教育しているということの１つのあかしであろうと考えております。","id":"exchange-138"},{"speaker":"飯沼委員","kind":"質問","question":"今日質問させていただいたんですけれども、ポイントは、品川の今の水準をよくしていってほしい。水準が下がるような状況だったら、断固反対、拒否をしてほしいなと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"今回の決算特別委員会への資料提供は間に合わなかったのかということを１つ確認をしておきたいのと、来年以降は。これを１つ確認をさせてください。","respondent":"久保田行財政改革担当課長、金子企画財政課長、福田会計管理者","answer":"今評価の作業を進めているところでございまして、今の予定では、１月ぐらいの行革委員会等にご報告ができればと考えているところです。… もうしばらくしますと、落ちるということになるかと考えています。そういう意味では、需要そのものが減ったというわけではなくて… 右から２列目、ここの２９億４,５００万円余、このようにご理解をいただきたいと思います。","id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、それまで５年間やっていた毎年の事務事業評価、たしか決算特別委員会に間に合っていなかったですかね。こういう中でどういうふうに、優先順位をつけて回収というものに当たる、そういうお考えがあるのかどうかというのをひとつ確認をさせてください。","respondent":"武内税務課長、福田会計管理者","answer":"それでも納入がなくて、１年後になりますと、滞納繰越という形になります。財産調査をする等、実施しまして、極力滞納者については徴収する努力をしています。コスト、３つの区分によるコストと、それから債権の回収との関係ですが、区民税収入などにつきましては、かなり大きくまとまったものです。","id":"exchange-141"},{"speaker":"若林委員","kind":"質問・要望","question":"これは、各部署、区役所でどこかでまとまっているものなのでしょうか。件数とか、金額とか、それを確認させていただきたいのと、そのときに、区民に対してどのような対応をされているのかというのを確認させてください。","respondent":"福田会計管理者","answer":"すぐに返していただけることも、大半がそうですけれども、そうではないものもあります。これらを現在統一したところになっているということはございませんし、なかなか統一することは難しいのではないかな、私はそのように思っております。","id":"exchange-142"},{"speaker":"若林委員","kind":"意見","question":"そのときに、払い過ぎましたので、お返しくださいといったときに、どういう対応をされているかとの意見を述べました。","respondent":"福田会計管理者","answer":"そうしまして、それで期限までにお支払いがない場合については督促通知を送付する。この辺で大体回収はできていると考えております。","id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう対応をぜひお願いしたい。私はそれは違うと思うし、そういう意味での区役所を目指していただきたいと思うのですが、何かご答弁がありましたらお願いいたします。","respondent":"古川子ども未来事業部長","answer":"今１つの事例として、児童扶養手当のお話がございました。窓口対応、あるいは実務の中で十分に今後生かしていきたい、このように考えております。","id":"exchange-144"},{"speaker":"渡辺委員","kind":"質問・要望","question":"教えていただきたいのと、リピーター率というんですか、あるいはそういうふうな話を聞いているでもいいと思います。行きたいというのは、やはり最高の評価であると思いますので、まずこの２点から伺います。","respondent":"阿部経理課長、中山地域活動課長","answer":"確かに以前そういう話がございまして、これは方針が閣議決定されているものですので、その方針を変更したとは聞いてございません。凍結というのが正しいのかどうかわかりませんけれども、変更、移転をするという話は出ておりません。 申しわけありませんが、まとめての予約、数部屋とられるケースというのはかなりあります。感覚的なもので恐縮ですけれども、半分ぐらいはそのような利用かなと考えています。","id":"exchange-145"},{"speaker":"渡辺委員","kind":"質問","question":"年に２回という接点、どうですかというよりは、伝えられたほうがいいのではないかと思っています。常に課題はあるかと思いますが、そういった経費の考え方含めて、これから中長期的な取り組みや考え方を伺いたいと思います。","respondent":"中山地域活動課長、阿部経理課長","answer":"客観的に分析しながら、場合によっては、施設のある意味での根本的なあり方の論議をしっかり区の中で考えていく。こういうこととの兼ね合いの中で見きわめていきたいと思います。 当然のことながら、移転反対という立場は変わってございませんので、東京法務局との話し合いの中ではそういう立場で臨んでいきたいと考えています。","id":"exchange-146"},{"speaker":"渡辺委員","kind":"質問","question":"銀行なのか、あるいはコンビニで違いがあるのかどうか、その辺を伺えたらと思います。そういう中で、この金額の点、あるいはどのような評価をされているのか、伺いたいと思います。","respondent":"武内税務課長、秋山協働・国際担当課長","answer":"平成１８年から普通徴収についても、コンビニで収納を開始しているんですけれども、区の窓口は３７.３％です。ほかの部分については、金融機関については、２円ということになっております。 平成２１年度につきましては、個人の方３３名、６０７万４１９円という結果になっているものです。個人が７名、団体が５社ということで、徐々に増えてきているのかなということでは考えておるところです。","id":"exchange-147"},{"speaker":"渡辺委員","kind":"質問","question":"それとか、区民活動支援の目的もあるので、ここは強く行けるのかどうかを伺いたいと思います。この区民との協働事業の軸として、どのように発展していくのか、伺えればと思います。","respondent":"武内税務課長、秋山協働・国際担当課長","answer":"先ほどの答弁で、郵便局につきましては、２円ではなくて、今、資料がなくて、後ほどまた回答します。それは、納税者の方が安全・安心、確実、便利という、そういう視点の中で… その１つとしてお金を出すというような形を考えてありますので、協働の形の１つということで、広く働きかけていきたいということを考えております。","id":"exchange-148"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/260957?Template=document&Id=1324#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":119075,"voices":361}},{"id":"h22-20101101-4","meetingId":"h22-c-settlement","date":"2010年11月1日","dateIso":"2010-11-01","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２１年度品川区一般会計歳入歳出決算","agenda":"◯鈴木委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２１年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"私は、１１９ページの文化スポーツ振興費の中の区民スポーツ大会、そして関連して、東品川公園弓道場について、お伺いしたいと考えています。区民スポーツ大会の現状について、お伺いいたします。","respondent":"堀越文化スポーツ振興課長","answer":"区と品川区スポーツ協会と共催をして実施しておりまして、スポーツ協会と各競技連盟との間で調整をしながら行っているという形になってあります。現に、グランドゴルフの部分は、平成１８年度から新しく区民スポーツ大会に加わっているという状況です。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"よくお伺いするわけですけれども、それにつきましては、土地がないというお話をよくお伺いします。確かに特別養護老人ホーム等の優先順位はあると思いますけれども、そういった部分で、土地があればつくられるのか、お伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"７月から、１０月分の申込みになるんですが、区民優先の抽選申込みというやり方を取り入れました。全体で３割から４割減という形の実績も出ておりますので、いろいろな工夫を図って、振興の場として環境整備を図っていきたいと考えているところです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"近い将来、建て替えとか、改修の予定はあるのかどうかを、お伺いさせてほしいと求めました。特に弓道は弓道場がないとできませんので、新たな新設の予定とかあるのか、どうかお伺いさせてほしいと求めました。","respondent":"齋藤道路公園課長","answer":"耐震基準は達しておりませんので、近い将来、東品川公園にテニスコートとかありますので、その改修にあわせて検討してみたいと思います。お金がかかってしまうものについては、どのようなあり方が正しいのかというのは、これからちょっと検討してみたいと思います。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"品川区の弓道連盟６０周年式典のときに、弓道は、これからの生涯スポーツ社会の推進にとって大変魅力的なものです。見通しとか、そういった可能性はあるのかどうかも、お伺いさせてほしいと求めました。","respondent":"冠木指導課長","answer":"それに先立ちまして、小中一貫教育要領の中でも、武道については推し進めるというスタンスでやらさせていただいているところです。現状の施設上、そういったところはありますけれども、弓道についてもいろいろと調査をしてまいりたいと思ってあります。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"今のところ、地域ワイマックスのサービス提供のめどが立っていないと思いますけれども、現状について、お伺いします。３点目に、どうか、ということについてお伺いします。","respondent":"原情報システム課長、久保田行財政改革担当課長、中山防災課長","answer":"平成２１年度、今年３月に業務継続計画をＩＣＴに特化した形で、マニュアルとして策定したものです。新型インフルエンザといったところについても… それを活用いたしましたメニューのほうがなかなか定まらないといったような状況があるということで、引き続き調査・検討が必要だと伺っております。… 例えば備蓄倉庫がどこにあるとかということは、後で情報を追加することができますので、その辺も検討してまいりたいと考えています。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"情報システム運営費のほうですけれども、地震等の災害時の対応ということで、お伺いしました。これは区民の安全のため、ぜひとも検討を進めていっていただきたいと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、１１５ページの広報紙発行経費、１１６ページ、区民相談経費、１２８ページの選挙公報、３点でお伺いします。雨が降ったらぬれてぐしゃぐしゃになってしまうのではないかという声も出ていたので、ちょっとその辺の仕様の中身についても、お伺いします。","respondent":"中川原広報広聴課長、早津選挙管理委員会事務局長","answer":"それにつきましては、まだまだ体制とか、費用とか、いろいろ検討しなければ、すぐにはできないという結果が出たわけです。果たしてスピードをもって確実に配る方法というのがあるかというのを、今後… 選挙期間が７日間しかないために、３日ほどはかかりますので、どうしても起こってしまうという事情になります。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ１００％を目指していくという姿勢がおありなのか、どうか、ちょっとそこをお伺いします。それから、インターネットなどで公表するといった方法はどうなんでしょうか、。","respondent":"中川原広報広聴課長、早津選挙管理委員会事務局長","answer":"お客様の声をしっかり受けとめるということで、今後も検討を考えていくように、庁舎管理と所管とも相談していきたいと考えています。経費と業者の体力等々を考えますと、実証実験の結果をまとめているところですが… あるいは、配布している部数等について、これまで以上に有権者の方に届くように工夫したいと考えております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"各場所でなくてもいいです、１カ所でも、２カ所でもきちんとした場所を確保してほしいと求めました。せめて月１回からスタートするとか、全戸配布プラスアルファで１００％を目指すという方向は、いかがか尋ねました。","respondent":"中川原広報広聴課長","answer":"いろいろ経過的な作戦は立てたいと思いますが、３９回のうち、月のうち１回というのは、記事の関係でまた非常に微妙な問題がいろいろ出ます。ということですので、これにつきましては、いろいろご意見をいただきながら、さらに検討を進めていきたいと考えております。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"そして１２６ページ、１２７ページの選挙啓発費についても、お伺いしたいと思います。それから、大崎第二地域センター跡地の検討経費に１,５００万円弱が出ているんですが、どういった内容なのか説明を求めました。","respondent":"原情報システム課長、宍戸施設整備課長、久保田行財政改革担当課長、佐藤防災安全担当課長、中山防災課長","answer":"いざ何かあったときの対応ということで、こういったところに借りて、保管をして備えているところです。今でき得る形、費用等々… 部位部材、例えば屋上防水ですとか、外壁、それから機器類等、計画的修繕を行うことにより、区施設を長寿命化させようという計画です。… 私からは、跡地活用検討経費について、お答えいたします。","id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"ちょっとそこを教えてほしいと求めました。もう１点、災害時要援護者の方たちは、避難所はどのように設定されているのか、そこをちょっと説明を求めました。","respondent":"久保田行財政改革担当課長、佐藤防災安全担当課長、中山防災課長","answer":"今後、有効な活用を図っていきたいと考えているところでございまして、将来的な施設に対する区民ニーズにこたえていきたいと考えているところです。… 必要であれば、防災課でも対応できるようにしております。ポンプの点検等については、業者に委託して行っております。避難所の新たな指定につきましては、町会、自治会と十分に話し合いながら、合意の上で進めてまいりたいと思います。","id":"exchange-011"},{"speaker":"石田委員","kind":"提案","question":"１番、２番が上にあって、そういったこともできないのかと思います。これは提案としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"それから、１１９ページ、文化スポーツ振興費の中で、今年、行われました芸術祭の件と伺っていきたいと思います。拒否された件はあったのでしょうか、なかったのでしょうか、お願いします。","respondent":"中山地域活動課長","answer":"これは先ほど申し上げた登録調査員、もくしは場合によっては、区の職員が直接やっております。今回、前回のそういう声が反映されて、郵送なり、インターネットの方式がとられたですので、これはきちんとやっていきたいと思っています。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"５年後に大きい調査があるわけですから、また次にやっていただく方がやりやすいのかなと思って、それは要望します。教えていただきたいのと、どのような形で推移していくか、答えるよう求めました。","respondent":"堀越文化スポーツ振興課長","answer":"芸術祭ですが、中心といたしましては、８月２２日から１０月１７日まで行いました。芸術祭という初めての取り組みで、我々も認識しておりますので、定着を図っていくように頑張っていきたいと考えているところです。","id":"exchange-014"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は、１１６ページの総務管理費の中の広報広聴費のサービス向上運動全般について、お伺いをさせてほしいと求めました。東京都の補助金が出ているから、また現況調査をしたのか、そのあたりの関係性を教えていただけますか尋ねました。","respondent":"中川原広報広聴課長","answer":"今後、新しい長期基本計画の中で続けるかどうかという検討期間でございましたので、イメージアップ運動２１という形で再出発をいたしました。","id":"exchange-015"},{"speaker":"井桁委員","kind":"質問・要望","question":"お伺いをしたんですが、認知度というのでしょうか、ちょっと考えています。案内表示のあり方というのをどのようにお考えなのか、この２点、お願いいたします。","respondent":"中川原広報広聴課長","answer":"平成６年につくりましたサイン計画が、景観の視点も盛り込まないと、なかなか内容が時代に合わなくなってまいりました。こういう表記をしていきましょうという基準を、所管等ともヒアリングを繰り返しながら、実効性のあるものをまとめたです。","id":"exchange-016"},{"speaker":"井桁委員","kind":"質問・要望","question":"この百景をさらに熟成をさせて拡大をしていくというようなことも、今後、ぜひ考えていっていただきたいと、これは要望です。再度ですけれども、必ず観光に生かしていける素材だと思いますので、その点も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"山元委員","kind":"質問・要望","question":"平成１７年から今まで、そういうことが起きたか、その件数を教えていただきたい。そしてまた、協力者たちはどのようなことをするのかを、改めて教えてほしいと求めました。","respondent":"矢部生活安全担当課長","answer":"運用開始から、約４万５,０００件の誤報ということで、平成２１年度末ですけれども、緊急通報につきましては６９件となっております。まもるっちセンターのほうからメール、それから音声メッセージで、児童が緊急通報していますということで流れるような仕組みになっています。","id":"exchange-018"},{"speaker":"山元委員","kind":"質問・要望","question":"実は私も協力者の一人として、何回か協力者通信というものですか、送られてきた記憶があります。今後、協力者としてどのようにしていくのか、教えてほしいと求めました。","respondent":"矢部生活安全担当課長","answer":"したがいまして、今回、協力者の研修会を１１月２５日に実施する予定です。１万３,０００人の方を全部集めるというのは、協力者の研修会を実施して、それから協力者にお願いすることなどを説明していきたいと考えています。","id":"exchange-019"},{"speaker":"山元委員","kind":"質問","question":"前回の予算書には、協力者のボランティア経費ということで３６０万円強計上されているんですが、今回の決算書にはその項目が載っていなかったので、それはどういうことなのかということで質問させていただきました。","respondent":"金子企画財政課長","answer":"平成２１年度予算では、今、ご指摘のところは平成２２年度の予算書かと思います。それにつきましては、平成２２年度の決算のほうでは、きちんと分類して表示していきたいと考えております。","id":"exchange-020"},{"speaker":"山元委員","kind":"質問・要望","question":"５月１０日付の委員会報告で、何か不都合があったということでお聞きいたしました。不都合が起きた件数というのですか、発生した件数を教えていただきたいのと同時に、賠償はどのようになっているのかも教えてほしいと求めました。","respondent":"矢部生活安全担当課長","answer":"行いましたソフトウエアと違いまして、１回、修復するという作業となります。充電ができないというのが約１,４００件、やはり同じく１,４００件ぐらいということで、合計２,８００件ぐらいの件数となっております。","id":"exchange-021"},{"speaker":"山元委員","kind":"質問","question":"改善の余地といいますか、このまま使っていて大丈夫なのかというか、その辺はいかがなんか尋ねました。","respondent":"矢部生活安全担当課長","answer":"１月から８月までで、５００件ぐらいの通常の故障はどうしても起きますので、やはり交換ということで対応していきたいと思います。したがいまして、今回の不具合でハードの交換ということになりますけれども、これで一応、不具合は解消されると認識しております。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"高齢者の見守り機能として、ちょっとこれは違うかもしれないのですが、何か活用することはできないものか尋ねました。","respondent":"矢部生活安全担当課長","answer":"あくまでもＧＰＳというか、まもるっちセンターで受けているオペレーターたち、児童の安全を見守るということでやって…。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"そういう意味において、見直しをしたほうがいいと思うんですけれども、その辺については、いかがでしょうか。来年の７月２４日から、機械類に弱い方にどういうふうに対処していくか、説明を求めました。","respondent":"榎本人事課長、伊勢総務課長、金子企画財政課長、久保田行財政改革担当課長","answer":"区が所有しているものが７２戸、それから民間の住宅を借り上げているものが３０戸で、合わせて１０２戸です。今後の予定ですけれども… これらはそれぞれ特別区相互間の連携、基本的には、あまり区民に直接身近なものではないというところがあります。… これはやはりハードではありませんけれども、そういう観点から、こういう整理の仕方をしています。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"やっぱり今の状況を考えて、迫っていかないといけないと思うんですけれども、その辺はいかがですかという質問です。こういう方に対して、どういう対策をしているのか、答えるよう求めました。","respondent":"伊勢総務課長、久保田行財政改革担当課長","answer":"例えば特別区人事・厚生事務組合の中の費用の内訳で幾つかあるんですけれども、その中で、例えば共同研修というのがありますけれども、この辺の見直しなども、具体的に申し入れをしています。継続して対応していきたいと考えていますが、民間の場合は、取りやめるという事業者もいると聞いております。","id":"exchange-025"},{"speaker":"稲川委員","kind":"確認","question":"まず１点は、ちょっと確認のために、教えてください。平成２２年度の予算では桁数がまた増えて、１億円の規模になっているんですが、なぜか、その辺説明を求めました。","respondent":"矢部生活安全担当課長","answer":"開始につきましては、条例の施行されました平成１５年１０月から進めている事業です。２人１組で、これも指定駅以外の２０駅を、１０駅ごとに交互ということで入ってもらった事業です。","id":"exchange-026"},{"speaker":"稲川委員","kind":"質問","question":"それからお伺いしたいのは、その警備員なんですが、警備員にする必要性があるのか。ここは見直しをするべきではないかと思うんですが。","respondent":"矢部生活安全担当課長","answer":"平成２１年９月から平成２２年３月までということで、２人１組、２組で回っていただいております。実施したところ、オレンジ色のジャンパーに「歩きたばこはやめましょう」というたすきをつけてもらったシルバー人材センターの方にお願いしています。","id":"exchange-027"},{"speaker":"稲川委員","kind":"意見","question":"３年前、４年前に比べれば、ポイ捨ての数が減っているんですよね。減っているのは、品川区の取り組みなのか、それとも、喫煙者のマナーの向上なのか、どちらだと思いますかとの意見を述べました。","respondent":"矢部生活安全担当課長","answer":"確かに、タバコの本数というか、ポイ捨ては減っていると思います。これは、どちらの取り組みかというと、やはり両方の力が一緒になって初めて減ってきているのではないかなと思っているところです。","id":"exchange-028"},{"speaker":"稲川委員","kind":"意見","question":"雇用創出ということもあると思うんですけれども、今後、この事業を見直していかなければいけないと思うんです。いつまでも、１０年後、２０年後もこういうことをやっていたら、あまりにもちょっとナンセンスな部分だと思うので、その辺をお答えくださいとの意見を述べました。","respondent":"矢部生活安全担当課長","answer":"この事業につきましては、現在、東京都の補助金をいただきまして、大々的にやっているところです。残りの今後の見直しにつきましては、一般財源の中で、できる範囲で努力をしていきたいと考えています。","id":"exchange-029"},{"speaker":"稲川委員","kind":"質問・要望","question":"それから、平成２０年度で約３億円の決算、平成２１年度、今やっているのは７,５００万円。２年間で３億７,０００万円を超える費用がかかっているんですが、何の工事というか、更新なのか、教えてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"きゅりあんの大ホールにつきましては、４期に分けて更新の工事を行う予定です。滑車等の更新、やはり非常に重いものをいろいろ吊って操作をしているということから、全体経費で大体３億２,０００万円ぐらいを見込んでおります。","id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"先ほど、ご答弁の中に、数年使っているとだんだん磨耗してくるとおっしゃっていましたが、大体何年周期なんですか。１０年周期なのか、２０年なのか、それとも５年なのか、５年ではちょっと早過ぎると思うんですが、その辺を。","respondent":"堀越文化スポーツ振興課長","answer":"使用頻度にもよりますけれども、一般的に言われておりますのが、ワイヤー等の部品交換は５年ごと、大規模な工事は１０年から１５年に１回行うというように聞いております。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書１１７ページの公有財産管理費に関連して、第一日野小学校跡のＴＯＣへの貸し付けについて、ちょっと伺いたいと思います。ちょっと伺いたいんですけれども、この決定に至る手続ですね、どういうふうな手続でやってきたのかということを伺いたいと思います。","respondent":"阿部経理課長","answer":"この場合は、普通財産の貸し付けということですので、その場合の方法について、ご説明いたします。今回の第一日野小学校跡の貸し付けにつきましては、今、委員ご指摘のように、鑑定士の評価を踏まえまして、貸付料を算定しているというものです。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"それから、評価に基づいて決定したというのは、その評価がそのままイコールでこの金額になっているのか、どうなのか聞きたい。それから、この金額について、鑑定士は、これは妥当だというふうに言っているのか、どうなのか、どうか尋ねました。","respondent":"阿部経理課長","answer":"その２年の中で減価償却しなければいけないということですので、当然、安くなることになっております。鑑定評価との関係ですけれども、先ほど申し上げたとおり、鑑定評価を踏まえましてやっておりますので、ほぼ同等の金額でお貸ししております。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問","question":"近隣、全部調べたわけではないんですけれども、私が見た感じでは、やっぱり屋根なしで月３万円というのが、大体こんな感じだったと思うんです。どうしてもこの値段が納得できないんですけれども、先ほどの質問とあわせて、お願いいたします。","respondent":"阿部経理課長","answer":"もう１点、それは貸付金額の重要な要素になると考えていますので、評価をしているです。３年から５年という形で見ますので、２年で減価償却をする場合は、これは当然です。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"もう一度、どういう手続で、どういうふうな評価でやってきたのか伺いたいと思います。そうすると、何の経費なのかということを伺いたいと思います。","respondent":"阿部経理課長","answer":"今回の貸し付けが２年ということですので、まさに臨時的な貸し付けであるです。もう１点、それを踏まえまして貸付料を決めている、まさに適正に貸付料を決めているです。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"意見","question":"そうしますと、今、駐車場部分は２年間という説明でした。そうして、１０年間貸すということになると、この規則から言ったら、どうなるのかということを聞きたいと思いますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"土日の混雑解消のために、暫定的にお借りしたいということで、２年の契約でお貸ししています。１０年間の契約をＴＯＣと結びまして、貸付料算定の上、お貸ししていきたいと考えております。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、この規則ではないことをやるということを考えているのか、どうなのか聞きたいと思います。適正な金額かどうか、貸し出すことが先行して決まっているのではないかと思うんですけれども、そこのところはどうなんか尋ねました。","respondent":"市岡総務部長","answer":"あくまでも２年の短期暫定貸し付けということで、この条件を鑑定の条件として、１０９万円という賃料を算出しております。やや、今回の暫定貸し付けと将来の話とが、今、若干ごっちゃになっているような気がいたしますので、ちょっと説明をさせていただきました。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、２年間ですよ。こうした行政需要との比較、なぜＴＯＣへの貸し付けが先になるのかということも疑問なんですけれども、あわせて、伺いたいと思います。","respondent":"阿部経理課長、久保田行財政改革担当課長","answer":"品川区公有財産管理規則の中で、臨時的な場合は２年間という定めがありますけれども、そのほかに、さまざまな貸し方を想定しております。それによって期間が、当然異なってくるというものです。地域経済の中心的存在だと認識しておりますので、こういったものを確保しながらやっていきたいと考えています、お貸し出しをすると。","id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"ちょっと確認なんですけれども、成果報告書の１２ページに、大体まもるっちの状況が出ております。何件かの協力者に通報すると思うんですけれども、そのやり方を、もう１回確認させてほしいと求めました。","respondent":"矢部生活安全担当課長、中山防災課長","answer":"協力者の研修会につきましては、先ほど言いましたとおり、１１月２５日、第３庁舎の６階の講堂で実施したいと考えております。その半径２００ｍ以内の協力者２０人を、その協力者にメールなり… 要綱につきましては、これまで実施してきた内容を全体的に明文化したものです。それから、新たにつけ加えたようなことはございません。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問・要望","question":"私もちょっと定かではないものですから、あれですけれども。今年度中なのでまだありますけれども、その辺が今後どうなっていくのか、ここをちょっとお知らせください。","respondent":"矢部生活安全担当課長、中山防災課長","answer":"平成２１年度に協力者に通報した事案ですけれども、ありません、０件です。今のところ、子どもの見守りシステムということで運用したいと考えております。やはり個人支援プランを、各町会レベルでいかに立てていただくかということが、一番重要なポイントだと思ってあります。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問・要望","question":"区が責任持って集めた名簿なわけですから、その先のところまで、個人情報を守りながらどうやって情報を提供していくか。見守るといったってできないわけですから、または障害を持った方たちの見守りみたいなことにもつなげていこうと取り組んでいる区があるわけです。","respondent":"宮地地域振興事業部長、中山防災課長","answer":"先ほど、年１回ぐらいしかきていないような気がするとおっしゃられましたように、きちんと行っているものが見ていただけてない場合などもあります。ここら辺も、今後の大きな取り組みの課題としまして… 個別支援プランの作成ということで、まずモデル町会を実施しまして、各町会へ広めていきたいと考えております。","id":"exchange-041"},{"speaker":"渡辺委員","kind":"確認","question":"私は、１１３ページ、国際交流推進事業、１１８ページ、区民まつり経費、１２０ページ、学校温水プール開放、この３点で伺ってまいります。そんなところをどうお考えか、まず伺いたいと思います。","respondent":"秋山協働・国際担当課長、中山地域活動課長","answer":"これについては、平成２１年度の予算でお認めいただきました、アジアの大都市との交流をどのように進めていくかという調査経費です。都市と交流していくのがいいのかということで、調査、委託を行ったという経費になってあります。 特に夏休みに入って１週目、２週目に集中するという関係上、なるべく重複のないような調整を図っているという状況です。可能な部分であれば、調整できる限り、情報を伝えてやっていきたいと思います。","id":"exchange-042"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今後、あるいは報告等が、何か取りまとめ等はどのように見ていくのか。あるいは、その取りまとめの中で、何かポイントがあれば、教えてほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"アジアの多様な交流の現況を調査いたしまして、今後の国際交流を進めるにあたっての検討資料とするということで、調査を始めております。こういう経済状況ですので、状況を見て進めていくべきではないかと考えているところです。","id":"exchange-043"},{"speaker":"渡辺委員","kind":"確認","question":"それから、１２０ページ、学校温水プール開放の項目から伺っていこうと思います。その辺、伺えればと思います。","respondent":"秋山協働・国際担当課長、堀越文化スポーツ振興課長","answer":"羽田空港の国際化等ありますので、今後の状況も含めて、周囲の状況を見ながら検討をしていきたいと考えています。アジアの地域を中心に検討を進めてきたものでございまして、アジア以外のものについては… そのほか、スポーツ協会等で行っている教室におきましても、１万８,０００人ほどの方がご利用いただいています。そちらのほうは、人数でいきますと、約８万５,０００人にご利用いただいているという内容です。","id":"exchange-044"},{"speaker":"渡辺委員","kind":"質問","question":"地域バランスだったり、利用者の年代層もすごく考慮がされていて、バランスが取れていると思います。ここでは４校となっていますが、これから推移していくのか、伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"施設のあり方については、やはり区全体のいろいろな施設に対する行政需要ですとか、そういったことを考えながら進めていかなければなりません。私どもといたしましては、そういった機会をとらえて、施設を有効活用していきたいと考えているところです。","id":"exchange-045"},{"speaker":"渡辺委員","kind":"意見","question":"それは一つ、大きな起点になるかと思います。今いろいろありましたが温水プールを例にとって、全般で考えたときの、施設整備へのポイントを幾つか挙げてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"多目的にご利用いただけるような、例えば人工芝化等を進めて、いろいろな種目に対応できるというような形です。トータルで、できる限り、生涯スポーツの場としてご活用いただきたいと考えているところです。","id":"exchange-046"},{"speaker":"高橋委員","kind":"質問・要望","question":"これまで行われた事業のレベルアップをするための財源というのでしょうか、そういうのは、どのような形でひねり出していくのでしょうか。そこをちょっと教えてほしいと求めました。","respondent":"金子企画財政課長","answer":"それに先立ちまして、最近は、隔年になりましたけれども、実施計画の策定も始めております。そういう意味で、実施計画、それから実際の予算編成を、秋から冬の段階にかけて煮詰めていくわけです。","id":"exchange-047"},{"speaker":"高橋委員","kind":"質問","question":"経常経費が、年間かかるというのはわかるんですが、その大枠をこのぐらいにするようにとか、あるいは、何％カットして要求するようにというような方針や基準が示されるのか尋ねました。","respondent":"金子企画財政課長","answer":"歳出に関してご説明申し上げたけれども、財政調整の見込みであるとか、歳入のほうは見ております。非常に多岐に渡って判断しておりますので、これ一つ重点的というのは難しい言い方になりますけれども、そういった、総合的に判断して編成しています。","id":"exchange-048"},{"speaker":"高橋委員","kind":"質問","question":"そして、三役の査定というのでしょうか、それで予算額が確定すると。今後、このように編成過程の可視化をするお考えはあるのでしょうか、お願いします。","respondent":"金子企画財政課長","answer":"いわゆる説明責任、でき得る部分について、できる限り公開していくというのが基本的な考え方かもしれません。これについては慎重に検討していきたい、あるいは研究していきたいという、今の段階です。","id":"exchange-049"},{"speaker":"高橋委員","kind":"質問","question":"さまざまな要素があって予算は編成されていくので、公開もいろいろな問題があると思いますが、慎重に検討されるということです。とすると、今すぐに知るとすると、品川区情報公開・個人情報保護条例に基づいて情報公開を請求するという方法はいかがか尋ねました。","respondent":"金子企画財政課長","answer":"私ども、これまで行ってきた予算編成というのは、あくまでも内部的な意思決定の過程と考えておりますので、現在の段階では、情報公開にはなじまないものと考えています。","id":"exchange-050"},{"speaker":"高橋委員","kind":"質問","question":"なじまないということですね。それは、第８条の非公開情報に当たるということでよろしいか尋ねました。","respondent":"金子企画財政課長","answer":"委員ご指摘のとおりだと思います。意思決定前の情報ですので、これは非公開情報であると、考えてあります。","id":"exchange-051"},{"speaker":"高橋委員","kind":"意見","question":"意思決定前の情報ということで、非公開情報。例えば第９条か、それを除いて公開することができるという部分があるんですが、そういう部分は種分けできませんかとの意見を述べました。","respondent":"金子企画財政課長","answer":"先ほど申し上げました意図は、部分部分ではなくて、トータルとして、あくまでも意思決定過程のものですから、全体として非公開と考えています。","id":"exchange-052"},{"speaker":"高橋委員","kind":"質問","question":"そういうものを説明するという意味においても、予算編成過程を、何らかの形で見える形にしていく方策をお願いしたいと思います。事務事業評価については、一言、どのような扱いをしていくのか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"事務事業評価につきましては、評価が終わって、作業が終わった段階で、公開はしたいと考えておりますので、そのときには、議会のほうにもご報告をさせていただきたいと考えています。","id":"exchange-053"},{"speaker":"井上委員","kind":"提案","question":"広報広聴課長と確認をさせていただきましたので、決して古いデータを使っているわけではないということをご理解ほしいと求めました。そのことについて、広報広聴課の見解を伺いますとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"情報公開の運営にあたっては、各事業部長と部長職の方々が判断、決定を下すという仕組みで運営させていただいているところです。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"決算書を確認すると、この間の１月から３月は、委員報酬が支払われていたんだろうと理解をしました。９月の新聞でもいろいろと報道されているように、品川区には厳正に対処してほしいと求めましたけれども、見解を伺います。","respondent":"早津選挙管理委員会事務局長","answer":"全国的に見れば、そういうのもあるということを、ご報告いたしておきます。たまたま病気で休まれていても、減額するというような規定もございませんので、そのまま支給しているというのが実態です。","id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"次は、区政アドバイザー会議についてお伺いいたします。１２人の委員ということで、それから、その決算額の内訳を説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"決算の内訳ですけれども、１５０万円ほどありますけれども、そのうちの１３０万円ほどが委員の報酬費です。残りの金額につきましては、テープの反訳代、または食糧費、あとは郵送費等の内訳になってあります。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"でも、地方自治法第２０３条の２の４項では、その金額と、その支給方法は条例で定めなければならないとなっているかと思うんです。任期ごとの委員会のときに、この報酬額は決定されると伺ったと思うんですが、これが条例で決めていかなくてもよいのだという根拠を説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"こちらの区政アドバイザーにつきましては、任意の諮問団体ですので、その任期の冒頭に、それぞれ委員のメンバー、また報酬額等を決定して、決裁を取っているです。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"任意の会ということが、どういうことなのか、ちょっとわからないので、これはまた研究をしたいと思います。この区政アドバイザー会議は、２００４年の６月に初会議が開かれて、今年度、４期目を迎えるんですけれども、改めて、その成果をお伺いいたします。","respondent":"久保田行財政改革担当課長","answer":"事業継続計画ということで、大学やそれぞれの専門分野でどういった取り組みが必要かといったものを、それぞれ高所な見地からいただいたです。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"そういうお考えということで、見直しも検討されるおつもりがあるのか、ちょっとその辺をお伺いいたします。","respondent":"久保田行財政改革担当課長","answer":"区政アドバイザー会議の設置目的につきましては、区長の政策形成を支援するといったところで、取り組んでいるところです。常に見直しを行っているといったところですので、例えば開催回数等につきましても、それぞれの状況に応じて見直しを常に図っているです。","id":"exchange-059"},{"speaker":"井上委員","kind":"提案","question":"その専門職の方々のいろいろなことがあるかもしれませんが、ぜひ、費用対効果というところも検討の素材にしていただきたいと要望します。公募の状況がどうだったのかということと、どういうところが評価されて決定されたのかということを、お伺いしますとの意見を述べました。","respondent":"秋山協働・国際担当課長","answer":"私どものほうで設定をいたしまして、八潮におけるコミュニティレストランの運営をしていただける方を公募したです。手を挙げていただいた団体が１団体ありまして、２月を予定をしておりますが、営業をしていただくということで決まったものです。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"利益を求められているというところでは、ハードの部分でどうかというと、担い手の方たちはいろいろとアイデアがあろうかと思うんです。そういったことがうまく協議されているのか、どうか、現状をお伺いします。","respondent":"秋山協働・国際担当課長","answer":"ハードの部分については、区が用意をするということで、こちらのほうで用意をしている段階です。区のほうで用意をする予定ですので、今、当該団体と協議をしている最中です。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"今回のこの事業は、ほんとうに区民と行政の協働事業として、ぜひ成功事例になるようにご尽力いただきたいと要望しますので、お願いいたします。１０年前の議事録を確認したら、９８％を超えている今の状況をどのように思っていらっしゃるのか、見解を伺います。","respondent":"阿部経理課長","answer":"９８％がどこから来た数値か承知はしておりませんけれども、私の手元に持っているのは、制限付一般競争入札ですけれども、落札率が９４.４％です。この落札率については、適正なものだと考えています。","id":"exchange-062"},{"speaker":"山路委員","kind":"質問","question":"１点目ですが、品川区でまだいろいろ検討されていると伺っておりますが、ぜひ奨学金を利用したいという方がいらっしゃるんです。そして、奨学金制度を借りて、かなり歴史も古くなってきたんですが、回収率はどのぐらいであるのか、これについてお伺いいたします。","respondent":"小林青少年育成課長","answer":"平成１７年度、区民の高校への進学に対してどういうふうに役割を分担していくべきなのかということで、制度の詳細を検討しています。平成２１年度の変換率は５２.４％、平成２０年度は６１.５％と、若干低下傾向で推移しています。","id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"現場でお母さん方にお話をお伺いしますと、品川区の奨学金というのは、今までも利用する方に非常に役立っていると。現実の生活の上で必要な方もまだまだありますので、ぜひ、品川区は品川区なりに続けていただきたいことを要望するものです。","respondent":"小林青少年育成課長","answer":"今年度１年間、また一歩進めて拡充されておりますので、その適用関係等も含めて検討してまいりたいと考えています。その生活の状況に応じて回収を進めておりますので、ぜひ、それぞれの生活の状況を踏まえながら粘り強く対応してまいりたいと考えています。","id":"exchange-064"},{"speaker":"山路委員","kind":"質問","question":"２３区でも、品川区が一番多いという、非常に気になるお話がありました。昨年も質問いたしましたが、本年度の振り込め詐欺の現状はどのようになっているか、お伺いいたします。","respondent":"矢部生活安全担当課長","answer":"約５,４００万円という額でありまして、これからも６０歳以上の高齢者には、振り込め詐欺の注意喚起をしていきたいと思っているところです。架空請求が９件、融資保証金詐欺が１件で、今年度発生しておりません。","id":"exchange-065"},{"speaker":"山路委員","kind":"質問","question":"お互いに声をかけ合って、チラシを配って啓発しているのにかかわらず、まだこういう高い数字のオレオレ詐欺事件がある。発想の転換をする必要があると思いますが、これについては、今後、どのようにお考えか尋ねました。","respondent":"矢部生活安全担当課長","answer":"生活安全サポート隊のパトロールカーによって、巡回しているときに、広報活動をしたりしています。やはり各警察署との連携も非常に重要になってきますので、今後とも情報交換をしまして、広報活動を推進していきたいと思っています。","id":"exchange-066"},{"speaker":"山路委員","kind":"質問・要望","question":"電話がかかってきて、ただ聞くだけではなく、反発するので、かけた人がそこでたじろいでしまうと。は審議会等で徹底して、高齢者が黙って聞かないように、高齢者に伝えていただくことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"山内委員","kind":"質問・要望","question":"それから、１２７ページ、まずはこちらの選挙費のほうからお伺いをさせてほしいと求めました。いわゆる参加をしてもらうという働きかけはしっかりと行っていく必要があるかと思うんですけれども、そのあたりを、お伺いさせてください。","respondent":"早津選挙管理委員会事務局長","answer":"さしあたり、選挙管理委員会として考えておりますのは、前回の選挙以上の投票率というのが直近の目標数値になろうかと思います。２３区で、単独選挙で行われたのは、この後、新宿区で予定されておりますが、参議院選挙の前に中野区で行われました。","id":"exchange-068"},{"speaker":"山内委員","kind":"質問・要望","question":"それから、掲示板の考え方について伺います。そういったところは設置が比較的しやすいといったことも考えられると思うんですけれども、その辺の考え方、ちょっと説明を求めました。","respondent":"早津選挙管理委員会事務局長","answer":"有権者が１万人を超えると９枚というようなことになりまして、品川区では、４３カ所の投票所がありますが、現在、掲示板は３４６カ所あります。","id":"exchange-069"},{"speaker":"山内委員","kind":"質問・要望","question":"私も区民委員会に所属しておりますので、以前、お伺いさせていただいたことがあります。６割に満たないといった数字を、そういったものをどういうふうにお考えなのか、まずはその辺をちょっとお伺いさせてください。","respondent":"中山地域活動課長","answer":"６割に満たないと申し上げたとすれば若干、約６割であるということは申し上げていたつもりなんですけれども、正直あります。一人でも多くの方が入り、１００％に近づくように、区としても支援していきたいと考えております。","id":"exchange-070"},{"speaker":"山内委員","kind":"質問・要望","question":"私ども自民党から要望させていただいた中で、自治会に、行政のほうにも協力をいただいた過去があります。その辺の品川区の考え方というか、もしあれば、教えていただきたいと思うんです。","respondent":"中山地域活動課長","answer":"町会・自治会を基本に、１３地区のいわゆるコミュニティブロックをベースに、まず活動を基本にしております。ただし現状だけでいいのかということも十分に考えながら、よりしっかりした仕組みのありようについては、考えていきたいと考えています。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"決算説明の中でも、繰り返し不断の行革による健全財政が強調されておりますけれども、現在の職員雇用形態の全体像がどうなっているのか、伺います。２０１０年４月１日現在の常勤職員数、それから非常勤職員数、人材派遣が何人か、臨時職員数、それぞれ説明を求めました。","respondent":"榎本人事課長","answer":"今年の４月１日現在ということですけれども、まず常勤職員数ですが、定員管理調査のほうでいきますけれども、２,６４３人。非常勤職員が１,０２１名、４月１日というところでは統計を持っていないのですけれども、月当たり大体３０人から４０人ぐらいというのが平均値です。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいんですが、品川区の財調算定人数は、今年の４月１日で何人なのか。そのうち、保育園の部門の人数は何人か尋ねました。","respondent":"榎本人事課長","answer":"今年４月１日現在の財調算定人員は２,６２１名で、実人員数より２２名下回っております。すみませんけれども、まだ細かい内訳等、基準等がまだ手元にきておりませんので、その部分は、ちょっと答えられません。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"保育園の直近の財調算定人数、このぐらいの業務量だということで、東京都が財調で定めている人数があるわけですよね。その内訳、直近の数字でもいいので、説明を求めました。","respondent":"榎本人事課長、金子企画財政課長","answer":"保育士の人員数が６６８名といった形です。これには育児休暇等を含んでおりますけれども、実際の人数としては、そういう形です。 平成２１年４月１日現在の財調人員が、先ほど、人事課長が答弁申し上げたとおり、旧基準でありますので、これで人数を計算しますと、８７１人です。これは保育士だけではなくて、保育所の人数という数字です。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"それから、契約期間は、何年になるのでしょうか。一時的や臨時的な業務に限定して行われるべきものであって、派遣保育士を保育園に入れている考え方も、お伺いします。","respondent":"吉岡保育課長","answer":"それから、契約は１年間の契約ということです。単価については、ちょっと今、手元に資料がございませんので、申しわけございません。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"考え方です、お伺いします。派遣保育士を常用的に１年間通してそこに充てるというのは、そういった点も含めまして、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問","question":"１年間の契約期間を超えた派遣保育士は、どうか、お伺いします。それぞれの保育園で、こういう実態というんですか、育休代替以外の派遣の保育士はいないということなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"派遣を常用的な労働に充てないで、充てることは禁止されているわけですから、きちんと正規の職員でしっかりと雇用して充てるべきだと思うんです。１年契約を超えた派遣の人が翌年働けないという状況だと、くるくる変わってしまうと思いますし、そこら辺の状況とあわせて、お考えをお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"安藤委員","kind":"確認","question":"雇われている派遣保育士は、育休か、病欠の代替にしか使っていないということなんですか。もう一度、そこら辺は確認させてください。","respondent":"榎本人事課長","answer":"人材派遣を使うというのは派遣法に定められていますので、その理由の中で使っているというものです。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうことを確認させていただいたのであれば、派遣の方が入って、その派遣の方は１年しかいられないわけですね。子どもにとっても、働く人にとっても、それから現場にとってもしっかりと働けるような環境をつくっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"堺委員","kind":"確認","question":"それから、１１３ページの職員研修費に関連いたしまして、確認をしておきたいと考えています。平成２１年度決算時期においては、１７８名採用となっておりますけれども、ちょっと確認をしておきたいと思うんです。","respondent":"榎本人事課長","answer":"ここ三、四年の採用状況ですけれども、平成１９年度が、全体の育児休業の任期付も含めまして９０名、それから、平成２０年度が１２０名、平成２１年度が１２７名、平成２２年度が１９１名ということで、平成２２年度は保育士の関係で大幅増になっているです。","id":"exchange-081"},{"speaker":"堺委員","kind":"提案","question":"今年８月、新卒という考え方を、卒後３年も新卒というとらえ方でいいのではないかということを提案をしているわけです。２３区の職員の採用の受験資格というんですか、我々はその辺の理解をどうしたいいのか、ちょっと教えてほしいと求めました。","respondent":"榎本人事課長","answer":"今、委員おっしゃられたように、Ｉ類の２３区の採用試験につきましては、国籍と年齢要件が受験資格の主な要件になっております。２８歳未満であればということなので、大学卒業後、最大６年ぐらい勤務経験がある方でも受けられるというのがＩ類の試験の現状です。","id":"exchange-082"},{"speaker":"堺委員","kind":"確認","question":"さっき申し上げた、同等の資格があることを人事委員会が認める人ということですから、そういう理解でいいんですか。ちょっとその辺、もう１回、確認をしておきたいんですが。","respondent":"榎本人事課長","answer":"やはり年齢要件という形になりますので、高校卒業だけの方でも、年齢が年齢要件に達していれば受験資格があると考えております。ですから、III類とＩ類という年齢要件だけでの受験の制度となっております。","id":"exchange-083"},{"speaker":"堺委員","kind":"質問","question":"それなりの経験を経た人が新たに採用されてくるわけですから、非常に重要なパワーというのですか、人材ということになるんだろうと思うんです。その辺を、区はどのように検証されているのか、ちょっと教えていただけますか。","respondent":"榎本人事課長","answer":"その中で、特に民間企業経験が８年以上、もしくは４年以上ということなので、かなり実務に精通しているという形が挙げられます。それぞれの課の専門的な実務にすぐにつける、即戦力として活躍できるということで、各所属長からは評価をいただいているところです。","id":"exchange-084"},{"speaker":"堺委員","kind":"質問","question":"９月１７日の「都政新報」で、ということで、そういう形で研修の一環として行われているように思うんです。徴収率がいいですから、考え方として、いかがか尋ねました。","respondent":"榎本人事課長","answer":"徴収という部分ではやっておりませんけれども、品川区の場合には、清掃の体験研修ですとか、福祉施設での体験研修等をやっているところです。","id":"exchange-085"},{"speaker":"阿部委員","kind":"質問","question":"そして１１９ページ、１２８ページの農林業センサスについて、お伺いします。ないものの統計に約２８万円かかるとは、どういう仕組みなのかなと思いまして、伺います。","respondent":"阿部経理課長、中山地域活動課長、堀越文化スポーツ振興課長","answer":"まだ検討はしておりませんけれども、地球環境への影響をなるべく少なくするという意味では、有効な手段だと思います。私は聞いているところがありますので… こういうことのありようについてもしっかりと考えていきながら、事業の効率としても上げていきながら、交流を進めていきたいと考えております。したがって… 芸術祭は始まったばかりですので、トータルで、新しいあり方、美術のほうについても検討していきたいと思っています。","id":"exchange-086"},{"speaker":"阿部委員","kind":"質問","question":"貸しスペースの場所も大切ですから、それはそれで持っていくべきであると考えていますので、お考えを伺いたいと思います。これはどこのコンサルタントに頼んで、報告書というのは、どういう形で出てきているんか尋ねました。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"ですからこそ、芸術祭の中でもいろいろな民間の美術館とも連携をして、事業として全体の中で枠組みに入れてきたというような経過があります。いろいろな発信のあり方について検討していると聞いていますし、民間の美術館との連携ですと… アジアの大都市との交流ですけれども、委託先は三菱総合研究所です。発展していくアジアとの交流も進めていくことが必要です、ということが、三菱総合研究所からの調査書には書かれているところです。","id":"exchange-087"},{"speaker":"阿部委員","kind":"質問","question":"アジアとの交流なんですが、報告書は何ページぐらいかということも、さっき伺ったと思うんですけれども、教えてください。もし今、お手元にあるのでしたら示していただいても構わないんですが。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"どういった形がフレームとして考えられるかということで、一義的には、文化振興事業団の中で検討する。我々のほうとしても、いろいろ協議というか、今、お話があったことを伝えたいと考えているところです。考えられるアジアの各都市の状況であるとか、その内容の報告を受けておりますので、総ページとしては３００ページぐらいのものにはなっております。","id":"exchange-088"},{"speaker":"伊藤委員","kind":"確認","question":"そのことの確認をお願いしたい。だから、そのことについての確認を、改めてお願いいたします。","respondent":"早津選挙管理委員会事務局長","answer":"ただいまのは、選挙期間前に個人名のたすき、それから、選挙期間中に個人名ののぼり旗、いずれも、公職選挙法違反の疑いが強いかと思います。これについては、捜査を担当する警察のほうの所管ということになりますので、念のため追加します。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問","question":"やっぱり同じルールにのっとって選挙をやらないとおかしいと、だれもが思うわけですよ。だから、そういうことがもしこれから先にあった場合に、我々はどうしたらいいんですかということを、再度、お答えください、お願いします。","respondent":"早津選挙管理委員会事務局長","answer":"そのようなことのないように、選挙管理委員会としてもいろいろＰＲもいたしますし、いろいろな機関も、そのようにしているかと思われます。選挙管理委員会として対応できることはいたしますし、警察のほうで対応していただくとか、そういうような形になろうかと思われます。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問・要望","question":"午前中にも、いろいろ質問がありました。何かしら要望していくとか、国の仕事なんですから、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"やはり国が主体となって取り組むべき事業だと考えておりまして、それに協力をしていくという形で、これまで取り組んでまいりました。","id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"テレビをどうこうするかという話ですから、最も身近な品川区なり、行政が対処していかざるを得ないと思うんです。これは２３区、総務省に対して言っていくお考えがありますか、答えるよう求めました。","respondent":"久保田行財政改革担当課長","answer":"国のほうで、チューナーとアンテナ工事の設置の助成をしてまいりましたけれども、今度は非課税世帯まで拡大をする予定だと聞いております。いろいろと要望等を伝えていく機会もありますので、そういったところを活用しながら、さらに進めていきたいと考えています。","id":"exchange-092"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、品川区役所の代表電話番号から、この番号につなぐことはできませんかという確認をひとついただきたい。特に三つの課にまたがる事業ですから、一つの情報をどういうふうに分析していくかという仕組みを、確認しておきたいと思います。","respondent":"中山人権啓発課長","answer":"緊急対応のケースの振り分けということになりますが、子育て支援課、これまでもこうした虐待の対応をしておりまして。その中で、ご連絡いただいた通報の連絡票に基づいて、緊急度の判断から、情報収集、そして対応というところで、一貫した対応を進めているところです。","id":"exchange-093"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もう１回確認の答弁をいただきたいんですけれども、そういうふうなことについて、どう連携していくかということが一つ。システムでできるかどうかということについての確認をいただかないといけないと思いますので、再度、ご答弁をお願いいたします。","respondent":"中山人権啓発課長","answer":"医師会との連携、事業の説明と、ご協力のお願いをしていくつもりです。現場の子育て支援課、間違いなく対応ができるように、しっかりとやってまいりたいと考えています。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"地域の方が文化センターはどこにあるんですかと結構聞かれるらしいんです。人数が多過ぎるので、少なくしても運営できるのではないですかというご意見を聞きましたので、それについてのお考えをお聞きします。","respondent":"金子企画財政課長、中川原広報広聴課長、秋山協働・国際担当課長、早津選挙管理委員会事務局長","answer":"それに対応するのが、８７ページの下から８行目の企画調整費のところで、このような表記にしているものです。ほかのところにおきましても、大体… お尋ねの五反田の施設につきましては、現在、実踏を２回行いまして、適地、候補地を挙げました。合計６カ所について、調整をしながら… 事業執行の一つの方法とは考えておりますけれども、それから、区と区民との協働を進めていくという方法をとっているところです。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"備考欄ですが、ここからここに行ったというのはわかるんですが、どういうものがどこに行ってという、そういう仕組みがあるんですか。ですから、そういう方法は考えられるのではないかということで、いろいろ考えていただきたいと思っています。","respondent":"金子企画財政課長、久保田行財政改革担当課長","answer":"目を越えるということから、決算書には、改めて明記するという形で表記させていただいているものです。ＴＯＣのバスのご質問ですけれども、区内にはＴＯＣ以外にもいろいろなショッピングのバス等も走っていると思います。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"款の中で終結するものなのか、どこからどういうふうに持ってくるものなのか、そういう仕組みがあるんですか。何か規則があって、その中でのやりくりをしているのかどうかというところを聞きたいんです。","respondent":"金子企画財政課長","answer":"ただ、もちろん、予算の仕組みの中で、款、項を越えることはなくやっていくのが、私どもの基本的なルールです。ちょっと細かい説明になると、非常にたくさんになってしまいます。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"我々区議会議員の責任でもありますが、区の施策、対策についても積極的に賛意を示していないという考え方もできるのではないでしょうか。実際にこういう結果が出て、どうなんでしょうか、答えるよう求めました。","respondent":"久保田行財政改革担当課長","answer":"選挙の投票率というご質問ですけれども、私ども、投票率云々ということではなく、区民が求める施策を堅実に、着実に進めてきたです。それに取り組んでまいりましたし、今後もそういった形で着実に推進をして、実現をさせていきたいです。","id":"exchange-098"},{"speaker":"須貝委員","kind":"意見","question":"でも、実際、１.５％下げようとしている。この実態について、ちょっとご答弁を、ご見解を説明を求めました。","respondent":"榎本人事課長","answer":"その５.５％というのは、全体の平均値のマイナスですけれども、要は似たような職業、もしくは職種、役職、区分、そういうものを比べて、どうするか。あくまでも、それは基準が違うということで、いろいろな調べ方があるのかなと考えています。","id":"exchange-099"},{"speaker":"須貝委員","kind":"確認","question":"ということは、たかだか１.５％しか下がっていないから、区内経済は、区民の所得は大して下がっていないという解釈になるのではないですか。そういうところにメスを入れていくべきではないかと思うんですが、その辺について、ご見解を説明を求めました。","respondent":"榎本人事課長","answer":"比べ方のもとが違うので、なかなか難しいのですけれども、国税庁のほうの調査は、日本全国での平均値を出しております。そういう判断はなかなかできないかなと考えていますし、６６１万円とかも出ていますので、なかなか細かい調査分析はできないかなと考えています。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問","question":"今、お話がありましたが、でも、実際に、ではほんとうにそうなんですかと。皆さんの生活も大変だから、だからいっぱいさまざまな支援をするんだと、そうではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"若林委員","kind":"質問","question":"１１９ページのシルバー大学について、お聞きいたします。この事業の目的を伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"シルバー大学という形で、学習事業を体系化しまして、幅広い学習事業を提供しているものです。班別活動等も取り入れまして、学生間の交流も図っている、これを目的としている事業です。","id":"exchange-102"},{"speaker":"若林委員","kind":"質問・要望","question":"どのように歩んでいただきたいかというようなところの、目的としてもう１回お聞きしたいと思うのが、一つあります。３年目のいきいきコース、これは単年度のコースになるのでしょうか、ここら辺をお聞きしておきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"コースの概要についてはご説明しますが、今度は学ぶ側から教える側という形で、そういったご活躍もいただいているところです。２７講座、このような構成が、シルバー大学の構成になっております。","id":"exchange-103"},{"speaker":"若林委員","kind":"確認","question":"平成１９年度、平成２０年度の決算の資料では、どうかということの確認。足かせみたいなところが出てくるのか、どうかというのを、ちょっとお聞きしておきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"どのような学習を進めるのかといった観点、目的意識を持つということからも、そういった成果を得るための工夫を図っているものです。そういった部分、実際の高齢者対策の目的に照らして妥当であれば、特に問題ないと、今のところは、そういう状況で運営しています。","id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"９名体制で四つの事業をやられておりますけれども、果たして今十分なのかという疑問に、一つお答えほしいと求めました。よりレベルアップを望む方々、高齢者のニーズにこたえる見直しというのは、どうか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"民間の企業とか、ＮＰＯのお手伝いをいただいて、全体の中でできるだけ効率的に行っていきたいと思っています。さまざまいろいろな教育機関等とも連携しながら、現在も検討していますし、常に検討を続けていきたいと考えております。","id":"exchange-105"},{"speaker":"須藤委員","kind":"質問","question":"１２７ページ、選挙費、１１９ページ、文化スポーツ振興費、１１２ページの職員給与費、退職手当について質問します。それから、港区などは首長だけでやったときに、どのぐらいの数字で結果が出たのか、ということを聞かせてください。","respondent":"早津選挙管理委員会事務局長","answer":"そういう方にＰＲをするのが、なかなかつぼを得ているのではないかというような考え方から始めたもので、２カ月前から始めたことがあります。目黒区は２７％台というような実績だったと記憶しています。","id":"exchange-106"},{"speaker":"須藤委員","kind":"質問・要望","question":"来年春にまた統一地方選挙がありますので、今後も、しっかりとした広報をしてほしいと求めました。どういう対処をしますということを、規則は規則で守っていこうという指導をしていくんですから、いかがか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"我々としても、あらゆる機会をとらえて、ＰＲ活動には努めたいと考えています。選挙管理委員会としても精いっぱいのことを行いますけれども、そういう面での制約があるということは、お酌み取りいただきたいと考えています。","id":"exchange-107"},{"speaker":"須藤委員","kind":"質問","question":"先生方、弟子の方たちも非常に気合が入って、やりましたというお話を伺った。この辺の１,１００万円ぐらいを、平成２１年度はどういう切り分けでやられたのか、説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"一体的に実施して、相乗的な効果による盛り上げを図り、区内全域での取り組みを図っていきたいです。こういう新たな取り組みという方向性も打ち出しておりますので、区のほうといたしましても、しっかりと支援していきたいと考えています。","id":"exchange-108"},{"speaker":"須藤委員","kind":"質問","question":"国体を目指しての意味で、近年こういう数字なのか、今までもずっときている形なのか。４事業、高齢者スポーツの普及で１事業、説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"平成１９年度から平成２１年度まで、今年の３月、そういった形で進めているところです。高齢者スポーツの普及事業は、体育指導委員会のほうで行っておりますウォーキング事業の中身です。","id":"exchange-109"},{"speaker":"須藤委員","kind":"意見","question":"それから、この１年、２年で、やはり部課長クラスの方々が退職されるという年齢になってきていると、そのあたりをどういうふうにもっていくのかと。責任だけ残っては嫌だとやらないのか、そのあたりはどういうふうになっているのか、お聞かせ願いたいと思いますとの意見を述べました。","respondent":"榎本人事課長","answer":"フルタイム２４名を、人事委員会の給与の仕組みの中で、同じように入っております。逆にいくと、その配置ポストをどうするかということで、給与水準は同じという形で取り扱っているところです。","id":"exchange-110"},{"speaker":"須藤委員","kind":"意見","question":"平成２５年度からということですけれども、平成２５年まで待っていれば、二年をどうするのかなと。これは品川区だけではなくて、東京都全体がそういう雰囲気になっていると思うので、そのあたりを説明を求めました。","respondent":"本間副区長","answer":"区民サービスの向上につながるという面もありますから、このような点等を総合的に考えまして、活力の維持に努めたい。統括課長、その後は私に任せろというような気概を持った管理職が続出するよう、区長の指示を仰ぎながら一生懸命努力をしてまいる所存です。","id":"exchange-111"},{"speaker":"川西委員","kind":"質問・要望","question":"１１３ページ、新型インフルエンザ対策、同じページの職員研修の中の研修支援、１２５ページの防災行政無線、３点、伺います。１４４台、声がどのように挙がってきているのか、伺います。","respondent":"伊勢危機管理室長、榎本人事課長、中山防災課長","answer":"医師会との関係ですけれども、保健所が医師会と連携しながら、あるいは、情報を流しながら対応してきたところです。全般的には、広報の号外をはじめ… 去年度までで２名合格、それから社会福祉士につきましても２名合格、それから公共政策大学院も修了者１名ということで出ております。… 私どもやっておりますので、申し出ていただければ、そのようなことをしてまいりたいと思っています。","id":"exchange-112"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、庁内の横のつながりといいますか、そういうものを、今後、考えてほしいと求めました。これは要望で結構です。","respondent":"中川原広報広聴課長、榎本人事課長","answer":"ほぼ同じぐらいかと思います。発信が本部で決まりますと、その都度、流しているような形になりますが、ちょっと確認させていただきたいと思います。 自主研究グループですけれども、グループ数としては、６グループということで、数は変わっておりません。別のグループができてきたりとかして、大体６グループぐらいが、平均して活動している状況です。","id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"区長は、さきの選挙が終わった後に随所で、選挙中もだったでしょうか、長期基本計画について粛々と進めていくと、そういうお話をされておられました。笑顔輝くとは、どういうことを意味しているのか、まずそこからちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"住み続けたいまちしながわの実現を目指すために進めていく、１０年間の行政計画ですので、毎日暮らしていけるような施策を展開していきたいと考えているところです。","id":"exchange-114"},{"speaker":"南委員","kind":"質問","question":"この選挙中に認可保育園２カ所をつくる計画を急遽掲げざるを得なくなった状況もあると、長期基本計画のこの部分で質問をしたいと思っているんです。その点について、改めて、ご見解を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"南委員","kind":"質問・要望","question":"この間の区の姿勢を伺っていると、どうもその辺については、そういうふうには思えないんです。したがって、長期基本計画のこの総務費の場面で、そういう質問をしてみましたので、ぜひ、答弁をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"鈴木委員長","kind":"質問","question":"その辺で、今の質問に対するご答弁は、理事者側としても、できないのではないかと思います。南委員、質問の形式を変えていただいた上で、今の内容ですと、ちょっとお答えができないと判断いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"南委員","kind":"質問","question":"先ほどから申し上げておりますように、〔「何ページなのか」と呼ぶ者あり〕長期基本計画の７６ページということを言っています。総務のところですからいいではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"質問しているんですけれども、ぜひ、質問を続けさせてほしいと求めました。ぜひ、委員長として計らってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"南委員","kind":"質問","question":"どういうふうな検討をしたのかと質問しているんですから、だってそうしたら、どこの款だってそういうふうになってしまうではないですか。どういうふうに検討してきたのかということを聞いているんですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"南委員","kind":"質問・要望","question":"長期基本計画に基づいて区政運営をしているわけですから、全然質問できない、こうだとかと狭めるということはおかしいと思いますよ。ぜひ、質問をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"南委員","kind":"質問・要望","question":"全庁を挙げて取り組んできたという点ですから、どこの問題でも、堂々と受けて答弁をしてほしいと求めました。ここのところで、区の一番基本的な区政運営をする長期基本計画のことを聞いているんですから、そんな制限をしないでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"鈴木委員長","kind":"質問・要望","question":"ページ数のご指定をいただいて質問をしていただくように、そこの部分を、私のほうからお聞きしたいと思います。南委員、その辺をお考えのうえで、質問を続けてほしいと求めましたが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"南委員","kind":"質問・要望","question":"どういう角度で策定したのかという質問をしているのに、させていただけないのは、甚だ私は残念です。そして、これからの審査にあたっては、区の基本姿勢のところですから、やっぱり枠を広げてやっていただけるように、配慮してほしいと求めました。","respondent":"鈴木委員長","answer":"今、最後に終わられましたが、私のほうは、あくまでも款別審査の中でのお答えだと考えています。一番最初の副委員長の説明の段階でも、ご指摘いたしておりますので、私は同じように運用してまいります。","id":"exchange-124"},{"speaker":"三上委員","kind":"質問・要望","question":"昨年の決算特別委員会でも、この件についてどうなっているんでしょうかということで、お伺いをしております。つけることができないという方について、今度は区民チャンネルも見れなくなるのではないかと考えるんですけれども、この点はどうお考えか尋ねました。","respondent":"榎本人事課長、阿部経理課長、久保田行財政改革担当課長、早津選挙管理委員会事務局長","answer":"今年２１名受講して、２年目の職員が受講しましたけれども、こういうものがあるということが目の前でわかるような形での研修で行いました。… １０月から新たに電気自動車をリースするということを始めまして、一部ソケットを直しましたけれども、そのリース用の充電をしております。… 品川区内の８４.５％の方につきましては、地上デジタル放送対応のテレビなり、地上デジタル放送が見られる状況にあると考えております。","id":"exchange-125"},{"speaker":"三上委員","kind":"質問・要望","question":"これは署名を求めて出された期間を見てみると、１０月２２日、１０月２５日と追加で署名が出されている。いかがか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"もし選挙期間中ということになると、署名活動の禁止とは別に、法定外の氏名の入ったビラを頒布したという可能性があるかもわかりません。条文は、ちょっと違ってくる可能性があるということになります。","id":"exchange-126"},{"speaker":"三上委員","kind":"質問・要望","question":"４月の選挙ということになれば、その時期はとてもではないけれどもやってはいけないという意識は、皆さんも持っているかもわからない。こういう時期に署名運動をやってはいけないんだという意識を持っていただくような啓発の仕方をやっていっていただきたいと、こう思います。","respondent":"早津選挙管理委員会事務局長","answer":"私ども、公正な選挙が実施されるように、あらゆる機会をとらえてＰＲ等に努めてまいりたいと考えております。","id":"exchange-127"},{"speaker":"松澤委員","kind":"質問","question":"第２款総務費、２項の地域振興費、４目の防災対策費、こうやって質問は入らなくてはいけないんです。消火ポンプのほうは安かったのかなと思いますけれども、その辺をお聞きしたいと思います。","respondent":"佐藤防災安全担当課長","answer":"今の金額が少なくなった点につきましては、荏原第二地区、荏原第三地区の地区総合防災訓練が、雨のために中止になったため、執行できなくなって、金額が少なくなっております。","id":"exchange-128"},{"speaker":"松澤委員","kind":"質問","question":"やはり即戦力というのでしょうか、このような訓練を子どもたちにしていくというのは、大変重要だなと思っているところです。そういう意味かと思いますけれども、中学生が参加していない地域をどのように考えているのか、お聞きしたいと思います。","respondent":"佐藤防災安全担当課長","answer":"平成２０年度、平成２１年度に配備した８校が、訓練を実施して参加する形態をとらせていただいております。今年度配備した中学校については、来年度、地区総合防災訓練に参加していただきたいと考えております。","id":"exchange-129"},{"speaker":"松澤委員","kind":"質問","question":"売りものになっているというのでしょうか、大変に見た目もきれいなんですけれども、区民消火隊の参加率ですね。どうか、その辺の参加率というものを、ちょっとお聞きしたいと思います。","respondent":"佐藤防災安全担当課長","answer":"全体は、数字としては、７割から８割と推測しているんですが、荏原地区については、まだ実施していない地区もあるんですが、実施予定ということで、ちょっと数字を挙げしますと、７７町会のうち５５町会が、Ｄ級ポンプ、Ｃ級ポンプの放水訓練を披露すると伺っております。","id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"ただ、今回、初めてみんなに話をして、２０年ぶりで参加したという町会がありました。しっかりとそれがわかっているのか、どうか、その辺をちょっとお聞きしたいと思います。","respondent":"佐藤防災安全担当課長","answer":"委員ご指摘のとおり、ポンプ隊が高齢化したということで、ポンプを返納したいという隊は、私たち防災課でも伺っております。消防団と連携して、個別にどういう理由ということをお伺いしながら、連携を図ってまいりたいと考えております。","id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"披露する機会がなかったものですから、やはり参加意識も高まったり、訓練日を設けたりすると思うんです。そのような手だてというものを考えていかなくちゃいけないと思うんですが、その辺、いかがお考えか尋ねました。","respondent":"佐藤防災安全担当課長","answer":"うまくいかなかったということにつきましては、中学校も含め、防災課では確認しております。消防団と連携して、ある程度目に見えてわかるようなマニュアル等を検討して、検討しております。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうすると、１週間、２週間前でも、もう準備しなくちゃいけない。区民消火隊ですから、こういうのは大事だからと行ったことですから、その辺のお考えを説明を求めました。","respondent":"佐藤防災安全担当課長","answer":"やはり地区総合防災訓練でＣ級、Ｄ級ポンプの隊がその場で披露するということを、地域防災計画で定めて実施しております。来年以降また、発表会を開催するにあたって、区として、できる限りの支援、協力をしてまいりたいと考えております。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"品川区にはほかにも消防署があるわけですから、品川、大井のほうにも働きかけるような努力をしていただければ助かると思います。その辺の決意を聞きたいと思います。","respondent":"佐藤防災安全担当課長","answer":"屋内消火栓の操法大会も実施しているので、今現在、そういう操法大会を実施するということは検討しないということを言っております。もしやる場合には、荏原と同様に、支援、協力をしてまいりたいと考えております。","id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/260957?Template=document&Id=1326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":114470,"voices":341}},{"id":"h22-20101102-8","meetingId":"h22-cm11","date":"2010年11月2日","dateIso":"2010-11-02","committee":"建設委員会","time":"午前１１時０２分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"１番目に、外環など首都圏３環状道路の整備の重点的な促進というのがうたわれておりまして、事前に確認できるのかどうかを伺います。","respondent":"松代都市計画課長","answer":"その中で決まったものが、今申し上げましたように、１時の大会等でお示しされ、それに賛同いただくという形になっております。その後、その決議案をもって各関係、例えば国土交通省だとか、そういったところに要請活動をすると、こういう段取りになっているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"少なくとも内容確認できないということなので、大会に参加してから内容を確認して、改めて参加できないということを私としては申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3994#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":1871,"voices":12}}]);
